INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C1','kor',3,2,'u5',2,'낱말을 다루는 힘 — 이 단원에서 배울 두 가지는 기준에 따라 낱말 나누기(낱말의 종류와 특징)와 국어사전 쓰기(낱말을 찾고 글 읽기)이며, 둘 다 낱말을 다루는 힘을 기르는 일임',ARRAY['[4국04-02]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C2','kor',3,2,'u5',2,'모르는 낱말을 만났을 때 — 글을 읽다가 모르는 낱말이 나오면 그냥 건너뛰지도, 한 낱말 때문에 읽기를 멈추지도 않고, 앞뒤를 살펴 짐작하며 읽은 뒤에 국어사전에서 확인함',ARRAY['[4국04-02]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C3','kor',3,2,'u5',2,'이름을 나타내는 낱말 — “이것이 무엇이다”의 ‘무엇’ 쪽에 들어가는 낱말(사물함·손잡이·계단·바구니)',ARRAY['[4국04-02]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C4','kor',3,2,'u5',2,'움직임을 나타내는 낱말 — “무엇을 한다”의 ‘한다’ 쪽에 들어가는 낱말(닦다·옮기다·두드리다·접다·심다)',ARRAY['[4국04-02]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C5','kor',3,2,'u5',2,'성질이나 상태를 나타내는 낱말 — “어떠하다”의 ‘어떠하다’ 쪽에 들어가는 낱말(비좁다·환하다·매끈하다·묵직하다)',ARRAY['[4국04-02]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C6','kor',3,2,'u5',2,'문장에 넣어 읽어 종류 가리기 — 낱말만 보고 외우는 것이 아니라 “이것이 ○○이다 / ○○을 한다 / ○○이 어떠하다” 틀에 넣어 소리 내어 읽어 보고 어울리는 쪽을 찾음',ARRAY['[4국04-02]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C7','kor',3,2,'u5',2,'모양이 닮아도 종류가 다를 수 있음 — ‘웃음’과 ‘웃다’, ‘잠’과 ‘자다’처럼 모양이 닮아도 하나는 이름, 하나는 움직임을 나타낼 수 있으며 둘 다 바른 말임',ARRAY['[4국04-02]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C8','kor',3,2,'u5',2,'낱말의 종류를 아는 쓸모 — 종류의 이름을 외우는 것이 목표가 아니라, 낱말을 보고 어떤 말인지 알아보아 기준을 정해 나누고 사전에서 찾고 하려는 말을 또렷하게 하는 데 씀',ARRAY['[4국04-02]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C9','kor',3,2,'u5',4,'바뀌는 부분과 바뀌지 않는 부분 — 접고·접으니·접으면·접어서에서 앞쪽 ‘접’은 그대로이고 뒤쪽만 문장에 따라 바뀜',ARRAY['[4국04-02]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C10','kor',3,2,'u5',4,'모양이 바뀌는 낱말과 그대로인 낱말 — 움직임과 성질·상태를 나타내는 낱말은 문장에 쓰일 때 모양이 바뀌고, 이름을 나타내는 낱말은 뒤에 붙는 말이 달라져도 낱말 자체는 그대로임',ARRAY['[4국04-02]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C11','kor',3,2,'u5',4,'사전에 대표 모양 하나만 싣는 까닭 — 닦고·닦으니·닦아서·닦았다 …처럼 낱말 하나에 모양이 너무 많아 다 실으면 사전이 몇 배로 두꺼워지므로 대표 모양 하나만 실음(틀린 말이라서·빠뜨려서가 아님)',ARRAY['[4국04-02]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C12','kor',3,2,'u5',4,'기본형 만들기 — 바뀌지 않는 부분을 찾아 ‘-다’를 붙임(닦으니 → 닦 + 다 → 닦다); 이렇게 만든 대표 모양을 기본형이라 함',ARRAY['[4국04-02]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C13','kor',3,2,'u5',4,'바뀐 모양은 틀린 말이 아님 — 기본형은 사전에 실을 때 고른 대표 모양일 뿐이며, ‘접어서’·‘닦으니’는 문장에 알맞게 모양이 바뀐 것이지 틀린 말이 아님(사전에 없다고 틀린 말이 되지 않음)',ARRAY['[4국04-02]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C14','kor',3,2,'u5',6,'나누기 전에 기준을 먼저 정하기 — 낱말을 여럿 놓고 나눌 때 가장 먼저 할 일은 무엇을 보고 나눌지, 곧 기준을 정하는 것임(낱말마다 정해진 칸이 하나 있는 것이 아님)',ARRAY['[4국04-02]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C15','kor',3,2,'u5',6,'기준이 바뀌면 결과도 바뀜 — 같은 낱말이라도 종류로 나누면 셋·셋·셋, 모양이 바뀌는가로 나누면 여섯·셋처럼 나뉜 칸의 수와 든 낱말이 달라지며, 그 까닭은 낱말이 아니라 기준이 달라졌기 때문임',ARRAY['[4국04-02]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C16','kor',3,2,'u5',6,'「잃어버린 것을 말하는 법」 내용 알기 — 물통은 처음부터 상자에 있었지만 그것을 가리킬 낱말이 모자라 찾지 못했고, 짝이 손잡이·뚜껑·겉을 하나씩 물어 주자 낱말이 떠올라 자세히 말할 수 있었음',ARRAY['[4국04-02]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C17','kor',3,2,'u5',8,'글자의 짜임 — 글자 하나를 첫 자음자·모음자·받침으로 나눔(손 → ㅅ · ㅗ · ㄴ)',ARRAY['[4국04-02]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C18','kor',3,2,'u5',8,'첫 자음자의 차례 — 국어사전은 첫 자음자 차례(ㄱ ㄲ ㄴ ㄷ ㄸ ㄹ ㅁ ㅂ ㅃ ㅅ ㅆ ㅇ ㅈ ㅉ ㅊ ㅋ ㅌ ㅍ ㅎ)로 낱말을 묶어 실음',ARRAY['[4국04-02]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C19','kor',3,2,'u5',8,'모음자의 차례 — 첫 자음자가 같으면 모음자 차례(ㅏ ㅐ ㅑ ㅒ ㅓ ㅔ ㅕ ㅖ ㅗ ㅘ ㅙ ㅚ ㅛ ㅜ ㅝ ㅞ ㅟ ㅠ ㅡ ㅢ ㅣ)로 봄 — ㅏ가 맨 앞, ㅣ가 맨 뒤',ARRAY['[4국04-02]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C20','kor',3,2,'u5',8,'받침의 차례 — 첫 자음자와 모음자가 같으면 받침이 없는 글자가 먼저 실리고, 그다음 받침이 있는 글자가 ㄱ · ㄴ · ㄷ · ㄹ … 차례로 실림',ARRAY['[4국04-02]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C21','kor',3,2,'u5',8,'첫 글자가 같으면 다음 글자 — 첫 글자가 같으면 두 번째 글자를, 그것도 같으면 세 번째 글자를 같은 방법(첫 자음자 → 모음자 → 받침)으로 봄 — 낱말의 길이로 정하지 않음',ARRAY['[4국04-02]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C22','kor',3,2,'u5',8,'모양이 바뀐 낱말은 기본형으로 찾기 — ‘찌그러졌고’·‘비좁으니’는 사전에서 그대로 찾을 수 없으니, 사전을 펴기 전에 기본형(찌그러지다·비좁다)으로 되돌려 찾음',ARRAY['[4국04-02]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C23','kor',3,2,'u5',8,'국어사전에 실린 여러 가지 — 국어사전에는 낱말의 뜻뿐 아니라 소리 내어 읽는 법과 그 낱말이 쓰인 문장도 함께 실려 있음(뜻풀이표가 아님 · 바뀐 모양이 다 실린 것도 아님)',ARRAY['[4국04-02]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C24','kor',3,2,'u5',10,'앞뒤를 살펴 뜻 짐작하기 — 앞뒤 문장을 살피고 아는 다른 말로 바꾸어 읽어 보아 뜻이 통하면 짐작이 가까이 간 것임(‘어귀’ — 처음 오는 사람이 들어오는 곳)',ARRAY['[4국04-02][4국02-01]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C25','kor',3,2,'u5',10,'짐작이 빗나갔을 때 — 짐작한 뜻이 사전의 뜻과 다르면 사전의 뜻으로 고쳐 알고 그 줄을 다시 읽음(글을 못 읽는 것도, 사전이 틀린 것도 아님); 사전마다 뜻풀이 말이 조금씩 달라도 뜻이 같으면 됨',ARRAY['[4국04-02][4국02-01]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C26','kor',3,2,'u5',10,'국어사전을 쓰며 글을 읽으면 좋은 점 — 「학교 안내도를 만드는 법」처럼 낱말의 뜻을 알면 걸리는 곳이 줄어 글의 내용을 정확하게 알 수 있고, 짐작을 확인하며, 아는 낱말이 늘어남(빨리 읽으려는 것이 아님)',ARRAY['[4국04-02][4국02-01]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C27','kor',3,2,'u5',12,'「단서 세 장」 — 낱말 하나를 정해 단서 세 장에 낱말의 종류·사전에서 찾은 뜻·낱말을 괄호로 비운 쓰인 문장을 나누어 적고 짝이 알아맞힘 — 낱말을 그대로 적으면 단서가 아니라 답임',ARRAY['[4국04-02]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C28','kor',3,2,'u5',12,'「내 낱말 공책」 — 생활하다가 뜻이 궁금한 낱말을 모아 낱말(기본형)·종류·사전에서 찾은 뜻·내가 쓴 문장을 적고, 국어사전에 싣는 차례로 늘어놓아 나중에 찾기 쉽게 함',ARRAY['[4국04-02]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C29','kor',3,2,'u5',12,'놀이의 목표 — 단서 놀이의 목표는 이기는 것이 아니라 단서를 보며 낱말을 헤아려 보는 것이며, 못 맞힌 낱말은 사전에서 함께 찾아봄',ARRAY['[4국04-02]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C30','kor',3,2,'u5',12,'‘ㄴ’ 소리가 더해지는 낱말 — 앞 글자에 받침이 있고 뒤 글자가 이·야·여·요·유로 시작하면 ‘ㄴ’ 소리가 더해져 소리 남(한여름 [한녀름] · 논일 [논닐] · 눈인사 [눈닌사]) — 쓸 때는 그대로 씀(기초 다지기)',ARRAY['[4국04-02](케이티처 l14 표기)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C31','kor',3,2,'u5',12,'뜻을 알아 두면 좋은 우리말 — 아우르다(여럿을 모아 하나로 만들다) · 북돋우다(기운을 더 나게 해 주다) · 여미다(옷깃을 바로 해 단정히 하다) — 셋 다 움직임을 나타내는 낱말(기초 다지기)',ARRAY['[4국04-02](케이티처 l14 표기)']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u5-C32','kor',3,2,'u5',12,'ㅘ · ㅚ · ㅙ가 든 글자 쓰기 — ㅘ(ㅗ+ㅏ) · ㅚ(ㅗ+ㅣ) · ㅙ(ㅗ+ㅐ)는 모음자 두 개가 붙은 것으로, 두 모음자가 어느 쪽에 붙는지 살피며 씀(관찰 · 참외 · 괜찮다, 기초 다지기)',ARRAY['[4국04-02](케이티처 l14 표기)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X01','kor',3,'u5',ARRAY['K3-2-u5-C2']::text[],'모르는 낱말은 그냥 건너뛰고 읽어도 글을 다 이해한 것이라고 여긴다','건너뛴 낱말 때문에 무엇을 놓칠까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X02','kor',3,'u5',ARRAY['K3-2-u5-C2','K3-2-u5-C24']::text[],'한 낱말이라도 모르면 읽기를 멈추거나, 모르는 낱말이 나올 때마다 멈추어 사전부터 찾아야 한다고 여긴다','먼저 끝까지 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X03','kor',3,'u5',ARRAY['K3-2-u5-C2','K3-2-u5-C25']::text[],'앞뒤로 짐작만 하고 사전에서 확인하지 않은 채 짐작한 뜻을 그대로 맞는 뜻으로 여긴다','짐작한 다음에 할 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X04','kor',3,'u5',ARRAY['K3-2-u5-C3','K3-2-u5-C4','K3-2-u5-C5']::text[],'이름·움직임·성질이나 상태를 나타내는 낱말을 엇갈리게 가린다','세 가지 틀에 넣어 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X05','kor',3,'u5',ARRAY['K3-2-u5-C4','K3-2-u5-C5']::text[],'움직임을 나타내는 낱말과 성질이나 상태를 나타내는 낱말을 섞어, ‘-다’로 끝나면 모두 같은 종류라고 여긴다','무엇을 한다? 어떠하다?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X06','kor',3,'u5',ARRAY['K3-2-u5-C6','K3-2-u5-C7']::text[],'낱말을 문장에 넣어 읽어 보지 않고 소리나 모양이 닮으면 같은 종류라고 여기거나(웃음·웃다), 닮은 둘 가운데 하나는 틀린 말이라고 여긴다','문장에 넣어 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X07','kor',3,'u5',ARRAY['K3-2-u5-C8','K3-2-u5-C1']::text[],'낱말의 종류를 배우는 까닭을 종류의 이름을 외우는 것이나 글씨를 빨리 쓰는 것처럼 낱말을 다루는 일과 상관없는 것으로 여긴다','이 단원에서 앞으로 할 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X08','kor',3,'u5',ARRAY['K3-2-u5-C9']::text[],'바뀌지 않는 부분과 바뀌는 부분을 잘못 갈라, 뒤에 붙는 ‘으’·‘어’까지 바뀌지 않는 부분에 넣거나 앞쪽 일부를 뺀다','모든 모양에 빠짐없이 든 곳까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X09','kor',3,'u5',ARRAY['K3-2-u5-C10']::text[],'모든 낱말은 문장에 따라 모양이 바뀐다고 여기거나, 이름을 나타내는 낱말도 뒤에 붙는 말이 달라지면 낱말 자체가 바뀐 것이라고 여긴다','계단이 · 계단을 · 계단은 — 낱말은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X10','kor',3,'u5',ARRAY['K3-2-u5-C11']::text[],'사전에 ‘닦으니’ 같은 모양이 실려 있지 않은 까닭을 사전을 만든 사람이 빠뜨려서라고 여긴다','모양이 몇 가지나 될까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X11','kor',3,'u5',ARRAY['K3-2-u5-C12']::text[],'기본형을 만들 때 바뀌는 부분까지 붙인 채 ‘-다’를 붙이거나(닦아다·심으다), ‘-다’가 아닌 다른 모양으로 만든다','바뀌지 않는 부분 + 다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X12','kor',3,'u5',ARRAY['K3-2-u5-C13','K3-2-u5-C11']::text[],'기본형만 바른 말이고 사전에 없는 바뀐 모양(접어서·닦으니)은 틀린 말이라고 여긴다','문장에 맞게 바뀐 것뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X13','kor',3,'u5',ARRAY['K3-2-u5-C11','K3-2-u5-C22','K3-2-u5-C23']::text[],'모양이 바뀐 낱말(접어서·찌그러졌고)도 사전에 모두 실려 있어 그대로 찾을 수 있다고 여긴다','사전에는 대표 모양 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X14','kor',3,'u5',ARRAY['K3-2-u5-C14','K3-2-u5-C15']::text[],'낱말마다 들어갈 칸이 하나로 정해져 있다고 여겨, 나누기 전에 기준을 정하지 않고 그 칸부터 찾는다','무엇을 보고 나눌지부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X15','kor',3,'u5',ARRAY['K3-2-u5-C14']::text[],'기준 없이 생각나는 대로 아무렇게나 나누어도 된다고 여긴다','다른 사람이 보고 알 수 있을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X16','kor',3,'u5',ARRAY['K3-2-u5-C15']::text[],'같은 낱말을 나눈 결과가 달라지면 앞에서 잘못 나누었기 때문이라고 여겨, 기준이 달라졌다는 것을 놓친다','두 번 나누는 동안 무엇이 바뀌었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X17','kor',3,'u5',ARRAY['K3-2-u5-C16','K3-2-u5-C26']::text[],'글에 나온 일의 까닭이나 내용을 글에 없는 것으로 짐작해 잘못 읽는다','그 줄을 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X18','kor',3,'u5',ARRAY['K3-2-u5-C17']::text[],'글자의 짜임에서 첫 자음자·모음자·받침을 엇갈리게 가른다','천천히 소리 내어 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X19','kor',3,'u5',ARRAY['K3-2-u5-C18']::text[],'첫 자음자의 차례를 틀리게 알아, ㄲ·ㄸ·ㅃ·ㅆ·ㅉ 같은 쌍자음자를 맨 뒤에 놓거나 ㄱ·ㄴ·ㄷ 차례를 엇갈린다','ㄱ 다음은 ㄲ') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X20','kor',3,'u5',ARRAY['K3-2-u5-C19']::text[],'첫 자음자가 같을 때 모음자의 차례를 틀리게 안다','ㅏ가 맨 앞, ㅣ가 맨 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X21','kor',3,'u5',ARRAY['K3-2-u5-C20']::text[],'받침이 있는 글자가 받침이 없는 글자보다 먼저 실린다고 여긴다','받침은 없는 쪽이 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X22','kor',3,'u5',ARRAY['K3-2-u5-C21']::text[],'첫 글자가 같은 낱말의 차례를 다음 글자가 아니라 낱말의 길이(짧은 것이 먼저)로 정한다','다음 글자를 같은 방법으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X23','kor',3,'u5',ARRAY['K3-2-u5-C22']::text[],'모양이 바뀐 낱말을 바뀐 모양 그대로 사전에서 찾으려 한다','사전을 펴기 전에 할 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X24','kor',3,'u5',ARRAY['K3-2-u5-C23']::text[],'국어사전에는 낱말의 뜻만 적혀 있다고 여긴다','한 낱말 옆에 함께 적힌 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X25','kor',3,'u5',ARRAY['K3-2-u5-C24']::text[],'뜻을 짐작할 때 앞뒤 문장을 살피지 않고 낱말의 소리나 모양만 보고 짐작한다','앞뒤 문장에 실마리가 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X26','kor',3,'u5',ARRAY['K3-2-u5-C25']::text[],'짐작한 뜻이 사전의 뜻과 다르면 그 글은 못 읽는다고 여기거나, 내 짐작이 맞고 사전이 틀렸다고 여긴다','사전의 뜻으로 고쳐 알고 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X27','kor',3,'u5',ARRAY['K3-2-u5-C25']::text[],'사전마다 뜻풀이의 말이 조금씩 다르면 어느 하나는 틀린 것이라고 여긴다','말이 달라도 뜻이 같으면 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X28','kor',3,'u5',ARRAY['K3-2-u5-C26']::text[],'국어사전을 쓰며 글을 읽는 까닭을 글을 더 빨리 읽기 위해서라고 여긴다','두 번째로 읽을 때 무엇이 달라졌나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X29','kor',3,'u5',ARRAY['K3-2-u5-C27']::text[],'단서 카드에 알아맞힐 낱말을 그대로 적거나, 쓰인 문장에서 낱말 자리를 비우지 않는다','단서는 답을 가리킬 뿐 답이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X30','kor',3,'u5',ARRAY['K3-2-u5-C28']::text[],'낱말 공책을 낱말이 긴 차례나 좋아하는 차례로 적거나, 나중에 찾아볼 때 도움이 안 되는 것(그날 날씨 등)을 적는다','나중에 다시 찾아볼 거예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X31','kor',3,'u5',ARRAY['K3-2-u5-C29']::text[],'낱말 놀이의 목표를 이기는 것으로 여겨 못 맞히면 실패라고 여긴다','단서를 보며 헤아려 보는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X32','kor',3,'u5',ARRAY['K3-2-u5-C30']::text[],'‘ㄴ’ 소리가 더해지는 조건을 잘못 알아, 앞 글자에 받침이 없어도 소리가 더해진다고 여긴다','앞 글자에 받침이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X33','kor',3,'u5',ARRAY['K3-2-u5-C30']::text[],'‘ㄴ’ 소리가 더해져 소리 나는 대로 낱말을 쓴다(한녀름·논닐)','쓸 때는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X34','kor',3,'u5',ARRAY['K3-2-u5-C31']::text[],'아우르다·북돋우다·여미다의 뜻을 엇갈리게 안다','어울리는 장면을 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u5-X35','kor',3,'u5',ARRAY['K3-2-u5-C32']::text[],'ㅘ·ㅚ·ㅙ를 이루는 두 모음자를 엇갈리게 알아 글자를 틀리게 쓴다(괜·관·외)','ㅗ 옆에 무엇이 붙었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_basic#1','kor',3,2,'u5','L02','g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C2',1,'mc','auto','알림장의 ‘어귀’처럼 글을 읽다가 모르는 낱말을 만나면 어떻게 할까요?',ARRAY['K3-2-u5-X01','K3-2-u5-X02']::text[],false,'{"seq":1,"concept":"K3-2-u5-C2","difficulty":1,"kind":"mc","stem":"알림장의 ‘어귀’처럼 글을 읽다가 모르는 낱말을 만나면 어떻게 할까요?","options":[{"t":"앞뒤를 살펴 짐작해 보고, 그 뒤에 확인한다","correct":true},{"t":"모르는 말은 그냥 건너뛴다","mis":"K3-2-u5-X01"},{"t":"한 낱말이라도 모르면 읽기를 멈춘다","mis":"K3-2-u5-X02"},{"t":"뜻을 몰라도 글자만 읽으면 된다","mis":"K3-2-u5-X01"}],"explanation":["글자만 읽어서는 어디로 갈지 몰라요.","멈추어도, 건너뛰어도 곤란해요.","짐작하고 확인해요."],"asset":{"type":"passage","lines":["“내일은 정문 어귀에서 모입니다.”","— 어귀가 어디지?","글자는 다 읽었는데 뜻을 몰라서 무엇을 해야 할지 알 수 없어요."],"title":"알림장에 적힌 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_basic#2','kor',3,2,'u5','L02','g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C3',1,'mc','auto','이름을 나타내는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X04']::text[],false,'{"seq":2,"concept":"K3-2-u5-C3","difficulty":1,"kind":"mc","stem":"이름을 나타내는 낱말은 무엇인가요?","options":[{"t":"사물함","correct":true},{"t":"닦다","mis":"K3-2-u5-X04"},{"t":"비좁다","mis":"K3-2-u5-X04"},{"t":"옮기다","mis":"K3-2-u5-X04"}],"explanation":["“이것이 ○○이다”에 넣어 봐요.","“이것이 사물함이다”가 돼요.","이름을 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_basic#3','kor',3,2,'u5','L02','g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C4',1,'mc','auto','움직임을 나타내는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X05']::text[],false,'{"seq":3,"concept":"K3-2-u5-C4","difficulty":1,"kind":"mc","stem":"움직임을 나타내는 낱말은 무엇인가요?","options":[{"t":"두드리다","correct":true},{"t":"손잡이","mis":"K3-2-u5-X04"},{"t":"환하다","mis":"K3-2-u5-X05"},{"t":"빗자루","mis":"K3-2-u5-X04"}],"explanation":["“문을 ○○” 하고 읽어 봐요.","“문을 두드린다”가 돼요.","움직임을 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_basic#4','kor',3,2,'u5','L02','g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C5',1,'ox','auto','‘매끈하다’는 성질이나 상태를 나타내는 낱말이에요.',ARRAY['K3-2-u5-X05']::text[],false,'{"seq":4,"concept":"K3-2-u5-C5","difficulty":1,"kind":"ox","stem":"‘매끈하다’는 성질이나 상태를 나타내는 낱말이에요.","answer":"O","reason_options":[{"t":"“책상이 매끈하다”처럼 어떠한지를 나타내기 때문에","correct":true},{"t":"‘-다’로 끝나는 낱말은 모두 움직임을 나타내기 때문에","mis":"K3-2-u5-X05"}],"mis":"K3-2-u5-X05","explanation":["“책상이 ○○”에 넣어 봐요.","책상이 어떠한지 말해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_basic#5','kor',3,2,'u5','L02','g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C6',2,'match','auto','낱말과 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u5-C6","difficulty":2,"kind":"match","stem":"낱말과 종류를 알맞게 이으세요.","pairs":[{"l":"바구니","r":"이름을 나타내는 낱말"},{"l":"심다","r":"움직임을 나타내는 낱말"},{"l":"비좁다","r":"성질이나 상태를 나타내는 낱말"}],"mis":"K3-2-u5-X04","explanation":["세 가지 틀에 차례로 넣어요.","어울리는 틀이 하나씩 있어요.","소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["“이것이 ○○이다” — ‘무엇’ 쪽","“○○을 한다” — ‘한다’ 쪽","“○○이 어떠하다” — ‘어떠하다’ 쪽"],"title":"종류를 가르는 세 가지 틀"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_basic#6','kor',3,2,'u5','L02','g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C6',2,'mc','auto','‘계단’을 세 가지 틀에 넣어 보았어요. 어울리는 문장은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X06']::text[],false,'{"seq":6,"concept":"K3-2-u5-C6","difficulty":2,"kind":"mc","stem":"‘계단’을 세 가지 틀에 넣어 보았어요. 어울리는 문장은 무엇인가요?","options":[{"t":"“이것이 계단이다.”","correct":true},{"t":"“계단이 무엇을 한다.”","mis":"K3-2-u5-X04"},{"t":"“계단이 어떠하다.”","mis":"K3-2-u5-X04"},{"t":"세 틀에 다 어울린다","mis":"K3-2-u5-X06"}],"explanation":["“계단이 무엇을 한다”는 어색해요.","“이것이 계단이다”는 돼요.","이름을 나타내는 낱말이에요."],"asset":{"type":"passage","lines":["“이것이 ○○이다” — ‘무엇’ 쪽","“○○을 한다” — ‘한다’ 쪽","“○○이 어떠하다” — ‘어떠하다’ 쪽"],"title":"종류를 가르는 세 가지 틀"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_basic#7','kor',3,2,'u5','L02','g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C7',2,'mc','auto','‘웃음’과 ‘웃다’에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u5-X06','K3-2-u5-X04']::text[],false,'{"seq":7,"concept":"K3-2-u5-C7","difficulty":2,"kind":"mc","stem":"‘웃음’과 ‘웃다’에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"‘웃음’은 이름을, ‘웃다’는 움직임을 나타내어 종류가 다르다","correct":true},{"t":"소리가 닮았으니 같은 종류이다","mis":"K3-2-u5-X06"},{"t":"둘 가운데 하나는 틀린 말이다","mis":"K3-2-u5-X06"},{"t":"둘 다 성질이나 상태를 나타낸다","mis":"K3-2-u5-X04"}],"explanation":["“웃음이 터졌다.”를 봐요.","“친구가 웃다.”도 봐요.","닮았어도 종류가 달라요."],"asset":{"type":"passage","lines":["웃음이 터졌다. / 친구가 웃다.","잠이 쏟아진다. / 동생이 자다."],"title":"모양이 닮은 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_basic#8','kor',3,2,'u5','L02','g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C5',2,'blank','auto','“복도가 (　).”의 빈칸에 들어가 복도가 어떠한지를 나타내는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":8,"concept":"K3-2-u5-C5","difficulty":2,"kind":"blank","stem":"“복도가 (　).”의 빈칸에 들어가 복도가 어떠한지를 나타내는 낱말은 무엇인가요?","options":[{"t":"환하다","correct":true},{"t":"두드리다","mis":"K3-2-u5-X05"},{"t":"빗자루","mis":"K3-2-u5-X04"},{"t":"옮기다","mis":"K3-2-u5-X05"}],"explanation":["복도가 어떠한지 말해요.","“복도가 환하다.”가 돼요.","성질이나 상태예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_basic#9','kor',3,2,'u5','L02','g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C1',2,'mc','auto','이 단원에서 배울 두 가지를 알맞게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u5-X07','K3-2-u5-X01']::text[],false,'{"seq":9,"concept":"K3-2-u5-C1","difficulty":2,"kind":"mc","stem":"이 단원에서 배울 두 가지를 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"기준에 따라 낱말 나누기 · 국어사전 쓰기","correct":true},{"t":"글씨 빨리 쓰기 · 줄넘기 오래 하기","mis":"K3-2-u5-X07"},{"t":"낱말 외우기 · 낱말 많이 쓰기","mis":"K3-2-u5-X07"},{"t":"책 빨리 읽기 · 모르는 말 건너뛰기","mis":"K3-2-u5-X01"}],"explanation":["둘 다 낱말을 다루는 일이에요.","하나는 낱말 나누기예요.","하나는 국어사전 쓰기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_basic#10','kor',3,2,'u5','L02','g3_2_kor_u5_L02_basic','lesson_basic','K3-2-u5-C8',3,'error','auto','낱말의 종류를 배우는 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X07']::text[],false,'{"seq":10,"concept":"K3-2-u5-C8","difficulty":3,"kind":"error","stem":"낱말의 종류를 배우는 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「세 가지 종류의 이름을 외워서 말하는 게 목표야.」","correct":true,"mis_target":"K3-2-u5-X07"},{"t":"친구 가 — 「기준을 정해 낱말을 나눌 수 있게 돼.」","mis":"K3-2-u5-X07"},{"t":"친구 나 — 「국어사전에서 낱말을 찾기 쉬워져.」","mis":"K3-2-u5-X07"}],"explanation":["이름을 외우는 것이 목표가 아니에요.","낱말을 보고 알아보는 것이 목표예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_challenge#1','kor',3,2,'u5','L02','g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C3',2,'sa','auto','“이것이 ○○이다”의 ‘무엇’ 쪽에 들어가는 낱말은 무엇을 나타내는 낱말인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u5-C3","difficulty":2,"kind":"sa","stem":"“이것이 ○○이다”의 ‘무엇’ 쪽에 들어가는 낱말은 무엇을 나타내는 낱말인가요? 두 글자로 쓰세요.","answer":["이름"],"explanation":["사물함·계단이 들어가요.","무엇인지 가리켜요.","‘이름’이에요."],"mis":"K3-2-u5-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_challenge#2','kor',3,2,'u5','L02','g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C2',2,'mc','auto','알림장의 “정문 어귀에서 모입니다.”를 읽고 곤란했던 까닭은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":2,"concept":"K3-2-u5-C2","difficulty":2,"kind":"mc","stem":"알림장의 “정문 어귀에서 모입니다.”를 읽고 곤란했던 까닭은 무엇인가요?","options":[{"t":"글자는 다 읽었는데 ‘어귀’의 뜻을 몰라서","correct":true},{"t":"글자를 읽을 줄 몰라서","mis":"K3-2-u5-X17"},{"t":"알림장 글씨가 작아서","mis":"K3-2-u5-X17"},{"t":"모이는 시각이 적혀 있지 않아서","mis":"K3-2-u5-X17"}],"explanation":["글자는 다 읽었어요.","뜻을 모르는 낱말이 있었어요.","그래서 어디로 갈지 몰랐어요."],"asset":{"type":"passage","lines":["“내일은 정문 어귀에서 모입니다.”","— 어귀가 어디지?","글자는 다 읽었는데 뜻을 몰라서 무엇을 해야 할지 알 수 없어요."],"title":"알림장에 적힌 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_challenge#3','kor',3,2,'u5','L02','g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C5',3,'mc','auto','세 낱말이 모두 성질이나 상태를 나타내는 것은 무엇인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":3,"concept":"K3-2-u5-C5","difficulty":3,"kind":"mc","stem":"세 낱말이 모두 성질이나 상태를 나타내는 것은 무엇인가요?","options":[{"t":"비좁다 · 환하다 · 묵직하다","correct":true},{"t":"닦다 · 매끈하다 · 접다","mis":"K3-2-u5-X05"},{"t":"손잡이 · 비좁다 · 심다","mis":"K3-2-u5-X04"},{"t":"옮기다 · 두드리다 · 심다","mis":"K3-2-u5-X05"}],"explanation":["“○○이 어떠하다”에 넣어요.","닦다·접다는 움직임이에요.","셋 다 어떠한지 말하는 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_challenge#4','kor',3,2,'u5','L02','g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C7',3,'ox','auto','‘잠’과 ‘자다’는 모양이 닮았으니 같은 종류의 낱말이에요.',ARRAY['K3-2-u5-X06']::text[],false,'{"seq":4,"concept":"K3-2-u5-C7","difficulty":3,"kind":"ox","stem":"‘잠’과 ‘자다’는 모양이 닮았으니 같은 종류의 낱말이에요.","answer":"X","reason_options":[{"t":"‘잠’은 이름을, ‘자다’는 움직임을 나타내어 종류가 다르기 때문에","correct":true},{"t":"소리가 닮은 낱말은 언제나 같은 종류이기 때문에","mis":"K3-2-u5-X06"}],"mis":"K3-2-u5-X06","explanation":["“잠이 쏟아진다.”를 봐요.","“동생이 자다.”도 봐요.","그래서 X예요."],"asset":{"type":"passage","lines":["웃음이 터졌다. / 친구가 웃다.","잠이 쏟아진다. / 동생이 자다."],"title":"모양이 닮은 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_challenge#5','kor',3,2,'u5','L02','g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C6',3,'mc','auto','‘환하다’의 종류가 헷갈릴 때 가장 빠른 방법은 무엇인가요?',ARRAY['K3-2-u5-X06','K3-2-u5-X07']::text[],false,'{"seq":5,"concept":"K3-2-u5-C6","difficulty":3,"kind":"mc","stem":"‘환하다’의 종류가 헷갈릴 때 가장 빠른 방법은 무엇인가요?","options":[{"t":"“복도가 환하다.”처럼 문장에 넣어 읽어 본다","correct":true},{"t":"낱말의 글자 수를 센다","mis":"K3-2-u5-X06"},{"t":"비슷한 소리의 낱말과 같은 종류로 정한다","mis":"K3-2-u5-X06"},{"t":"종류의 이름을 여러 번 외운다","mis":"K3-2-u5-X07"}],"explanation":["낱말만 보고 외우지 않아요.","문장에 넣어 읽어요.","어떠한지 말하는지 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_challenge#6','kor',3,2,'u5','L02','g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C4',3,'error','auto','이야기를 들으며 떠오른 낱말을 나누었어요. 잘못 나눈 친구는 누구인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":6,"concept":"K3-2-u5-C4","difficulty":3,"kind":"error","stem":"이야기를 들으며 떠오른 낱말을 나누었어요. 잘못 나눈 친구는 누구인가요?","options":[{"t":"친구 나 — 「‘두드리다’는 성질이나 상태를 나타내.」","correct":true,"mis_target":"K3-2-u5-X05"},{"t":"친구 가 — 「‘빗자루’는 이름을 나타내.」","mis":"K3-2-u5-X04"},{"t":"친구 다 — 「‘옮기다’는 움직임을 나타내.」","mis":"K3-2-u5-X04"}],"explanation":["“문을 두드린다”가 돼요.","무엇을 하는지 말해요.","친구 나가 잘못 나누었어요."],"asset":{"type":"passage","lines":["사물함, 손잡이, 빗자루 …","닦다, 옮기다, 두드리다 …","비좁다, 환하다, 매끈하다 …"],"title":"교실을 둘러보며 떠오른 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_challenge#7','kor',3,2,'u5','L02','g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C1',3,'mc','auto','이 단원에서 배우는 것이 모두 ‘낱말을 다루는 힘’을 기르는 일인 까닭은 무엇인가요?',ARRAY['K3-2-u5-X07','K3-2-u5-X01']::text[],false,'{"seq":7,"concept":"K3-2-u5-C1","difficulty":3,"kind":"mc","stem":"이 단원에서 배우는 것이 모두 ‘낱말을 다루는 힘’을 기르는 일인 까닭은 무엇인가요?","options":[{"t":"낱말을 나누고, 찾고, 뜻을 알아 글을 읽는 일이기 때문에","correct":true},{"t":"글씨를 예쁘게 쓰는 일이기 때문에","mis":"K3-2-u5-X07"},{"t":"낱말을 빨리 외우는 일이기 때문에","mis":"K3-2-u5-X07"},{"t":"모르는 낱말을 건너뛰는 일이기 때문에","mis":"K3-2-u5-X01"}],"explanation":["나누기도 낱말을 다뤄요.","사전 찾기도 낱말을 다뤄요.","그래서 낱말을 다루는 힘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_challenge#8','kor',3,2,'u5','L02','g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C8',4,'mc','auto','낱말의 종류를 알면 할 수 있는 일로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u5-X07']::text[],false,'{"seq":8,"concept":"K3-2-u5-C8","difficulty":4,"kind":"mc","stem":"낱말의 종류를 알면 할 수 있는 일로 알맞지 않은 것은 무엇인가요?","options":[{"t":"글씨를 더 빨리 쓸 수 있다","correct":true},{"t":"기준을 정해 낱말을 나눌 수 있다","mis":"K3-2-u5-X07"},{"t":"국어사전에서 낱말을 찾기 쉬워진다","mis":"K3-2-u5-X07"},{"t":"하려는 말을 더 또렷하게 할 수 있다","mis":"K3-2-u5-X07"}],"explanation":["셋은 낱말을 다루는 일이에요.","글씨 빠르기는 상관없어요.","그것이 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_challenge#9','kor',3,2,'u5','L02','g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C7',4,'essay','teacher','‘웃음’과 ‘웃다’가 같은 종류인지 쓰고, 세 가지 틀 가운데 알맞은 것에 각각 넣어 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u5-C7","difficulty":4,"kind":"essay","stem":"‘웃음’과 ‘웃다’가 같은 종류인지 쓰고, 세 가지 틀 가운데 알맞은 것에 각각 넣어 까닭을 쓰세요.","answer_guide":{"answer":"예: 같은 종류가 아니다. ‘웃음’은 “이것이 웃음이다.”, “웃음이 터졌다.”처럼 ‘무엇’ 쪽에 들어가니 이름을 나타낸다. ‘웃다’는 “친구가 웃다(웃는다).”처럼 ‘한다’ 쪽에 들어가니 움직임을 나타낸다. 모양이 닮아도 종류는 다를 수 있다.","scoring_points":["같은 종류가 아니라고 썼는가","두 낱말을 틀에 넣어 보였는가","모양이 닮아도 종류가 다를 수 있다고 썼는가"]},"explanation":["닮았다고 같은 종류는 아니에요.","틀에 넣어 봐요.","둘 다 바른 말이에요."],"asset":{"type":"passage","lines":["웃음이 터졌다. / 친구가 웃다.","잠이 쏟아진다. / 동생이 자다."],"title":"모양이 닮은 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L02_challenge#10','kor',3,2,'u5','L02','g3_2_kor_u5_L02_challenge','lesson_challenge','K3-2-u5-C2',4,'essay','teacher','알림장의 ‘어귀’처럼 모르는 낱말을 만났을 때 어떻게 읽을지 순서대로 쓰고, 그냥 건너뛰면 어떤 일이 생길지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u5-C2","difficulty":4,"kind":"essay","stem":"알림장의 ‘어귀’처럼 모르는 낱말을 만났을 때 어떻게 읽을지 순서대로 쓰고, 그냥 건너뛰면 어떤 일이 생길지 쓰세요.","answer_guide":{"answer":"예: 먼저 앞뒤를 살펴 뜻을 짐작해 보며 끝까지 읽는다. 그다음 국어사전에서 그 뜻을 확인한다. 그냥 건너뛰면 ‘어귀’가 어디인지 몰라 내일 어디에서 모여야 하는지 알 수 없게 된다.","scoring_points":["짐작하며 읽는다고 썼는가","그 뒤에 확인한다고 썼는가","건너뛰면 생길 일을 썼는가"]},"explanation":["짐작이 먼저예요.","확인은 그 뒤예요.","건너뛰면 무엇을 놓칠까요?"],"asset":{"type":"passage","lines":["“내일은 정문 어귀에서 모입니다.”","— 어귀가 어디지?","글자는 다 읽었는데 뜻을 몰라서 무엇을 해야 할지 알 수 없어요."],"title":"알림장에 적힌 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_basic#1','kor',3,2,'u5','L04','g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C9',1,'mc','auto','‘접고 · 접으니 · 접으면 · 접어서’에서 바뀌지 않는 부분은 무엇인가요?',ARRAY['K3-2-u5-X08']::text[],false,'{"seq":1,"concept":"K3-2-u5-C9","difficulty":1,"kind":"mc","stem":"‘접고 · 접으니 · 접으면 · 접어서’에서 바뀌지 않는 부분은 무엇인가요?","options":[{"t":"접","correct":true},{"t":"접으","mis":"K3-2-u5-X08"},{"t":"고","mis":"K3-2-u5-X08"},{"t":"접어","mis":"K3-2-u5-X08"}],"explanation":["네 낱말을 나란히 놓아요.","빠짐없이 든 곳을 짚어요.","‘접’이에요."],"asset":{"type":"passage","lines":["종이를 접고 풀을 발랐다.","접으니 손바닥만 해졌다.","접으면 주머니에 들어간다.","접어서 책 사이에 끼웠다."],"title":"같은 낱말, 다른 모양"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_basic#2','kor',3,2,'u5','L04','g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C10',1,'ox','auto','‘계단’은 문장에 따라 모양이 바뀌지 않는 낱말이에요.',ARRAY['K3-2-u5-X09']::text[],false,'{"seq":2,"concept":"K3-2-u5-C10","difficulty":1,"kind":"ox","stem":"‘계단’은 문장에 따라 모양이 바뀌지 않는 낱말이에요.","answer":"O","reason_options":[{"t":"이름을 나타내는 낱말이라 문장이 달라져도 그대로이기 때문에","correct":true},{"t":"모든 낱말은 문장에 따라 모양이 바뀌기 때문에","mis":"K3-2-u5-X09"}],"mis":"K3-2-u5-X09","explanation":["계단이 · 계단을 · 계단은.","낱말 ‘계단’은 그대로예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_basic#3','kor',3,2,'u5','L04','g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C12',1,'mc','auto','‘닦으니’의 기본형은 무엇인가요?',ARRAY['K3-2-u5-X11']::text[],false,'{"seq":3,"concept":"K3-2-u5-C12","difficulty":1,"kind":"mc","stem":"‘닦으니’의 기본형은 무엇인가요?","options":[{"t":"닦다","correct":true},{"t":"닦으다","mis":"K3-2-u5-X11"},{"t":"닦아다","mis":"K3-2-u5-X11"},{"t":"닦는다","mis":"K3-2-u5-X11"}],"explanation":["바뀌지 않는 부분은 ‘닦’이에요.","거기에 ‘-다’를 붙여요.","‘닦다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_basic#4','kor',3,2,'u5','L04','g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C10',1,'mc','auto','문장에 쓰일 때 모양이 바뀌는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X09']::text[],false,'{"seq":4,"concept":"K3-2-u5-C10","difficulty":1,"kind":"mc","stem":"문장에 쓰일 때 모양이 바뀌는 낱말은 무엇인가요?","options":[{"t":"심다","correct":true},{"t":"바구니","mis":"K3-2-u5-X09"},{"t":"손잡이","mis":"K3-2-u5-X09"},{"t":"계단","mis":"K3-2-u5-X09"}],"explanation":["‘심고 · 심으니 · 심어서’.","뒤쪽이 바뀌어요.","움직임을 나타내는 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_basic#5','kor',3,2,'u5','L04','g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C9',2,'mc','auto','‘심고 · 심으니 · 심으면 · 심어서’에서 바뀌는 부분끼리 모은 것은 무엇인가요?',ARRAY['K3-2-u5-X08']::text[],false,'{"seq":5,"concept":"K3-2-u5-C9","difficulty":2,"kind":"mc","stem":"‘심고 · 심으니 · 심으면 · 심어서’에서 바뀌는 부분끼리 모은 것은 무엇인가요?","options":[{"t":"고 · 으니 · 으면 · 어서","correct":true},{"t":"심 · 으 · 어","mis":"K3-2-u5-X08"},{"t":"심고 · 심으 · 심어","mis":"K3-2-u5-X08"},{"t":"심 · 심 · 심 · 심","mis":"K3-2-u5-X08"}],"explanation":["‘심’은 네 번 다 그대로예요.","그 뒤가 갈아입어요.","뒤쪽만 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_basic#6','kor',3,2,'u5','L04','g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C11',2,'mc','auto','사전에 ‘닦고 · 닦으니 · 닦아서’가 모두 실려 있지 않은 까닭은 무엇인가요?',ARRAY['K3-2-u5-X12','K3-2-u5-X10']::text[],false,'{"seq":6,"concept":"K3-2-u5-C11","difficulty":2,"kind":"mc","stem":"사전에 ‘닦고 · 닦으니 · 닦아서’가 모두 실려 있지 않은 까닭은 무엇인가요?","options":[{"t":"모양이 너무 많아 다 실을 수 없으니 대표 모양 하나만 싣기 때문에","correct":true},{"t":"그런 말들은 틀린 말이라서","mis":"K3-2-u5-X12"},{"t":"사전을 만든 사람이 빠뜨려서","mis":"K3-2-u5-X10"},{"t":"바뀐 모양은 쓰지 않는 말이라서","mis":"K3-2-u5-X12"}],"explanation":["낱말 하나에 모양이 아주 많아요.","다 실으면 사전이 몇 배로 두꺼워져요.","대표 모양 하나만 실어요."],"asset":{"type":"passage","lines":["닦고 · 닦으니 · 닦으면 · 닦아서 · 닦는다 · 닦았다 …","낱말 하나에 모양이 이렇게 많아요."],"title":"사전의 곤란"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_basic#7','kor',3,2,'u5','L04','g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C12',2,'match','auto','문장 속 낱말과 기본형을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u5-C12","difficulty":2,"kind":"match","stem":"문장 속 낱말과 기본형을 알맞게 이으세요.","pairs":[{"l":"닦아서","r":"닦다"},{"l":"비좁으니","r":"비좁다"},{"l":"접으면","r":"접다"}],"mis":"K3-2-u5-X11","explanation":["바뀌지 않는 부분을 찾아요.","‘-다’를 붙여요.","세 짝을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_basic#8','kor',3,2,'u5','L04','g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C13',2,'mc','auto','“종이를 접어서 넣었다.”의 ‘접어서’에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u5-X12','K3-2-u5-X13']::text[],false,'{"seq":8,"concept":"K3-2-u5-C13","difficulty":2,"kind":"mc","stem":"“종이를 접어서 넣었다.”의 ‘접어서’에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"문장에 따라 모양이 바뀐 것일 뿐 틀린 말이 아니다","correct":true},{"t":"사전에 없으니 틀린 말이다","mis":"K3-2-u5-X12"},{"t":"바뀐 모양도 사전에 모두 실려 있다","mis":"K3-2-u5-X13"},{"t":"‘접다’로 고쳐 써야 바른 문장이다","mis":"K3-2-u5-X12"}],"explanation":["사전에는 ‘접다’가 실려요.","그렇다고 ‘접어서’가 틀린 것은 아니에요.","문장에 맞게 바뀐 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_basic#9','kor',3,2,'u5','L04','g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C10',2,'ox','auto','움직임이나 성질·상태를 나타내는 낱말은 문장에 쓰일 때 모양이 바뀌어요.',ARRAY['K3-2-u5-X09']::text[],false,'{"seq":9,"concept":"K3-2-u5-C10","difficulty":2,"kind":"ox","stem":"움직임이나 성질·상태를 나타내는 낱말은 문장에 쓰일 때 모양이 바뀌어요.","answer":"O","reason_options":[{"t":"‘비좁고 · 비좁으니’처럼 뒤쪽이 문장에 따라 바뀌기 때문에","correct":true},{"t":"이름을 나타내는 낱말만 모양이 바뀌기 때문에","mis":"K3-2-u5-X09"}],"mis":"K3-2-u5-X09","explanation":["‘접다’도 ‘비좁다’도 바뀌어요.","이름은 그대로예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_basic#10','kor',3,2,'u5','L04','g3_2_kor_u5_L04_basic','lesson_basic','K3-2-u5-C13',3,'error','auto','기본형을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X12','K3-2-u5-X13']::text[],false,'{"seq":10,"concept":"K3-2-u5-C13","difficulty":3,"kind":"error","stem":"기본형을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「기본형이 바른 말이니까 ‘닦으니’는 쓰면 안 돼.」","correct":true,"mis_target":"K3-2-u5-X12"},{"t":"친구 가 — 「기본형은 사전에 실을 때 고른 대표 모양이야.」","mis":"K3-2-u5-X12"},{"t":"친구 나 — 「사전에서 찾을 때는 기본형으로 바꾸어 찾아.」","mis":"K3-2-u5-X13"}],"explanation":["‘닦으니’는 문장에 맞게 바뀐 말이에요.","틀린 말이 아니에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_challenge#1','kor',3,2,'u5','L04','g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C12',2,'sa','auto','‘비좁으니’의 기본형을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u5-C12","difficulty":2,"kind":"sa","stem":"‘비좁으니’의 기본형을 쓰세요.","answer":["비좁다"],"explanation":["바뀌지 않는 부분은 ‘비좁’이에요.","‘-다’를 붙여요.","‘비좁다’예요."],"mis":"K3-2-u5-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_challenge#2','kor',3,2,'u5','L04','g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C12',2,'mc','auto','기본형을 만드는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X11','K3-2-u5-X08']::text[],false,'{"seq":2,"concept":"K3-2-u5-C12","difficulty":2,"kind":"mc","stem":"기본형을 만드는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"바뀌지 않는 부분을 찾아 ‘-다’를 붙인다","correct":true},{"t":"바뀌는 부분까지 그대로 두고 ‘-다’를 붙인다","mis":"K3-2-u5-X11"},{"t":"낱말 맨 앞 글자만 남긴다","mis":"K3-2-u5-X08"},{"t":"가장 많이 쓰는 모양을 고른다","mis":"K3-2-u5-X11"}],"explanation":["먼저 그대로인 곳을 찾아요.","그 뒤에 ‘-다’를 붙여요.","그것이 기본형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_challenge#3','kor',3,2,'u5','L04','g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C9',3,'mc','auto','‘집고 · 집으니 · 집어서’와 ‘찾고 · 찾으니 · 찾아서’에서 바뀌지 않는 부분을 차례대로 쓴 것은 무엇인가요?',ARRAY['K3-2-u5-X08']::text[],false,'{"seq":3,"concept":"K3-2-u5-C9","difficulty":3,"kind":"mc","stem":"‘집고 · 집으니 · 집어서’와 ‘찾고 · 찾으니 · 찾아서’에서 바뀌지 않는 부분을 차례대로 쓴 것은 무엇인가요?","options":[{"t":"집 · 찾","correct":true},{"t":"집으 · 찾으","mis":"K3-2-u5-X08"},{"t":"집어 · 찾아","mis":"K3-2-u5-X08"},{"t":"고 · 고","mis":"K3-2-u5-X08"}],"explanation":["세 모양에 빠짐없이 든 곳이에요.","‘으’는 빠지는 모양이 있어요.","‘집’과 ‘찾’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_challenge#4','kor',3,2,'u5','L04','g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C13',3,'ox','auto','사전에 ‘닦으니’가 실려 있지 않으니, ‘닦으니’는 틀린 말이에요.',ARRAY['K3-2-u5-X12']::text[],false,'{"seq":4,"concept":"K3-2-u5-C13","difficulty":3,"kind":"ox","stem":"사전에 ‘닦으니’가 실려 있지 않으니, ‘닦으니’는 틀린 말이에요.","answer":"X","reason_options":[{"t":"사전에 대표 모양만 실을 뿐, 문장에 맞게 바뀐 모양도 바른 말이기 때문에","correct":true},{"t":"사전에 없는 말은 모두 틀린 말이기 때문에","mis":"K3-2-u5-X12"}],"mis":"K3-2-u5-X12","explanation":["사전에는 ‘닦다’가 실려요.","‘닦으니’는 문장에서 바뀐 모양이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["닦고 · 닦으니 · 닦으면 · 닦아서 · 닦는다 · 닦았다 …","낱말 하나에 모양이 이렇게 많아요."],"title":"사전의 곤란"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_challenge#5','kor',3,2,'u5','L04','g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C10',3,'error','auto','모양이 바뀌는 낱말을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X09']::text[],false,'{"seq":5,"concept":"K3-2-u5-C10","difficulty":3,"kind":"error","stem":"모양이 바뀌는 낱말을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「‘계단이 · 계단을’처럼 ‘계단’도 모양이 바뀌어.」","correct":true,"mis_target":"K3-2-u5-X09"},{"t":"친구 나 — 「‘접다’는 ‘접고 · 접어서’처럼 바뀌어.」","mis":"K3-2-u5-X09"},{"t":"친구 다 — 「‘비좁다’도 ‘비좁고 · 비좁으니’처럼 바뀌어.」","mis":"K3-2-u5-X09"}],"explanation":["뒤에 붙는 말만 달라졌어요.","‘계단’ 자체는 그대로예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_challenge#6','kor',3,2,'u5','L04','g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C11',3,'mc','auto','사전이 낱말마다 바뀐 모양을 모두 싣는다면 어떻게 될까요?',ARRAY['K3-2-u5-X12','K3-2-u5-X10','K3-2-u5-X13']::text[],false,'{"seq":6,"concept":"K3-2-u5-C11","difficulty":3,"kind":"mc","stem":"사전이 낱말마다 바뀐 모양을 모두 싣는다면 어떻게 될까요?","options":[{"t":"낱말 하나에 모양이 많아 사전이 몇 배로 두꺼워진다","correct":true},{"t":"틀린 말이 사전에 실리게 된다","mis":"K3-2-u5-X12"},{"t":"사전을 만든 사람이 빠뜨린 것이 없어진다","mis":"K3-2-u5-X10"},{"t":"기본형이 필요 없어 찾기가 쉬워진다","mis":"K3-2-u5-X13"}],"explanation":["닦고·닦으니·닦아서·닦았다 ….","모양이 끝없이 많아요.","그래서 대표 모양 하나만 실어요."],"asset":{"type":"passage","lines":["닦고 · 닦으니 · 닦으면 · 닦아서 · 닦는다 · 닦았다 …","낱말 하나에 모양이 이렇게 많아요."],"title":"사전의 곤란"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_challenge#7','kor',3,2,'u5','L04','g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C12',3,'mc','auto','“짝이 문을 여닫으니 바람이 들어왔다.”에서 ‘여닫으니’를 사전에서 찾으려면 무엇으로 찾아야 하나요?',ARRAY['K3-2-u5-X13','K3-2-u5-X11']::text[],false,'{"seq":7,"concept":"K3-2-u5-C12","difficulty":3,"kind":"mc","stem":"“짝이 문을 여닫으니 바람이 들어왔다.”에서 ‘여닫으니’를 사전에서 찾으려면 무엇으로 찾아야 하나요?","options":[{"t":"여닫다","correct":true},{"t":"여닫으니","mis":"K3-2-u5-X13"},{"t":"여닫으다","mis":"K3-2-u5-X11"},{"t":"여닫","mis":"K3-2-u5-X11"}],"explanation":["바뀌지 않는 부분은 ‘여닫’이에요.","‘-다’를 붙여요.","‘여닫다’로 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_challenge#8','kor',3,2,'u5','L04','g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C13',4,'mc','auto','동생이 「사전에 ‘심어서’가 없으니 “씨앗을 심어서 물을 주었다.”는 틀린 문장이야.」라고 했어요. 동생에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X12','K3-2-u5-X13','K3-2-u5-X10']::text[],false,'{"seq":8,"concept":"K3-2-u5-C13","difficulty":4,"kind":"mc","stem":"동생이 「사전에 ‘심어서’가 없으니 “씨앗을 심어서 물을 주었다.”는 틀린 문장이야.」라고 했어요. 동생에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“‘심어서’는 ‘심다’가 문장에 맞게 바뀐 모양이야. 사전엔 대표 모양만 실어서 없는 거야.”","correct":true},{"t":"“맞아. ‘씨앗을 심다 물을 주었다’로 고쳐야 해.”","mis":"K3-2-u5-X12"},{"t":"“아니야. 사전을 다시 보면 ‘심어서’도 실려 있을 거야.”","mis":"K3-2-u5-X13"},{"t":"“사전을 만든 사람이 깜빡 빠뜨렸나 봐.”","mis":"K3-2-u5-X10"}],"explanation":["‘심어서’는 바른 말이에요.","사전엔 ‘심다’만 있어요.","대표 모양만 싣기 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_challenge#9','kor',3,2,'u5','L04','g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C11',4,'essay','teacher','사전에 ‘닦고 · 닦으니 · 닦아서’가 모두 실려 있지 않은 까닭을 쓰고, 그렇다면 ‘닦아서’는 사전에서 어떻게 찾아야 하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u5-C11","difficulty":4,"kind":"essay","stem":"사전에 ‘닦고 · 닦으니 · 닦아서’가 모두 실려 있지 않은 까닭을 쓰고, 그렇다면 ‘닦아서’는 사전에서 어떻게 찾아야 하는지 쓰세요.","answer_guide":{"answer":"예: 낱말 하나에 바뀐 모양이 아주 많아서 모두 실으면 사전이 몇 배로 두꺼워지기 때문에 대표 모양인 기본형 하나만 싣는다. ‘닦아서’는 바뀌지 않는 부분 ‘닦’에 ‘-다’를 붙여 ‘닦다’로 바꾸어 찾는다.","scoring_points":["모양이 너무 많아서라고 썼는가","대표 모양(기본형) 하나만 싣는다고 썼는가","‘닦다’로 바꾸어 찾는다고 썼는가"]},"explanation":["모양이 몇 가지인지 떠올려요.","사전엔 대표 모양이 실려요.","‘닦’ + 다예요."],"asset":{"type":"passage","lines":["닦고 · 닦으니 · 닦으면 · 닦아서 · 닦는다 · 닦았다 …","낱말 하나에 모양이 이렇게 많아요."],"title":"사전의 곤란"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L04_challenge#10','kor',3,2,'u5','L04','g3_2_kor_u5_L04_challenge','lesson_challenge','K3-2-u5-C13',4,'essay','teacher','「기본형만 바른 말이야.」라고 말하는 친구에게 기본형이 무엇인지 설명하고, ‘접어서’를 예로 들어 바뀐 모양이 틀린 말이 아닌 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u5-C13","difficulty":4,"kind":"essay","stem":"「기본형만 바른 말이야.」라고 말하는 친구에게 기본형이 무엇인지 설명하고, ‘접어서’를 예로 들어 바뀐 모양이 틀린 말이 아닌 까닭을 쓰세요.","answer_guide":{"answer":"예: 기본형은 바뀌지 않는 부분에 ‘-다’를 붙여 만든, 사전에 실을 때 고른 대표 모양이다. ‘접어서’는 “종이를 접어서 넣었다.”처럼 문장에 알맞게 ‘접다’의 모양이 바뀐 것이다. 사전에 없을 뿐 틀린 말이 아니다.","scoring_points":["기본형이 대표 모양이라고 썼는가","‘접어서’가 문장에 맞게 바뀐 모양이라고 썼는가","사전에 없어도 틀린 말이 아니라고 썼는가"]},"explanation":["기본형은 대표 모양이에요.","바뀐 모양도 바른 말이에요.","사전에 없다고 틀린 것은 아니에요."],"asset":{"type":"passage","lines":["종이를 접고 풀을 발랐다.","접으니 손바닥만 해졌다.","접으면 주머니에 들어간다.","접어서 책 사이에 끼웠다."],"title":"같은 낱말, 다른 모양"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_basic#1','kor',3,2,'u5','L06','g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C14',1,'mc','auto','낱말을 여럿 놓고 나눌 때, 가장 먼저 할 일은 무엇인가요?',ARRAY['K3-2-u5-X14','K3-2-u5-X15']::text[],false,'{"seq":1,"concept":"K3-2-u5-C14","difficulty":1,"kind":"mc","stem":"낱말을 여럿 놓고 나눌 때, 가장 먼저 할 일은 무엇인가요?","options":[{"t":"무엇을 보고 나눌지 기준을 먼저 정한다","correct":true},{"t":"낱말마다 정해진 칸이 하나 있으니 그 칸을 찾는다","mis":"K3-2-u5-X14"},{"t":"생각나는 대로 아무렇게나 나눈다","mis":"K3-2-u5-X15"},{"t":"낱말을 많이 외운 사람에게 맡긴다","mis":"K3-2-u5-X15"}],"explanation":["같은 낱말도 보는 것에 따라 달리 나뉘어요.","그래서 보는 것부터 정해요.","그것이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_basic#2','kor',3,2,'u5','L06','g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C16',1,'mc','auto','이야기에서 처음에 물통을 찾지 못한 까닭은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":2,"concept":"K3-2-u5-C16","difficulty":1,"kind":"mc","stem":"이야기에서 처음에 물통을 찾지 못한 까닭은 무엇인가요?","options":[{"t":"물통을 가리킬 낱말이 모자랐기 때문에","correct":true},{"t":"물통이 상자에 없었기 때문에","mis":"K3-2-u5-X17"},{"t":"교무실에 너무 늦게 갔기 때문에","mis":"K3-2-u5-X17"},{"t":"상자가 너무 무거웠기 때문에","mis":"K3-2-u5-X17"}],"explanation":["마지막 줄을 다시 읽어요.","물통은 처음부터 거기 있었어요.","없던 것은 낱말이었어요."],"asset":{"type":"passage","lines":["교실에서 짝이 물었다. “손잡이는 있어? 뚜껑은 어떻게 여닫아? 겉은 어때?”","하나씩 떠올랐다. 손잡이가 달렸고, 뚜껑을 돌려서 여닫고, 겉이 까슬까슬하고,","바닥이 조금 찌그러졌고, 물을 채우면 꽤 묵직했다.","그대로 말씀드리자 선생님은 상자에서 하나를 바로 집어 주셨다.","물통은 처음부터 거기 있었다. 없던 것은 그것을 말할 낱말이었다."],"title":"이야기 「잃어버린 것을 말하는 법」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_basic#3','kor',3,2,'u5','L06','g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C15',1,'ox','auto','같은 낱말이라도 기준이 바뀌면 나뉜 결과도 바뀔 수 있어요.',ARRAY['K3-2-u5-X14']::text[],false,'{"seq":3,"concept":"K3-2-u5-C15","difficulty":1,"kind":"ox","stem":"같은 낱말이라도 기준이 바뀌면 나뉜 결과도 바뀔 수 있어요.","answer":"O","reason_options":[{"t":"무엇을 보고 나누느냐에 따라 나뉘는 모양이 달라지기 때문에","correct":true},{"t":"낱말마다 들어갈 칸이 하나로 정해져 있기 때문에","mis":"K3-2-u5-X14"}],"mis":"K3-2-u5-X14","explanation":["아홉 낱말을 두 번 나누어 보았어요.","결과가 달랐어요.","그래서 O예요."],"asset":{"type":"passage","lines":["기준 ① 낱말의 종류로 — 셋 · 셋 · 셋","기준 ② 모양이 바뀌는가로 — 여섯 · 셋"],"title":"같은 아홉 낱말을 두 번 나눈 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_basic#4','kor',3,2,'u5','L06','g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C16',1,'mc','auto','짝의 물음이 도움이 된 까닭은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":4,"concept":"K3-2-u5-C16","difficulty":1,"kind":"mc","stem":"짝의 물음이 도움이 된 까닭은 무엇인가요?","options":[{"t":"무엇을 말해야 할지 하나씩 짚어 주어서","correct":true},{"t":"짝이 대신 교무실에 가 주어서","mis":"K3-2-u5-X17"},{"t":"짝이 큰 목소리로 물어보아서","mis":"K3-2-u5-X17"},{"t":"짝이 물통을 찾아 주어서","mis":"K3-2-u5-X17"}],"explanation":["짝은 손잡이·뚜껑·겉을 물었어요.","하나씩 낱말이 떠올랐어요.","그래서 자세히 말했어요."],"asset":{"type":"passage","lines":["교실에서 짝이 물었다. “손잡이는 있어? 뚜껑은 어떻게 여닫아? 겉은 어때?”","하나씩 떠올랐다. 손잡이가 달렸고, 뚜껑을 돌려서 여닫고, 겉이 까슬까슬하고,","바닥이 조금 찌그러졌고, 물을 채우면 꽤 묵직했다.","그대로 말씀드리자 선생님은 상자에서 하나를 바로 집어 주셨다.","물통은 처음부터 거기 있었다. 없던 것은 그것을 말할 낱말이었다."],"title":"이야기 「잃어버린 것을 말하는 법」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_basic#5','kor',3,2,'u5','L06','g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C3',2,'mc','auto','아홉 낱말을 낱말의 종류로 나눌 때, 이름을 나타내는 낱말만 모은 것은 무엇인가요?',ARRAY['K3-2-u5-X04']::text[],false,'{"seq":5,"concept":"K3-2-u5-C3","difficulty":2,"kind":"mc","stem":"아홉 낱말을 낱말의 종류로 나눌 때, 이름을 나타내는 낱말만 모은 것은 무엇인가요?","options":[{"t":"물통 · 손잡이 · 뚜껑","correct":true},{"t":"물통 · 여닫다 · 비좁다","mis":"K3-2-u5-X04"},{"t":"손잡이 · 집다 · 묵직하다","mis":"K3-2-u5-X04"},{"t":"뚜껑 · 찌그러지다 · 까슬까슬하다","mis":"K3-2-u5-X04"}],"explanation":["“이것이 ○○이다”에 넣어요.","셋만 들어가요.","물통·손잡이·뚜껑이에요."],"asset":{"type":"passage","lines":["물통 · 여닫다 · 까슬까슬하다 · 손잡이 · 집다","묵직하다 · 뚜껑 · 찌그러지다 · 비좁다"],"title":"이야기에 나온 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_basic#6','kor',3,2,'u5','L06','g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C10',2,'mc','auto','같은 아홉 낱말을 ‘문장에 따라 모양이 바뀌는가’로 나누면, 모양이 바뀌는 낱말은 몇 개인가요?',ARRAY['K3-2-u5-X14','K3-2-u5-X09']::text[],false,'{"seq":6,"concept":"K3-2-u5-C10","difficulty":2,"kind":"mc","stem":"같은 아홉 낱말을 ‘문장에 따라 모양이 바뀌는가’로 나누면, 모양이 바뀌는 낱말은 몇 개인가요?","options":[{"t":"여섯 개","correct":true},{"t":"세 개","mis":"K3-2-u5-X14"},{"t":"아홉 개","mis":"K3-2-u5-X09"},{"t":"하나도 없다","mis":"K3-2-u5-X09"}],"explanation":["‘-고 · -으니 · -어서’를 붙여 봐요.","이름을 나타내는 셋은 안 붙어요.","나머지 여섯이에요."],"asset":{"type":"passage","lines":["물통 · 여닫다 · 까슬까슬하다 · 손잡이 · 집다","묵직하다 · 뚜껑 · 찌그러지다 · 비좁다"],"title":"이야기에 나온 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_basic#7','kor',3,2,'u5','L06','g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C15',2,'mc','auto','같은 아홉 낱말인데 나뉜 결과가 달라진 까닭은 무엇인가요?',ARRAY['K3-2-u5-X16','K3-2-u5-X14']::text[],false,'{"seq":7,"concept":"K3-2-u5-C15","difficulty":2,"kind":"mc","stem":"같은 아홉 낱말인데 나뉜 결과가 달라진 까닭은 무엇인가요?","options":[{"t":"나눈 기준이 달라졌기 때문에","correct":true},{"t":"앞에서 잘못 나누어서","mis":"K3-2-u5-X16"},{"t":"낱말마다 칸이 하나뿐인데 헷갈려서","mis":"K3-2-u5-X14"},{"t":"두 번째에 낱말이 바뀌어서","mis":"K3-2-u5-X16"}],"explanation":["두 번 나누는 동안 낱말은 그대로였어요.","보는 것이 달라졌어요.","기준이 달라졌어요."],"asset":{"type":"passage","lines":["기준 ① 낱말의 종류로 — 셋 · 셋 · 셋","기준 ② 모양이 바뀌는가로 — 여섯 · 셋"],"title":"같은 아홉 낱말을 두 번 나눈 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_basic#8','kor',3,2,'u5','L06','g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C4',2,'error','auto','아홉 낱말을 종류로 나누었어요. 잘못 나눈 친구는 누구인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":8,"concept":"K3-2-u5-C4","difficulty":2,"kind":"error","stem":"아홉 낱말을 종류로 나누었어요. 잘못 나눈 친구는 누구인가요?","options":[{"t":"친구 나 — 「‘묵직하다’는 움직임을 나타내.」","correct":true,"mis_target":"K3-2-u5-X05"},{"t":"친구 가 — 「‘여닫다’는 움직임을 나타내.」","mis":"K3-2-u5-X04"},{"t":"친구 다 — 「‘까슬까슬하다’는 성질이나 상태를 나타내.」","mis":"K3-2-u5-X04"}],"explanation":["“물통이 묵직하다”가 돼요.","어떠한지 말해요.","친구 나가 잘못 나누었어요."],"asset":{"type":"passage","lines":["물통 · 여닫다 · 까슬까슬하다 · 손잡이 · 집다","묵직하다 · 뚜껑 · 찌그러지다 · 비좁다"],"title":"이야기에 나온 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_basic#9','kor',3,2,'u5','L06','g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C14',2,'mc','auto','낱말 카드 한 더미를 받았어요. 먼저 할 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X14','K3-2-u5-X15']::text[],false,'{"seq":9,"concept":"K3-2-u5-C14","difficulty":2,"kind":"mc","stem":"낱말 카드 한 더미를 받았어요. 먼저 할 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“무엇을 보고 나눌지부터 정하자.”","correct":true},{"t":"“낱말마다 맞는 칸을 찾자.”","mis":"K3-2-u5-X14"},{"t":"“아무 데나 넣고 빨리 끝내자.”","mis":"K3-2-u5-X15"},{"t":"“카드를 다 외운 다음에 나누자.”","mis":"K3-2-u5-X15"}],"explanation":["오늘 같은 낱말을 두 번 나누었어요.","먼저 한 일은 기준 정하기였어요.","그 말을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_basic#10','kor',3,2,'u5','L06','g3_2_kor_u5_L06_basic','lesson_basic','K3-2-u5-C15',3,'error','auto','두 번 나눈 결과를 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X16','K3-2-u5-X14']::text[],false,'{"seq":10,"concept":"K3-2-u5-C15","difficulty":3,"kind":"error","stem":"두 번 나눈 결과를 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「두 번째가 다르게 나왔으니 첫 번째가 틀린 거야.」","correct":true,"mis_target":"K3-2-u5-X16"},{"t":"친구 가 — 「낱말은 그대로인데 기준이 달라졌어.」","mis":"K3-2-u5-X16"},{"t":"친구 나 — 「기준이 바뀌니 칸의 수도 달라졌어.」","mis":"K3-2-u5-X14"}],"explanation":["두 번 다 바르게 나누었어요.","보는 것이 달랐을 뿐이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["기준 ① 낱말의 종류로 — 셋 · 셋 · 셋","기준 ② 모양이 바뀌는가로 — 여섯 · 셋"],"title":"같은 아홉 낱말을 두 번 나눈 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_challenge#1','kor',3,2,'u5','L06','g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C14',2,'sa','auto','낱말을 나누기 전에 먼저 정하는, ‘무엇을 보고 나눌지’를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u5-C14","difficulty":2,"kind":"sa","stem":"낱말을 나누기 전에 먼저 정하는, ‘무엇을 보고 나눌지’를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["기준"],"explanation":["나누기 전에 정해요.","그것이 바뀌면 결과가 바뀌어요.","‘기준’이에요."],"mis":"K3-2-u5-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_challenge#2','kor',3,2,'u5','L06','g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C16',2,'mc','auto','이야기의 마지막 줄 “없던 것은 그것을 말할 낱말이었다.”에 담긴 뜻은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":2,"concept":"K3-2-u5-C16","difficulty":2,"kind":"mc","stem":"이야기의 마지막 줄 “없던 것은 그것을 말할 낱말이었다.”에 담긴 뜻은 무엇인가요?","options":[{"t":"알맞은 낱말을 알아야 원하는 것을 자세히 말할 수 있다","correct":true},{"t":"물통은 처음부터 상자에 없었다","mis":"K3-2-u5-X17"},{"t":"선생님이 물통을 숨겨 두셨다","mis":"K3-2-u5-X17"},{"t":"낱말을 몰라도 손짓으로 다 통한다","mis":"K3-2-u5-X17"}],"explanation":["물통은 거기 있었어요.","말할 낱말이 모자랐어요.","낱말이 있어야 자세해져요."],"asset":{"type":"passage","lines":["교실에서 짝이 물었다. “손잡이는 있어? 뚜껑은 어떻게 여닫아? 겉은 어때?”","하나씩 떠올랐다. 손잡이가 달렸고, 뚜껑을 돌려서 여닫고, 겉이 까슬까슬하고,","바닥이 조금 찌그러졌고, 물을 채우면 꽤 묵직했다.","그대로 말씀드리자 선생님은 상자에서 하나를 바로 집어 주셨다.","물통은 처음부터 거기 있었다. 없던 것은 그것을 말할 낱말이었다."],"title":"이야기 「잃어버린 것을 말하는 법」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_challenge#3','kor',3,2,'u5','L06','g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C4',3,'mc','auto','아홉 낱말을 종류로 나눌 때, 움직임을 나타내는 낱말끼리 모은 것은 무엇인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":3,"concept":"K3-2-u5-C4","difficulty":3,"kind":"mc","stem":"아홉 낱말을 종류로 나눌 때, 움직임을 나타내는 낱말끼리 모은 것은 무엇인가요?","options":[{"t":"여닫다 · 집다 · 찌그러지다","correct":true},{"t":"여닫다 · 집다 · 묵직하다","mis":"K3-2-u5-X05"},{"t":"집다 · 비좁다 · 손잡이","mis":"K3-2-u5-X04"},{"t":"찌그러지다 · 까슬까슬하다 · 뚜껑","mis":"K3-2-u5-X04"}],"explanation":["“○○을 한다”를 떠올려요.","‘바닥이 찌그러졌다’는 바뀐 일이에요.","여닫다·집다·찌그러지다예요."],"asset":{"type":"passage","lines":["물통 · 여닫다 · 까슬까슬하다 · 손잡이 · 집다","묵직하다 · 뚜껑 · 찌그러지다 · 비좁다"],"title":"이야기에 나온 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_challenge#4','kor',3,2,'u5','L06','g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C15',3,'mc','auto','아홉 낱말을 종류로 나누면 셋·셋·셋, 모양이 바뀌는가로 나누면 여섯·셋이었어요. 이 결과에서 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u5-X16','K3-2-u5-X14']::text[],false,'{"seq":4,"concept":"K3-2-u5-C15","difficulty":3,"kind":"mc","stem":"아홉 낱말을 종류로 나누면 셋·셋·셋, 모양이 바뀌는가로 나누면 여섯·셋이었어요. 이 결과에서 알 수 있는 것은 무엇인가요?","options":[{"t":"기준이 바뀌면 나뉜 칸의 수도, 든 낱말도 달라진다","correct":true},{"t":"둘 가운데 한 번은 잘못 나눈 것이다","mis":"K3-2-u5-X16"},{"t":"낱말은 언제나 세 칸으로 나뉜다","mis":"K3-2-u5-X14"},{"t":"여섯·셋으로 나눈 것이 더 바르다","mis":"K3-2-u5-X16"}],"explanation":["칸의 수가 달랐어요.","든 낱말도 달랐어요.","기준이 달랐기 때문이에요."],"asset":{"type":"passage","lines":["기준 ① 낱말의 종류로 — 셋 · 셋 · 셋","기준 ② 모양이 바뀌는가로 — 여섯 · 셋"],"title":"같은 아홉 낱말을 두 번 나눈 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_challenge#5','kor',3,2,'u5','L06','g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C14',3,'ox','auto','낱말마다 들어갈 칸은 하나로 정해져 있어서, 나누기 전에 기준을 정할 필요가 없어요.',ARRAY['K3-2-u5-X14']::text[],false,'{"seq":5,"concept":"K3-2-u5-C14","difficulty":3,"kind":"ox","stem":"낱말마다 들어갈 칸은 하나로 정해져 있어서, 나누기 전에 기준을 정할 필요가 없어요.","answer":"X","reason_options":[{"t":"같은 낱말도 기준에 따라 다른 칸에 들어가니 기준을 먼저 정해야 하기 때문에","correct":true},{"t":"낱말마다 정해진 칸을 외워 두면 되기 때문에","mis":"K3-2-u5-X14"}],"mis":"K3-2-u5-X14","explanation":["‘물통’은 기준 ①에서 이름 칸이었어요.","기준 ②에서는 안 바뀌는 칸이었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["기준 ① 낱말의 종류로 — 셋 · 셋 · 셋","기준 ② 모양이 바뀌는가로 — 여섯 · 셋"],"title":"같은 아홉 낱말을 두 번 나눈 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_challenge#6','kor',3,2,'u5','L06','g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C14',3,'error','auto','친구들이 같은 낱말을 서로 다르게 나누었어요. 바르게 생각하지 못한 친구는 누구인가요?',ARRAY['K3-2-u5-X16','K3-2-u5-X14','K3-2-u5-X15']::text[],false,'{"seq":6,"concept":"K3-2-u5-C14","difficulty":3,"kind":"error","stem":"친구들이 같은 낱말을 서로 다르게 나누었어요. 바르게 생각하지 못한 친구는 누구인가요?","options":[{"t":"친구 다 — 「서로 다르게 나뉘었으니 둘 중 하나는 틀렸어.」","correct":true,"mis_target":"K3-2-u5-X16"},{"t":"친구 가 — 「무엇을 보고 나누었는지 먼저 물어볼래.」","mis":"K3-2-u5-X14"},{"t":"친구 나 — 「기준이 다르면 결과가 다를 수 있어.」","mis":"K3-2-u5-X15"}],"explanation":["결과보다 기준을 먼저 봐요.","기준이 다르면 결과도 달라요.","친구 다가 바르게 생각하지 못했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_challenge#7','kor',3,2,'u5','L06','g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C15',3,'mc','auto','기준 ①(종류)에서 서로 다른 칸이었던 ‘여닫다’와 ‘묵직하다’는 기준 ②(모양이 바뀌는가)에서 어떻게 되나요?',ARRAY['K3-2-u5-X14','K3-2-u5-X09','K3-2-u5-X16']::text[],false,'{"seq":7,"concept":"K3-2-u5-C15","difficulty":3,"kind":"mc","stem":"기준 ①(종류)에서 서로 다른 칸이었던 ‘여닫다’와 ‘묵직하다’는 기준 ②(모양이 바뀌는가)에서 어떻게 되나요?","options":[{"t":"둘 다 모양이 바뀌는 칸, 곧 같은 칸에 들어간다","correct":true},{"t":"기준 ②에서도 언제나 다른 칸이다","mis":"K3-2-u5-X14"},{"t":"둘 다 모양이 바뀌지 않는 칸에 들어간다","mis":"K3-2-u5-X09"},{"t":"기준 ①에서 잘못 나누었으니 다시 나누어야 한다","mis":"K3-2-u5-X16"}],"explanation":["‘여닫다’는 여닫고·여닫으니로 바뀌어요.","‘묵직하다’도 묵직하고·묵직하니로 바뀌어요.","기준 ②에서는 같은 칸이에요."],"asset":{"type":"passage","lines":["물통 · 여닫다 · 까슬까슬하다 · 손잡이 · 집다","묵직하다 · 뚜껑 · 찌그러지다 · 비좁다"],"title":"이야기에 나온 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_challenge#8','kor',3,2,'u5','L06','g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C15',4,'mc','auto','아홉 낱말을 이번에는 ‘글자 수가 세 글자보다 적은가’로 나누려고 해요. 두 글자인 낱말만 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u5-X15']::text[],false,'{"seq":8,"concept":"K3-2-u5-C15","difficulty":4,"kind":"mc","stem":"아홉 낱말을 이번에는 ‘글자 수가 세 글자보다 적은가’로 나누려고 해요. 두 글자인 낱말만 바르게 모은 것은 무엇인가요?","options":[{"t":"물통 · 뚜껑 · 집다","correct":true},{"t":"물통 · 뚜껑 · 손잡이","mis":"K3-2-u5-X15"},{"t":"집다 · 여닫다 · 비좁다","mis":"K3-2-u5-X15"},{"t":"물통 · 집다 · 묵직하다","mis":"K3-2-u5-X15"}],"explanation":["글자 수를 세어 봐요.","손잡이·여닫다는 세 글자예요.","물통·뚜껑·집다예요."],"asset":{"type":"passage","lines":["물통 · 여닫다 · 까슬까슬하다 · 손잡이 · 집다","묵직하다 · 뚜껑 · 찌그러지다 · 비좁다"],"title":"이야기에 나온 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_challenge#9','kor',3,2,'u5','L06','g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C15',4,'essay','teacher','같은 아홉 낱말을 두 기준으로 나눈 결과가 달라진 까닭을 쓰고, 「앞에서 잘못 나눠서 그래.」라고 말한 친구에게 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u5-C15","difficulty":4,"kind":"essay","stem":"같은 아홉 낱말을 두 기준으로 나눈 결과가 달라진 까닭을 쓰고, 「앞에서 잘못 나눠서 그래.」라고 말한 친구에게 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 낱말은 하나도 바뀌지 않았지만 무엇을 보고 나누었는지, 곧 기준이 달라졌기 때문에 결과가 달라졌다. 친구에게는 “두 번 다 바르게 나눈 거야. 기준 ①은 종류를, 기준 ②는 모양이 바뀌는지를 보았으니 결과가 다를 수밖에 없어.”라고 말해 주겠다.","scoring_points":["기준이 달라졌다고 썼는가","낱말은 그대로라고 썼는가","두 번 다 바르게 나눈 것이라고 친구에게 말했는가"]},"explanation":["달라진 것은 기준이에요.","낱말은 그대로예요.","잘못 나눈 것이 아니에요."],"asset":{"type":"passage","lines":["기준 ① 낱말의 종류로 — 셋 · 셋 · 셋","기준 ② 모양이 바뀌는가로 — 여섯 · 셋"],"title":"같은 아홉 낱말을 두 번 나눈 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L06_challenge#10','kor',3,2,'u5','L06','g3_2_kor_u5_L06_challenge','lesson_challenge','K3-2-u5-C14',4,'essay','teacher','낱말 카드 한 더미를 받았을 때 먼저 할 일을 쓰고, 「낱말마다 정해진 칸이 있어.」라는 생각이 왜 알맞지 않은지 이야기의 아홉 낱말을 예로 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u5-C14","difficulty":4,"kind":"essay","stem":"낱말 카드 한 더미를 받았을 때 먼저 할 일을 쓰고, 「낱말마다 정해진 칸이 있어.」라는 생각이 왜 알맞지 않은지 이야기의 아홉 낱말을 예로 들어 쓰세요.","answer_guide":{"answer":"예: 먼저 무엇을 보고 나눌지 기준을 정한다. 낱말마다 정해진 칸이 있는 것이 아니다. ‘비좁다’는 종류로 나누면 성질이나 상태 칸에 들어가지만, 모양이 바뀌는가로 나누면 모양이 바뀌는 칸에 들어간다. 기준에 따라 들어가는 칸이 달라진다.","scoring_points":["기준을 먼저 정한다고 썼는가","아홉 낱말 가운데 하나를 예로 들었는가","기준에 따라 칸이 달라진다고 썼는가"]},"explanation":["기준부터 정해요.","한 낱말을 두 기준에 넣어 봐요.","칸이 달라져요."],"asset":{"type":"passage","lines":["물통 · 여닫다 · 까슬까슬하다 · 손잡이 · 집다","묵직하다 · 뚜껑 · 찌그러지다 · 비좁다"],"title":"이야기에 나온 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_basic#1','kor',3,2,'u5','L08','g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C17',1,'match','auto','‘손’의 짜임을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u5-C17","difficulty":1,"kind":"match","stem":"‘손’의 짜임을 알맞게 이으세요.","pairs":[{"l":"첫 자음자","r":"ㅅ"},{"l":"모음자","r":"ㅗ"},{"l":"받침","r":"ㄴ"}],"mis":"K3-2-u5-X18","explanation":["천천히 소리 내어 읽어요.","셋으로 나뉘어 들려요.","ㅅ · ㅗ · ㄴ이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_basic#2','kor',3,2,'u5','L08','g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C18',1,'mc','auto','‘나비’와 ‘다리’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X19','K3-2-u5-X22']::text[],false,'{"seq":2,"concept":"K3-2-u5-C18","difficulty":1,"kind":"mc","stem":"‘나비’와 ‘다리’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?","options":[{"t":"나비","correct":true},{"t":"다리","mis":"K3-2-u5-X19"},{"t":"둘이 같은 쪽에 함께 실린다","mis":"K3-2-u5-X19"},{"t":"글자 수가 적은 낱말","mis":"K3-2-u5-X22"}],"explanation":["첫 자음자만 봐요.","ㄴ이 ㄷ보다 앞이에요.","‘나비’가 먼저예요."],"asset":{"type":"passage","lines":["ㄱ ㄲ ㄴ ㄷ ㄸ ㄹ ㅁ ㅂ ㅃ ㅅ ㅆ ㅇ ㅈ ㅉ ㅊ ㅋ ㅌ ㅍ ㅎ"],"title":"첫 자음자의 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_basic#3','kor',3,2,'u5','L08','g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C19',1,'mc','auto','‘바람’과 ‘보람’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X20','K3-2-u5-X22']::text[],false,'{"seq":3,"concept":"K3-2-u5-C19","difficulty":1,"kind":"mc","stem":"‘바람’과 ‘보람’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?","options":[{"t":"바람","correct":true},{"t":"보람","mis":"K3-2-u5-X20"},{"t":"둘이 같은 쪽에 함께 실린다","mis":"K3-2-u5-X20"},{"t":"글자 수가 적은 낱말","mis":"K3-2-u5-X22"}],"explanation":["첫 자음자는 ㅂ으로 같아요.","모음자를 봐요.","ㅏ가 ㅗ보다 앞이에요."],"asset":{"type":"passage","lines":["ㅏ ㅐ ㅑ ㅒ ㅓ ㅔ ㅕ ㅖ ㅗ ㅘ ㅙ ㅚ ㅛ ㅜ ㅝ ㅞ ㅟ ㅠ ㅡ ㅢ ㅣ"],"title":"모음자의 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_basic#4','kor',3,2,'u5','L08','g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C23',1,'mc','auto','국어사전에서 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u5-X24']::text[],false,'{"seq":4,"concept":"K3-2-u5-C23","difficulty":1,"kind":"mc","stem":"국어사전에서 알 수 있는 것은 무엇인가요?","options":[{"t":"낱말의 뜻과 소리 내어 읽는 법","correct":true},{"t":"그 낱말을 처음 만든 사람","mis":"K3-2-u5-X24"},{"t":"그 낱말을 그림으로 그리는 법","mis":"K3-2-u5-X24"},{"t":"그 낱말을 가장 많이 쓰는 사람","mis":"K3-2-u5-X24"}],"explanation":["사전을 펴 봐요.","뜻이 적혀 있어요.","읽는 법과 쓰인 문장도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_basic#5','kor',3,2,'u5','L08','g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C20',2,'mc','auto','‘다리’와 ‘달’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X21','K3-2-u5-X22']::text[],false,'{"seq":5,"concept":"K3-2-u5-C20","difficulty":2,"kind":"mc","stem":"‘다리’와 ‘달’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?","options":[{"t":"다리","correct":true},{"t":"달","mis":"K3-2-u5-X21"},{"t":"둘이 같은 쪽에 함께 실린다","mis":"K3-2-u5-X21"},{"t":"글자 수가 적은 낱말","mis":"K3-2-u5-X22"}],"explanation":["첫 글자는 ‘다’와 ‘달’이에요.","‘다’는 받침이 없어요.","받침이 없는 쪽이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_basic#6','kor',3,2,'u5','L08','g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C21',2,'mc','auto','‘모래밭’과 ‘모래알’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X22']::text[],false,'{"seq":6,"concept":"K3-2-u5-C21","difficulty":2,"kind":"mc","stem":"‘모래밭’과 ‘모래알’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?","options":[{"t":"모래밭","correct":true},{"t":"모래알","mis":"K3-2-u5-X22"},{"t":"둘이 같은 쪽에 함께 실린다","mis":"K3-2-u5-X22"},{"t":"글자 수가 적은 낱말","mis":"K3-2-u5-X22"}],"explanation":["‘모래’까지 같아요.","세 번째 글자를 봐요.","ㅂ이 ㅇ보다 앞이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_basic#7','kor',3,2,'u5','L08','g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C22',2,'mc','auto','‘찌그러졌고’를 국어사전에서 찾으려면 무엇으로 찾아야 하나요?',ARRAY['K3-2-u5-X23','K3-2-u5-X11']::text[],false,'{"seq":7,"concept":"K3-2-u5-C22","difficulty":2,"kind":"mc","stem":"‘찌그러졌고’를 국어사전에서 찾으려면 무엇으로 찾아야 하나요?","options":[{"t":"찌그러지다","correct":true},{"t":"찌그러졌고","mis":"K3-2-u5-X23"},{"t":"찌그러졌다","mis":"K3-2-u5-X23"},{"t":"찌그러","mis":"K3-2-u5-X11"}],"explanation":["사전엔 기본형이 실려요.","바뀌지 않는 부분에 ‘-다’를 붙여요.","‘찌그러지다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_basic#8','kor',3,2,'u5','L08','g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C18',2,'mc','auto','첫 자음자의 차례에서 ‘ㄲ’은 어디에 있나요?',ARRAY['K3-2-u5-X19']::text[],false,'{"seq":8,"concept":"K3-2-u5-C18","difficulty":2,"kind":"mc","stem":"첫 자음자의 차례에서 ‘ㄲ’은 어디에 있나요?","options":[{"t":"ㄱ 바로 다음, ㄴ 앞","correct":true},{"t":"ㅎ 다음, 맨 뒤","mis":"K3-2-u5-X19"},{"t":"ㄴ과 ㄷ 사이","mis":"K3-2-u5-X19"},{"t":"ㅅ 바로 다음","mis":"K3-2-u5-X19"}],"explanation":["ㄱ ㄲ ㄴ ㄷ ㄸ ….","쌍자음자는 홑자음자 바로 뒤예요.","ㄱ 다음이에요."],"asset":{"type":"passage","lines":["ㄱ ㄲ ㄴ ㄷ ㄸ ㄹ ㅁ ㅂ ㅃ ㅅ ㅆ ㅇ ㅈ ㅉ ㅊ ㅋ ㅌ ㅍ ㅎ"],"title":"첫 자음자의 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_basic#9','kor',3,2,'u5','L08','g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C23',2,'ox','auto','국어사전에는 낱말의 뜻만 적혀 있어요.',ARRAY['K3-2-u5-X24']::text[],false,'{"seq":9,"concept":"K3-2-u5-C23","difficulty":2,"kind":"ox","stem":"국어사전에는 낱말의 뜻만 적혀 있어요.","answer":"X","reason_options":[{"t":"뜻과 함께 소리 내어 읽는 법과 그 낱말이 쓰인 문장도 실려 있기 때문에","correct":true},{"t":"사전은 뜻을 풀이하려고 만든 책이라 뜻 말고는 없기 때문에","mis":"K3-2-u5-X24"}],"mis":"K3-2-u5-X24","explanation":["한 낱말 옆을 들여다봐요.","읽는 법도, 쓰인 문장도 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_basic#10','kor',3,2,'u5','L08','g3_2_kor_u5_L08_basic','lesson_basic','K3-2-u5-C23',3,'error','auto','국어사전에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X13','K3-2-u5-X24']::text[],false,'{"seq":10,"concept":"K3-2-u5-C23","difficulty":3,"kind":"error","stem":"국어사전에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「‘찌그러졌고’처럼 바뀐 모양까지 모두 실려 있어.」","correct":true,"mis_target":"K3-2-u5-X13"},{"t":"친구 가 — 「낱말이 쓰인 문장도 함께 실려 있어.」","mis":"K3-2-u5-X24"},{"t":"친구 나 — 「낱말을 정해진 차례로 실어 두었어.」","mis":"K3-2-u5-X24"}],"explanation":["사전엔 대표 모양이 실려요.","바뀐 모양은 기본형으로 찾아요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_challenge#1','kor',3,2,'u5','L08','g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C17',2,'sa','auto','‘달’의 받침은 무엇인가요? 자음자 하나로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u5-C17","difficulty":2,"kind":"sa","stem":"‘달’의 받침은 무엇인가요? 자음자 하나로 쓰세요.","answer":["ㄹ"],"explanation":["‘달’을 셋으로 나눠요.","ㄷ · ㅏ · ㄹ이에요.","받침은 ‘ㄹ’이에요."],"mis":"K3-2-u5-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_challenge#2','kor',3,2,'u5','L08','g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C20',2,'mc','auto','첫 자음자와 모음자가 같을 때, 받침은 어떤 차례로 보나요?',ARRAY['K3-2-u5-X21']::text[],false,'{"seq":2,"concept":"K3-2-u5-C20","difficulty":2,"kind":"mc","stem":"첫 자음자와 모음자가 같을 때, 받침은 어떤 차례로 보나요?","options":[{"t":"받침이 없는 글자가 먼저, 그다음 받침 ㄱ · ㄴ · ㄷ · ㄹ … 차례","correct":true},{"t":"받침이 있는 글자가 먼저","mis":"K3-2-u5-X21"},{"t":"받침이 많은 글자가 먼저","mis":"K3-2-u5-X21"},{"t":"받침은 차례와 상관없다","mis":"K3-2-u5-X21"}],"explanation":["‘다’와 ‘달’을 떠올려요.","받침 없는 ‘다’가 먼저였어요.","그다음 ㄱ·ㄴ·ㄷ·ㄹ 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
