INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_challenge#5','kor',3,2,'u5','L08','g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C21',3,'mc','auto','‘다람쥐’와 ‘달’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X22']::text[],false,'{"seq":5,"concept":"K3-2-u5-C21","difficulty":3,"kind":"mc","stem":"‘다람쥐’와 ‘달’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?","options":[{"t":"다람쥐","correct":true},{"t":"달","mis":"K3-2-u5-X22"},{"t":"둘이 같은 쪽에 함께 실린다","mis":"K3-2-u5-X22"},{"t":"글자 수가 적은 낱말","mis":"K3-2-u5-X22"}],"explanation":["첫 글자는 ‘다’와 ‘달’이에요.","받침 없는 ‘다’가 먼저예요.","긴 낱말이어도 ‘다람쥐’가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_challenge#6','kor',3,2,'u5','L08','g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C21',3,'mc','auto','‘눈사람’과 ‘눈썰매’의 차례를 정할 때, 무엇을 견주어야 하나요?',ARRAY['K3-2-u5-X21','K3-2-u5-X22','K3-2-u5-X18']::text[],false,'{"seq":6,"concept":"K3-2-u5-C21","difficulty":3,"kind":"mc","stem":"‘눈사람’과 ‘눈썰매’의 차례를 정할 때, 무엇을 견주어야 하나요?","options":[{"t":"두 번째 글자의 첫 자음자 ㅅ과 ㅆ","correct":true},{"t":"첫 글자 ‘눈’의 받침","mis":"K3-2-u5-X21"},{"t":"두 낱말의 글자 수","mis":"K3-2-u5-X22"},{"t":"두 번째 글자의 받침","mis":"K3-2-u5-X18"}],"explanation":["첫 글자 ‘눈’은 같아요.","두 번째 글자를 봐요.","ㅅ과 ㅆ을 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_challenge#7','kor',3,2,'u5','L08','g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C22',3,'error','auto','“바닥이 조금 찌그러졌고”의 ‘찌그러졌고’를 찾으려고 했어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K3-2-u5-X23','K3-2-u5-X24']::text[],false,'{"seq":7,"concept":"K3-2-u5-C22","difficulty":3,"kind":"error","stem":"“바닥이 조금 찌그러졌고”의 ‘찌그러졌고’를 찾으려고 했어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"친구 가 — 「ㅉ 쪽을 펴서 ‘찌그러졌고’를 그대로 찾아봐야지.」","correct":true,"mis_target":"K3-2-u5-X23"},{"t":"친구 나 — 「먼저 ‘찌그러지다’로 바꾸고 펴야지.」","mis":"K3-2-u5-X23"},{"t":"친구 다 — 「‘찌그러지다’를 찾으면 쓰인 문장도 볼 수 있어.」","mis":"K3-2-u5-X24"}],"explanation":["사전엔 바뀐 모양이 없어요.","기본형으로 되돌려요.","친구 가가 잘못 찾았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_challenge#8','kor',3,2,'u5','L08','g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C18',4,'mc','auto','네 낱말을 국어사전에 실리는 차례대로 늘어놓은 것은 무엇인가요?',ARRAY['K3-2-u5-X19','K3-2-u5-X22']::text[],false,'{"seq":8,"concept":"K3-2-u5-C18","difficulty":4,"kind":"mc","stem":"네 낱말을 국어사전에 실리는 차례대로 늘어놓은 것은 무엇인가요?","options":[{"t":"거울 → 꽃게 → 다람쥐 → 바늘","correct":true},{"t":"다람쥐 → 바늘 → 거울 → 꽃게","mis":"K3-2-u5-X19"},{"t":"꽃게 → 거울 → 다람쥐 → 바늘","mis":"K3-2-u5-X19"},{"t":"바늘 → 거울 → 꽃게 → 다람쥐","mis":"K3-2-u5-X22"}],"explanation":["첫 자음자는 ㄱ·ㄲ·ㄷ·ㅂ이에요.","ㄱ 다음이 ㄲ이에요.","거울 → 꽃게 → 다람쥐 → 바늘이에요."],"asset":{"type":"passage","lines":["ㄱ ㄲ ㄴ ㄷ ㄸ ㄹ ㅁ ㅂ ㅃ ㅅ ㅆ ㅇ ㅈ ㅉ ㅊ ㅋ ㅌ ㅍ ㅎ"],"title":"첫 자음자의 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_challenge#9','kor',3,2,'u5','L08','g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C21',4,'essay','teacher','‘모래밭’과 ‘모래알’ 가운데 국어사전에 먼저 실리는 낱말을 쓰고, 차례를 정한 방법을 처음부터 순서대로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u5-C21","difficulty":4,"kind":"essay","stem":"‘모래밭’과 ‘모래알’ 가운데 국어사전에 먼저 실리는 낱말을 쓰고, 차례를 정한 방법을 처음부터 순서대로 쓰세요.","answer_guide":{"answer":"예: ‘모래밭’이 먼저 실린다. 첫 글자 ‘모’가 같으니 두 번째 글자를 보고, ‘래’도 같으니 세 번째 글자를 본다. ‘밭’의 첫 자음자 ㅂ이 ‘알’의 첫 자음자 ㅇ보다 앞이므로 ‘모래밭’이 먼저이다.","scoring_points":["‘모래밭’이 먼저라고 썼는가","같은 글자를 지나 세 번째 글자를 본다고 썼는가","ㅂ이 ㅇ보다 앞이라고 썼는가"]},"explanation":["같은 글자는 넘어가요.","다음 글자를 같은 방법으로 봐요.","ㅂ과 ㅇ을 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L08_challenge#10','kor',3,2,'u5','L08','g3_2_kor_u5_L08_challenge','lesson_challenge','K3-2-u5-C23',4,'essay','teacher','「국어사전은 낱말의 뜻만 적힌 책이야.」라고 말하는 친구에게 사전에 실린 것을 두 가지 이상 들어 설명하고, 바뀐 모양은 어떻게 찾는지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u5-C23","difficulty":4,"kind":"essay","stem":"「국어사전은 낱말의 뜻만 적힌 책이야.」라고 말하는 친구에게 사전에 실린 것을 두 가지 이상 들어 설명하고, 바뀐 모양은 어떻게 찾는지도 쓰세요.","answer_guide":{"answer":"예: 사전에는 낱말의 뜻뿐 아니라 소리 내어 읽는 법과 그 낱말이 쓰인 문장도 함께 실려 있다. 다만 ‘찌그러졌고’처럼 모양이 바뀐 낱말은 그대로 실려 있지 않으니 ‘찌그러지다’처럼 기본형으로 바꾸어 찾아야 한다.","scoring_points":["뜻 말고 실린 것을 두 가지 이상 썼는가","바뀐 모양은 그대로 실려 있지 않다고 썼는가","기본형으로 찾는다고 썼는가"]},"explanation":["뜻 말고도 있어요.","바뀐 모양은 없어요.","기본형으로 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_basic#1','kor',3,2,'u5','L10','g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C24',1,'mc','auto','‘어귀’의 뜻을 앞뒤 문장으로 짐작한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":1,"concept":"K3-2-u5-C24","difficulty":1,"kind":"mc","stem":"‘어귀’의 뜻을 앞뒤 문장으로 짐작한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"드나드는 곳의 첫머리","correct":true},{"t":"건물의 가장 높은 층","mis":"K3-2-u5-X25"},{"t":"문을 여는 시각","mis":"K3-2-u5-X25"},{"t":"운동장의 한가운데","mis":"K3-2-u5-X25"}],"explanation":["1~2번 줄을 이어 읽어요.","처음 오는 사람이 들어오는 곳이에요.","들어오는 곳의 첫머리예요."],"asset":{"type":"passage","lines":["1 학교에 처음 오는 사람은 어디로 들어와야 할지 모른다.","2 그래서 안내도에는 정문 어귀를 가장 먼저 그린다.","3 다음으로 건물의 모양을 그린다.","4 건물이 운동장을 에워싼 학교도 있고, 한쪽에만 붙은 학교도 있다.","5 건물 안으로 들어가는 문도 표시한다."],"title":"설명하는 글 「학교 안내도를 만드는 법」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_basic#2','kor',3,2,'u5','L10','g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C2',1,'mc','auto','글을 읽다가 모르는 낱말이 나왔어요. 어떻게 읽을까요?',ARRAY['K3-2-u5-X02','K3-2-u5-X03','K3-2-u5-X01']::text[],false,'{"seq":2,"concept":"K3-2-u5-C2","difficulty":1,"kind":"mc","stem":"글을 읽다가 모르는 낱말이 나왔어요. 어떻게 읽을까요?","options":[{"t":"앞뒤로 짐작하며 끝까지 읽고, 다 읽은 뒤에 확인한다","correct":true},{"t":"나올 때마다 멈추어 사전을 찾는다","mis":"K3-2-u5-X02"},{"t":"짐작만 하고 확인하지 않는다","mis":"K3-2-u5-X03"},{"t":"모르는 낱말은 빼고 읽는다","mis":"K3-2-u5-X01"}],"explanation":["멈추면 글의 흐름을 놓쳐요.","짐작만 하면 틀린 채로 알아요.","짐작하고, 뒤에 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_basic#3','kor',3,2,'u5','L10','g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C26',1,'mc','auto','비탈진 길을 다르게 표시하는 까닭은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":3,"concept":"K3-2-u5-C26","difficulty":1,"kind":"mc","stem":"비탈진 길을 다르게 표시하는 까닭은 무엇인가요?","options":[{"t":"유모차나 휠체어로 다니는 사람이 길을 고를 수 있게","correct":true},{"t":"안내도를 더 예쁘게 꾸미려고","mis":"K3-2-u5-X17"},{"t":"안내도의 크기를 키우려고","mis":"K3-2-u5-X17"},{"t":"비탈진 길은 다니면 안 되어서","mis":"K3-2-u5-X17"}],"explanation":["7번 줄을 다시 읽어요.","길을 고를 수 있다고 했어요.","그래서 다르게 표시해요."],"asset":{"type":"passage","lines":["6 길도 그린다. 평평한 길과 비탈진 길을 다르게 표시한다.","7 그렇게 해 두면 유모차나 휠체어로 다니는 사람이 길을 고를 수 있다.","8 문도 나누어 적는다. 밀거나 당겨서 여는 여닫이 문인지,","   옆으로 미는 문인지 적어 둔다.","9 걸리는 시간도 적는다. “정문에서 도서관까지 오 분 남짓”처럼 적으면","   처음 온 사람이 셈하기 쉽다.","10 안내도는 그림만으로는 모자라다. 낱말이 있어야 자세해진다."],"title":"설명하는 글 「학교 안내도를 만드는 법」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_basic#4','kor',3,2,'u5','L10','g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C24',1,'match','auto','글에 나온 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u5-C24","difficulty":1,"kind":"match","stem":"글에 나온 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"비탈","r":"땅이 기울어진 곳"},{"l":"여닫이","r":"밀거나 당겨서 여는 문"},{"l":"남짓","r":"어느 만큼을 채우고 조금 남는 정도"}],"mis":"K3-2-u5-X25","explanation":["그 낱말이 나온 줄을 다시 읽어요.","앞뒤가 실마리예요.","셋을 하나씩 이어요."],"asset":{"type":"passage","lines":["6 길도 그린다. 평평한 길과 비탈진 길을 다르게 표시한다.","7 그렇게 해 두면 유모차나 휠체어로 다니는 사람이 길을 고를 수 있다.","8 문도 나누어 적는다. 밀거나 당겨서 여는 여닫이 문인지,","   옆으로 미는 문인지 적어 둔다.","9 걸리는 시간도 적는다. “정문에서 도서관까지 오 분 남짓”처럼 적으면","   처음 온 사람이 셈하기 쉽다.","10 안내도는 그림만으로는 모자라다. 낱말이 있어야 자세해진다."],"title":"설명하는 글 「학교 안내도를 만드는 법」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_basic#5','kor',3,2,'u5','L10','g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C25',2,'mc','auto','‘비탈’을 “울퉁불퉁한 길”로 짐작했는데 사전에는 “땅이 기울어진 곳”으로 나와 있었어요. 어떻게 할까요?',ARRAY['K3-2-u5-X26','K3-2-u5-X03']::text[],false,'{"seq":5,"concept":"K3-2-u5-C25","difficulty":2,"kind":"mc","stem":"‘비탈’을 “울퉁불퉁한 길”로 짐작했는데 사전에는 “땅이 기울어진 곳”으로 나와 있었어요. 어떻게 할까요?","options":[{"t":"사전의 뜻으로 고쳐 알고, 그 줄을 다시 읽어 본다","correct":true},{"t":"내 짐작이 틀렸으니 이 글은 못 읽는다","mis":"K3-2-u5-X26"},{"t":"내 짐작이 맞으니 사전이 틀렸다","mis":"K3-2-u5-X26"},{"t":"짐작한 뜻을 그대로 두고 다음 글로 넘어간다","mis":"K3-2-u5-X03"}],"explanation":["짐작은 사전을 펴기 위한 것이었어요.","빗나가면 고쳐 알아요.","그 줄을 다시 읽어요."],"asset":{"type":"speech","turns":[{"who":"내가 짐작한 뜻","text":"‘비탈’ — “울퉁불퉁한 길”"},{"who":"사전에서 찾은 뜻","text":"‘비탈’ — “땅이 기울어진 곳”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_basic#6','kor',3,2,'u5','L10','g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C25',2,'ox','auto','같은 낱말인데 두 사전의 뜻풀이 말이 조금 다르면, 둘 가운데 하나는 틀린 거예요.',ARRAY['K3-2-u5-X27']::text[],false,'{"seq":6,"concept":"K3-2-u5-C25","difficulty":2,"kind":"ox","stem":"같은 낱말인데 두 사전의 뜻풀이 말이 조금 다르면, 둘 가운데 하나는 틀린 거예요.","answer":"X","reason_options":[{"t":"사전마다 말이 조금씩 달라도 뜻이 같으면 되기 때문에","correct":true},{"t":"바른 뜻풀이는 어느 사전에서나 글자까지 같아야 하기 때문에","mis":"K3-2-u5-X27"}],"mis":"K3-2-u5-X27","explanation":["뜻풀이 말은 사전마다 달라요.","뜻이 같으면 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_basic#7','kor',3,2,'u5','L10','g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C24',2,'mc','auto','모르는 낱말의 뜻을 짐작하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X25','K3-2-u5-X01']::text[],false,'{"seq":7,"concept":"K3-2-u5-C24","difficulty":2,"kind":"mc","stem":"모르는 낱말의 뜻을 짐작하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"앞뒤 문장을 살피고, 아는 다른 말로 바꾸어 읽어 본다","correct":true},{"t":"낱말의 소리가 비슷한 말을 떠올려 정한다","mis":"K3-2-u5-X25"},{"t":"글자 수를 세어 정한다","mis":"K3-2-u5-X25"},{"t":"짐작하지 않고 바로 건너뛴다","mis":"K3-2-u5-X01"}],"explanation":["앞뒤 문장이 실마리예요.","다른 말로 바꾸어 읽어요.","뜻이 통하면 가까이 간 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_basic#8','kor',3,2,'u5','L10','g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C26',2,'mc','auto','국어사전을 쓰며 글을 읽으면 좋은 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u5-X28']::text[],false,'{"seq":8,"concept":"K3-2-u5-C26","difficulty":2,"kind":"mc","stem":"국어사전을 쓰며 글을 읽으면 좋은 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"글을 더 빨리 읽을 수 있다","correct":true},{"t":"글의 내용을 정확하게 알 수 있다","mis":"K3-2-u5-X28"},{"t":"내가 짐작한 뜻이 맞는지 확인할 수 있다","mis":"K3-2-u5-X28"},{"t":"아는 낱말이 늘어난다","mis":"K3-2-u5-X28"}],"explanation":["사전을 펴면 시간은 더 걸려요.","대신 글이 또렷해져요.","빨리 읽기는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_basic#9','kor',3,2,'u5','L10','g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C24',2,'mc','auto','“건물이 운동장을 에워싼 학교”에서 ‘에워싼’의 뜻을 짐작한 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X17','K3-2-u5-X25']::text[],false,'{"seq":9,"concept":"K3-2-u5-C24","difficulty":2,"kind":"mc","stem":"“건물이 운동장을 에워싼 학교”에서 ‘에워싼’의 뜻을 짐작한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"운동장 둘레를 빙 둘러싼","correct":true},{"t":"운동장 한쪽에만 붙은","mis":"K3-2-u5-X17"},{"t":"운동장보다 높이 솟은","mis":"K3-2-u5-X25"},{"t":"운동장 밖으로 멀리 떨어진","mis":"K3-2-u5-X25"}],"explanation":["뒤 문장과 견주어요.","‘한쪽에만 붙은 학교’와 달라요.","둘레를 둘러싼 거예요."],"asset":{"type":"passage","lines":["1 학교에 처음 오는 사람은 어디로 들어와야 할지 모른다.","2 그래서 안내도에는 정문 어귀를 가장 먼저 그린다.","3 다음으로 건물의 모양을 그린다.","4 건물이 운동장을 에워싼 학교도 있고, 한쪽에만 붙은 학교도 있다.","5 건물 안으로 들어가는 문도 표시한다."],"title":"설명하는 글 「학교 안내도를 만드는 법」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_basic#10','kor',3,2,'u5','L10','g3_2_kor_u5_L10_basic','lesson_basic','K3-2-u5-C2',3,'error','auto','「학교 안내도를 만드는 법」을 읽는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X02','K3-2-u5-X03']::text[],false,'{"seq":10,"concept":"K3-2-u5-C2","difficulty":3,"kind":"error","stem":"「학교 안내도를 만드는 법」을 읽는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「‘어귀’가 나오면 거기서 멈추고 사전부터 찾아야 해.」","correct":true,"mis_target":"K3-2-u5-X02"},{"t":"친구 가 — 「모르는 낱말은 공책에 적어 두고 끝까지 읽어.」","mis":"K3-2-u5-X02"},{"t":"친구 다 — 「다 읽고 나서 적어 둔 낱말을 사전에서 확인해.」","mis":"K3-2-u5-X03"}],"explanation":["지금은 멈추지 않고 끝까지 읽어요.","확인은 다 읽은 뒤에 해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_challenge#1','kor',3,2,'u5','L10','g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C24',2,'sa','auto','“정문에서 도서관까지 오 분 ○○”의 빈칸에 들어갈, 어느 만큼을 채우고 조금 남는 정도를 뜻하는 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u5-C24","difficulty":2,"kind":"sa","stem":"“정문에서 도서관까지 오 분 ○○”의 빈칸에 들어갈, 어느 만큼을 채우고 조금 남는 정도를 뜻하는 두 글자 낱말을 쓰세요.","answer":["남짓"],"explanation":["9번 줄을 봐요.","오 분을 조금 넘는다는 뜻이에요.","‘남짓’이에요."],"mis":"K3-2-u5-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_challenge#2','kor',3,2,'u5','L10','g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C26',2,'mc','auto','이 글에서 「안내도는 그림만으로는 모자라다.」라고 한 까닭은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":2,"concept":"K3-2-u5-C26","difficulty":2,"kind":"mc","stem":"이 글에서 「안내도는 그림만으로는 모자라다.」라고 한 까닭은 무엇인가요?","options":[{"t":"낱말이 있어야 길·문·시간을 자세히 알릴 수 있어서","correct":true},{"t":"그림은 그리기 어려워서","mis":"K3-2-u5-X17"},{"t":"안내도에는 그림이 필요 없어서","mis":"K3-2-u5-X17"},{"t":"낱말이 그림보다 더 예뻐서","mis":"K3-2-u5-X17"}],"explanation":["비탈·여닫이·남짓을 떠올려요.","그림만으로는 다 못 알려요.","낱말이 자세하게 해 줘요."],"asset":{"type":"passage","lines":["6 길도 그린다. 평평한 길과 비탈진 길을 다르게 표시한다.","7 그렇게 해 두면 유모차나 휠체어로 다니는 사람이 길을 고를 수 있다.","8 문도 나누어 적는다. 밀거나 당겨서 여는 여닫이 문인지,","   옆으로 미는 문인지 적어 둔다.","9 걸리는 시간도 적는다. “정문에서 도서관까지 오 분 남짓”처럼 적으면","   처음 온 사람이 셈하기 쉽다.","10 안내도는 그림만으로는 모자라다. 낱말이 있어야 자세해진다."],"title":"설명하는 글 「학교 안내도를 만드는 법」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_challenge#3','kor',3,2,'u5','L10','g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C25',3,'mc','auto','짐작한 뜻이 사전의 뜻과 달랐을 때 생각한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X26','K3-2-u5-X03']::text[],false,'{"seq":3,"concept":"K3-2-u5-C25","difficulty":3,"kind":"mc","stem":"짐작한 뜻이 사전의 뜻과 달랐을 때 생각한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“짐작이 빗나간 덕분에 사전을 펴 본 보람이 있네.”","correct":true},{"t":"“역시 나는 낱말을 못 찾아.”","mis":"K3-2-u5-X26"},{"t":"“사전이 잘못 적었나 봐.”","mis":"K3-2-u5-X26"},{"t":"“짐작했으니 사전은 안 봐도 됐는데.”","mis":"K3-2-u5-X03"}],"explanation":["빗나가는 일은 흔해요.","그래서 확인하는 거예요.","고쳐 알면 돼요."],"asset":{"type":"speech","turns":[{"who":"내가 짐작한 뜻","text":"‘비탈’ — “울퉁불퉁한 길”"},{"who":"사전에서 찾은 뜻","text":"‘비탈’ — “땅이 기울어진 곳”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_challenge#4','kor',3,2,'u5','L10','g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C2',3,'mc','auto','모르는 낱말이 나올 때마다 멈추어 사전을 찾으면 어떤 점이 곤란할까요?',ARRAY['K3-2-u5-X02']::text[],false,'{"seq":4,"concept":"K3-2-u5-C2","difficulty":3,"kind":"mc","stem":"모르는 낱말이 나올 때마다 멈추어 사전을 찾으면 어떤 점이 곤란할까요?","options":[{"t":"읽기가 자꾸 끊겨 글 전체의 흐름을 놓치기 쉽다","correct":true},{"t":"사전에서 뜻을 찾을 수 없다","mis":"K3-2-u5-X02"},{"t":"낱말의 뜻을 정확히 알게 된다","mis":"K3-2-u5-X02"},{"t":"아는 낱말이 줄어든다","mis":"K3-2-u5-X02"}],"explanation":["짐작하며 끝까지 읽어요.","흐름을 먼저 잡아요.","확인은 뒤에 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_challenge#5','kor',3,2,'u5','L10','g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C3',3,'ox','auto','앞뒤로 짐작한 뜻이 그럴듯하면 사전에서 확인하지 않아도 돼요.',ARRAY['K3-2-u5-X03']::text[],false,'{"seq":5,"concept":"K3-2-u5-C3","difficulty":3,"kind":"ox","stem":"앞뒤로 짐작한 뜻이 그럴듯하면 사전에서 확인하지 않아도 돼요.","answer":"X","reason_options":[{"t":"짐작은 빗나갈 수 있어서 다 읽은 뒤에 사전에서 확인해야 하기 때문에","correct":true},{"t":"그럴듯한 짐작은 언제나 사전의 뜻과 같기 때문에","mis":"K3-2-u5-X03"}],"mis":"K3-2-u5-X03","explanation":["‘비탈’ 짐작도 그럴듯했어요.","그런데 사전 뜻과 달랐어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"내가 짐작한 뜻","text":"‘비탈’ — “울퉁불퉁한 길”"},{"who":"사전에서 찾은 뜻","text":"‘비탈’ — “땅이 기울어진 곳”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_challenge#6','kor',3,2,'u5','L10','g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C25',3,'error','auto','두 사전에서 찾은 ‘남짓’의 뜻풀이가 조금 달랐어요. 잘못 생각한 친구는 누구인가요?',ARRAY['K3-2-u5-X27']::text[],false,'{"seq":6,"concept":"K3-2-u5-C25","difficulty":3,"kind":"error","stem":"두 사전에서 찾은 ‘남짓’의 뜻풀이가 조금 달랐어요. 잘못 생각한 친구는 누구인가요?","options":[{"t":"친구 나 — 「글자가 다르니까 한쪽 사전은 틀렸어.」","correct":true,"mis_target":"K3-2-u5-X27"},{"t":"친구 가 — 「말은 달라도 뜻은 같아.」","mis":"K3-2-u5-X27"},{"t":"친구 다 — 「두 풀이를 견주니 뜻이 더 또렷해졌어.」","mis":"K3-2-u5-X27"}],"explanation":["사전마다 말은 조금씩 달라요.","뜻이 같으면 돼요.","친구 나가 잘못 생각했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_challenge#7','kor',3,2,'u5','L10','g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C24',3,'mc','auto','8번 줄에서 ‘여닫이’ 말고 “옆으로 미는 문”이라고 쓴 것으로 보아, ‘여닫이’의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":7,"concept":"K3-2-u5-C24","difficulty":3,"kind":"mc","stem":"8번 줄에서 ‘여닫이’ 말고 “옆으로 미는 문”이라고 쓴 것으로 보아, ‘여닫이’의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"밀거나 당겨서 여는 문","correct":true},{"t":"옆으로 미는 문","mis":"K3-2-u5-X25"},{"t":"여닫을 수 없는 문","mis":"K3-2-u5-X25"},{"t":"여러 개가 달린 문","mis":"K3-2-u5-X25"}],"explanation":["8번 줄에 두 가지 문이 나와요.","옆으로 미는 문은 따로 있어요.","밀거나 당겨서 여는 문이에요."],"asset":{"type":"passage","lines":["6 길도 그린다. 평평한 길과 비탈진 길을 다르게 표시한다.","7 그렇게 해 두면 유모차나 휠체어로 다니는 사람이 길을 고를 수 있다.","8 문도 나누어 적는다. 밀거나 당겨서 여는 여닫이 문인지,","   옆으로 미는 문인지 적어 둔다.","9 걸리는 시간도 적는다. “정문에서 도서관까지 오 분 남짓”처럼 적으면","   처음 온 사람이 셈하기 쉽다.","10 안내도는 그림만으로는 모자라다. 낱말이 있어야 자세해진다."],"title":"설명하는 글 「학교 안내도를 만드는 법」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_challenge#8','kor',3,2,'u5','L10','g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C26',4,'mc','auto','처음 읽을 때 걸렸던 다섯 낱말을 사전에서 확인한 뒤 같은 글을 다시 읽었어요. 무엇이 달라졌을까요?',ARRAY['K3-2-u5-X28','K3-2-u5-X17','K3-2-u5-X03']::text[],false,'{"seq":8,"concept":"K3-2-u5-C26","difficulty":4,"kind":"mc","stem":"처음 읽을 때 걸렸던 다섯 낱말을 사전에서 확인한 뒤 같은 글을 다시 읽었어요. 무엇이 달라졌을까요?","options":[{"t":"걸리는 곳이 줄고 글 전체가 또렷해졌다","correct":true},{"t":"글을 읽는 시간이 크게 줄었다","mis":"K3-2-u5-X28"},{"t":"글의 내용이 바뀌었다","mis":"K3-2-u5-X17"},{"t":"짐작한 뜻이 모두 맞았다는 것을 알았다","mis":"K3-2-u5-X03"}],"explanation":["낱말 다섯의 뜻을 알았어요.","두 번째 읽을 때 덜 걸려요.","글이 또렷해져요."],"asset":{"type":"passage","lines":["6 길도 그린다. 평평한 길과 비탈진 길을 다르게 표시한다.","7 그렇게 해 두면 유모차나 휠체어로 다니는 사람이 길을 고를 수 있다.","8 문도 나누어 적는다. 밀거나 당겨서 여는 여닫이 문인지,","   옆으로 미는 문인지 적어 둔다.","9 걸리는 시간도 적는다. “정문에서 도서관까지 오 분 남짓”처럼 적으면","   처음 온 사람이 셈하기 쉽다.","10 안내도는 그림만으로는 모자라다. 낱말이 있어야 자세해진다."],"title":"설명하는 글 「학교 안내도를 만드는 법」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_challenge#9','kor',3,2,'u5','L10','g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C25',4,'essay','teacher','‘비탈’의 뜻을 짐작했다가 사전에서 다른 뜻을 찾았을 때 할 일을 쓰고, 「내 짐작이 틀렸으니 이 글은 못 읽어.」라고 말한 친구에게 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u5-C25","difficulty":4,"kind":"essay","stem":"‘비탈’의 뜻을 짐작했다가 사전에서 다른 뜻을 찾았을 때 할 일을 쓰고, 「내 짐작이 틀렸으니 이 글은 못 읽어.」라고 말한 친구에게 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 사전의 뜻인 “땅이 기울어진 곳”으로 고쳐 알고, ‘비탈진 길’이 나온 줄을 다시 읽어 본다. 친구에게는 “짐작은 사전을 펴 보려고 하는 거야. 빗나가도 고쳐 알면 되니까 다시 읽으면 글이 더 또렷해져.”라고 말해 주겠다.","scoring_points":["사전의 뜻으로 고쳐 안다고 썼는가","그 줄을 다시 읽는다고 썼는가","짐작이 빗나가도 괜찮다는 말을 썼는가"]},"explanation":["고쳐 알고 다시 읽어요.","빗나가는 것은 흔해요.","그래서 확인하는 거예요."],"asset":{"type":"speech","turns":[{"who":"내가 짐작한 뜻","text":"‘비탈’ — “울퉁불퉁한 길”"},{"who":"사전에서 찾은 뜻","text":"‘비탈’ — “땅이 기울어진 곳”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L10_challenge#10','kor',3,2,'u5','L10','g3_2_kor_u5_L10_challenge','lesson_challenge','K3-2-u5-C2',4,'essay','teacher','모르는 낱말을 만났을 때 「바로 멈추어 찾기」와 「짐작만 하고 넘어가기」가 각각 왜 곤란한지 쓰고, 알맞은 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u5-C2","difficulty":4,"kind":"essay","stem":"모르는 낱말을 만났을 때 「바로 멈추어 찾기」와 「짐작만 하고 넘어가기」가 각각 왜 곤란한지 쓰고, 알맞은 방법을 쓰세요.","answer_guide":{"answer":"예: 바로 멈추어 찾으면 읽기가 자꾸 끊겨 글 전체의 흐름을 놓치기 쉽다. 짐작만 하고 넘어가면 짐작이 빗나가도 모른 채 틀린 뜻으로 알게 된다. 그래서 앞뒤로 짐작하며 끝까지 읽고, 다 읽은 뒤에 사전에서 확인하는 것이 알맞다.","scoring_points":["멈추어 찾기가 곤란한 까닭을 썼는가","짐작만 하기가 곤란한 까닭을 썼는가","짐작한 뒤 확인하는 방법을 썼는가"]},"explanation":["멈추면 흐름이 끊겨요.","짐작만 하면 틀린 채로 알아요.","짐작하고 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_basic#1','kor',3,2,'u5','L12','g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C27',1,'mc','auto','「단서 세 장」의 단서로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u5-X29']::text[],false,'{"seq":1,"concept":"K3-2-u5-C27","difficulty":1,"kind":"mc","stem":"「단서 세 장」의 단서로 알맞지 않은 것은 무엇인가요?","options":[{"t":"알아맞힐 낱말을 그대로 적기","correct":true},{"t":"낱말의 종류","mis":"K3-2-u5-X29"},{"t":"사전에서 찾은 뜻","mis":"K3-2-u5-X29"},{"t":"낱말을 괄호로 비운 쓰인 문장","mis":"K3-2-u5-X29"}],"explanation":["단서는 답을 가리켜요.","그런데 답 자체는 아니에요.","낱말을 그대로 적으면 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_basic#2','kor',3,2,'u5','L12','g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C27',1,'sa','auto','세 장의 단서가 가리키는 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u5-C27","difficulty":1,"kind":"sa","stem":"세 장의 단서가 가리키는 낱말을 쓰세요.","answer":["바구니"],"explanation":["이름을 나타내는 낱말이에요.","물건을 담는 그릇이에요.","‘바구니’예요."],"asset":{"type":"passage","lines":["첫째 장 — 이름을 나타내는 낱말","둘째 장 — 물건을 담는 그릇","셋째 장 — 빨래를 (　)에 담았다."],"title":"「단서 세 장」 — 짝이 알아맞힐 낱말은?"},"mis":"K3-2-u5-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_basic#3','kor',3,2,'u5','L12','g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C30',1,'mc','auto','‘한여름’은 어떻게 소리 나나요?',ARRAY['K3-2-u5-X32']::text[],false,'{"seq":3,"concept":"K3-2-u5-C30","difficulty":1,"kind":"mc","stem":"‘한여름’은 어떻게 소리 나나요?","options":[{"t":"[한녀름]","correct":true},{"t":"[하녀름]","mis":"K3-2-u5-X32"},{"t":"[한여름]","mis":"K3-2-u5-X32"},{"t":"[한려름]","mis":"K3-2-u5-X32"}],"explanation":["앞 글자 ‘한’에 받침이 있어요.","뒤 글자는 ‘여’로 시작해요.","‘ㄴ’ 소리가 더해져요."],"asset":{"type":"passage","lines":["한여름 → [한녀름]","논일 → [논닐]","눈인사 → [눈닌사]"],"title":"소리가 하나 더해질 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_basic#4','kor',3,2,'u5','L12','g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C31',1,'match','auto','우리말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u5-C31","difficulty":1,"kind":"match","stem":"우리말과 뜻을 알맞게 이으세요.","pairs":[{"l":"아우르다","r":"여럿을 모아 하나로 만들다"},{"l":"북돋우다","r":"기운을 더 나게 해 주다"},{"l":"여미다","r":"옷깃을 바로 해 단정히 하다"}],"mis":"K3-2-u5-X34","explanation":["소리 내어 읽어요.","어울리는 장면을 떠올려요.","셋을 하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_basic#5','kor',3,2,'u5','L12','g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C28',2,'mc','auto','「내 낱말 공책」에 모은 낱말을 어떤 차례로 적으면 좋을까요?',ARRAY['K3-2-u5-X30']::text[],false,'{"seq":5,"concept":"K3-2-u5-C28","difficulty":2,"kind":"mc","stem":"「내 낱말 공책」에 모은 낱말을 어떤 차례로 적으면 좋을까요?","options":[{"t":"국어사전에 싣는 차례","correct":true},{"t":"낱말이 긴 차례","mis":"K3-2-u5-X30"},{"t":"내가 좋아하는 차례","mis":"K3-2-u5-X30"},{"t":"적은 날의 날씨 차례","mis":"K3-2-u5-X30"}],"explanation":["공책도 나중에 다시 찾아봐요.","사전처럼 차례를 맞춰요.","그러면 찾기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_basic#6','kor',3,2,'u5','L12','g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C28',2,'mc','auto','낱말 공책에 적을 것으로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u5-X30']::text[],false,'{"seq":6,"concept":"K3-2-u5-C28","difficulty":2,"kind":"mc","stem":"낱말 공책에 적을 것으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"그 낱말을 적은 날의 날씨","correct":true},{"t":"낱말의 기본형","mis":"K3-2-u5-X30"},{"t":"사전에서 찾은 뜻","mis":"K3-2-u5-X30"},{"t":"그 낱말을 넣어 내가 쓴 문장","mis":"K3-2-u5-X30"}],"explanation":["나중에 펴 볼 때를 생각해요.","날씨는 도움이 안 돼요.","나머지 넷이 모이면 사전이 돼요."],"asset":{"type":"passage","lines":["낱말 (모양이 바뀌는 낱말은 기본형으로)","낱말의 종류","사전에서 찾은 뜻","그 낱말을 넣어 내가 쓴 문장"],"title":"「내 낱말 공책」 — 낱말 하나에 적을 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_basic#7','kor',3,2,'u5','L12','g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C29',2,'ox','auto','「단서 세 장」에서 세 장을 다 열어도 못 맞히면 놀이에 실패한 거예요.',ARRAY['K3-2-u5-X31']::text[],false,'{"seq":7,"concept":"K3-2-u5-C29","difficulty":2,"kind":"ox","stem":"「단서 세 장」에서 세 장을 다 열어도 못 맞히면 놀이에 실패한 거예요.","answer":"X","reason_options":[{"t":"이 놀이의 목표는 단서를 보며 낱말을 헤아려 보는 것이기 때문에","correct":true},{"t":"놀이는 언제나 맞혀서 이겨야 하기 때문에","mis":"K3-2-u5-X31"}],"mis":"K3-2-u5-X31","explanation":["못 맞힐 수도 있어요.","못 맞힌 낱말은 사전에서 함께 찾아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_basic#8','kor',3,2,'u5','L12','g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C30',2,'mc','auto','‘ㄴ’ 소리가 더해져 소리 나는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X32']::text[],false,'{"seq":8,"concept":"K3-2-u5-C30","difficulty":2,"kind":"mc","stem":"‘ㄴ’ 소리가 더해져 소리 나는 낱말은 무엇인가요?","options":[{"t":"눈인사","correct":true},{"t":"나이","mis":"K3-2-u5-X32"},{"t":"오이","mis":"K3-2-u5-X32"},{"t":"바다","mis":"K3-2-u5-X32"}],"explanation":["앞 글자에 받침이 있어야 해요.","나이·오이는 받침이 없어요.","‘눈인사’ [눈닌사]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_basic#9','kor',3,2,'u5','L12','g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C32',2,'mc','auto','‘ㅘ’는 어떤 두 모음자가 붙은 것인가요?',ARRAY['K3-2-u5-X35']::text[],false,'{"seq":9,"concept":"K3-2-u5-C32","difficulty":2,"kind":"mc","stem":"‘ㅘ’는 어떤 두 모음자가 붙은 것인가요?","options":[{"t":"ㅗ와 ㅏ","correct":true},{"t":"ㅗ와 ㅣ","mis":"K3-2-u5-X35"},{"t":"ㅗ와 ㅐ","mis":"K3-2-u5-X35"},{"t":"ㅜ와 ㅓ","mis":"K3-2-u5-X35"}],"explanation":["‘관찰’의 ‘관’을 봐요.","ㅗ 옆에 ㅏ가 붙었어요.","ㅗ와 ㅏ예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_basic#10','kor',3,2,'u5','L12','g3_2_kor_u5_L12_basic','lesson_basic','K3-2-u5-C30',3,'error','auto','‘논일’을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X33','K3-2-u5-X32']::text[],false,'{"seq":10,"concept":"K3-2-u5-C30","difficulty":3,"kind":"error","stem":"‘논일’을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「소리 나는 대로 ‘논닐’이라고 써야 해.」","correct":true,"mis_target":"K3-2-u5-X33"},{"t":"친구 가 — 「[논닐]로 소리 나.」","mis":"K3-2-u5-X32"},{"t":"친구 나 — 「앞 글자 ‘논’에 받침이 있어서 그래.」","mis":"K3-2-u5-X32"}],"explanation":["소리는 [논닐]이에요.","쓸 때는 그대로예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_challenge#1','kor',3,2,'u5','L12','g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C27',2,'mc','auto','‘바구니’로 단서를 만들 때 셋째 장(쓰인 문장)으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X29']::text[],false,'{"seq":1,"concept":"K3-2-u5-C27","difficulty":2,"kind":"mc","stem":"‘바구니’로 단서를 만들 때 셋째 장(쓰인 문장)으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“빨래를 (　)에 담았다.”","correct":true},{"t":"“빨래를 바구니에 담았다.”","mis":"K3-2-u5-X29"},{"t":"“바구니는 바구니이다.”","mis":"K3-2-u5-X29"},{"t":"“(　)는 하늘을 난다.”","mis":"K3-2-u5-X29"}],"explanation":["쓰인 문장에서 낱말 자리는 비워요.","바구니가 들어갈 만한 문장이어야 해요.","빨래를 담는 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_challenge#2','kor',3,2,'u5','L12','g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C31',2,'sa','auto','‘옷깃을 바로 해 단정히 하다’라는 뜻의 우리말을 ‘-다’로 끝나게 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u5-C31","difficulty":2,"kind":"sa","stem":"‘옷깃을 바로 해 단정히 하다’라는 뜻의 우리말을 ‘-다’로 끝나게 쓰세요.","answer":["여미다"],"explanation":["기초 다지기의 우리말 셋을 떠올려요.","옷깃을 바로 하는 움직임이에요.","‘여미다’예요."],"mis":"K3-2-u5-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_challenge#3','kor',3,2,'u5','L12','g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C28',3,'mc','auto','낱말 공책에 ‘찌그러졌다’를 모았어요. 공책에 적을 모양으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X23','K3-2-u5-X11']::text[],false,'{"seq":3,"concept":"K3-2-u5-C28","difficulty":3,"kind":"mc","stem":"낱말 공책에 ‘찌그러졌다’를 모았어요. 공책에 적을 모양으로 알맞은 것은 무엇인가요?","options":[{"t":"찌그러지다","correct":true},{"t":"찌그러졌다","mis":"K3-2-u5-X23"},{"t":"찌그러졌고","mis":"K3-2-u5-X23"},{"t":"찌그러","mis":"K3-2-u5-X11"}],"explanation":["공책도 사전처럼 만들어요.","모양이 바뀌는 낱말은 기본형으로 적어요.","‘찌그러지다’예요."],"asset":{"type":"passage","lines":["낱말 (모양이 바뀌는 낱말은 기본형으로)","낱말의 종류","사전에서 찾은 뜻","그 낱말을 넣어 내가 쓴 문장"],"title":"「내 낱말 공책」 — 낱말 하나에 적을 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_challenge#4','kor',3,2,'u5','L12','g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C28',3,'mc','auto','낱말 공책에 모은 ‘비탈 · 남짓 · 어귀’를 사전에 싣는 차례대로 적은 것은 무엇인가요?',ARRAY['K3-2-u5-X30','K3-2-u5-X19']::text[],false,'{"seq":4,"concept":"K3-2-u5-C28","difficulty":3,"kind":"mc","stem":"낱말 공책에 모은 ‘비탈 · 남짓 · 어귀’를 사전에 싣는 차례대로 적은 것은 무엇인가요?","options":[{"t":"남짓 → 비탈 → 어귀","correct":true},{"t":"어귀 → 남짓 → 비탈","mis":"K3-2-u5-X30"},{"t":"비탈 → 어귀 → 남짓","mis":"K3-2-u5-X30"},{"t":"남짓 → 어귀 → 비탈","mis":"K3-2-u5-X19"}],"explanation":["첫 자음자는 ㄴ·ㅂ·ㅇ이에요.","ㄴ → ㅂ → ㅇ 차례예요.","남짓 → 비탈 → 어귀예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_challenge#5','kor',3,2,'u5','L12','g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C29',3,'error','auto','「단서 세 장」 놀이를 하며 말했어요. 놀이의 목표를 잘못 안 친구는 누구인가요?',ARRAY['K3-2-u5-X31']::text[],false,'{"seq":5,"concept":"K3-2-u5-C29","difficulty":3,"kind":"error","stem":"「단서 세 장」 놀이를 하며 말했어요. 놀이의 목표를 잘못 안 친구는 누구인가요?","options":[{"t":"친구 나 — 「무조건 빨리 맞혀서 이기는 게 제일이야.」","correct":true,"mis_target":"K3-2-u5-X31"},{"t":"친구 가 — 「단서를 하나씩 보며 낱말을 헤아려 보자.」","mis":"K3-2-u5-X31"},{"t":"친구 다 — 「못 맞힌 낱말은 사전에서 같이 찾아보자.」","mis":"K3-2-u5-X31"}],"explanation":["이기는 것이 목표가 아니에요.","헤아려 보는 것이 목표예요.","친구 나가 잘못 알았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_challenge#6','kor',3,2,'u5','L12','g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C30',3,'ox','auto','‘오이’는 앞 글자 ‘오’ 뒤에 ‘이’가 오니까 [오니]로 소리 나요.',ARRAY['K3-2-u5-X32']::text[],false,'{"seq":6,"concept":"K3-2-u5-C30","difficulty":3,"kind":"ox","stem":"‘오이’는 앞 글자 ‘오’ 뒤에 ‘이’가 오니까 [오니]로 소리 나요.","answer":"X","reason_options":[{"t":"앞 글자 ‘오’에 받침이 없어 ‘ㄴ’ 소리가 더해지지 않기 때문에","correct":true},{"t":"뒤 글자가 ‘이’로 시작하면 언제나 ‘ㄴ’ 소리가 더해지기 때문에","mis":"K3-2-u5-X32"}],"mis":"K3-2-u5-X32","explanation":["조건은 둘이에요.","앞 글자에 받침이 있어야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_challenge#7','kor',3,2,'u5','L12','g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C32',3,'mc','auto','‘괜찮다’의 ‘괜’에 든 모음자는 무엇인가요?',ARRAY['K3-2-u5-X35']::text[],false,'{"seq":7,"concept":"K3-2-u5-C32","difficulty":3,"kind":"mc","stem":"‘괜찮다’의 ‘괜’에 든 모음자는 무엇인가요?","options":[{"t":"ㅙ","correct":true},{"t":"ㅘ","mis":"K3-2-u5-X35"},{"t":"ㅚ","mis":"K3-2-u5-X35"},{"t":"ㅝ","mis":"K3-2-u5-X35"}],"explanation":["ㅗ 옆에 ㅐ가 붙었어요.","그래서 ㅙ예요.","‘관’의 ㅘ와 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_challenge#8','kor',3,2,'u5','L12','g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C27',4,'mc','auto','‘묵직하다’로 단서 세 장을 만들었어요. 가장 알맞게 만든 것은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X29']::text[],false,'{"seq":8,"concept":"K3-2-u5-C27","difficulty":4,"kind":"mc","stem":"‘묵직하다’로 단서 세 장을 만들었어요. 가장 알맞게 만든 것은 무엇인가요?","options":[{"t":"성질이나 상태를 나타내는 낱말 / 보기보다 꽤 무겁다 / 물을 채우니 물통이 (　).","correct":true},{"t":"움직임을 나타내는 낱말 / 보기보다 꽤 무겁다 / 물을 채우니 물통이 (　).","mis":"K3-2-u5-X04"},{"t":"성질이나 상태를 나타내는 낱말 / 묵직하다 / 물을 채우니 물통이 (　).","mis":"K3-2-u5-X29"},{"t":"성질이나 상태를 나타내는 낱말 / 보기보다 꽤 무겁다 / 물을 채우니 물통이 묵직했다.","mis":"K3-2-u5-X29"}],"explanation":["종류는 성질이나 상태예요.","둘째 장엔 뜻을 적어요.","셋째 장은 낱말 자리를 비워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_challenge#9','kor',3,2,'u5','L12','g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C28',4,'essay','teacher','「내 낱말 공책」에 ‘여닫으니’를 모으려고 해요. 낱말 하나에 적을 네 가지를 이 낱말로 채워 쓰고, 공책에 어떤 차례로 늘어놓을지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u5-C28","difficulty":4,"kind":"essay","stem":"「내 낱말 공책」에 ‘여닫으니’를 모으려고 해요. 낱말 하나에 적을 네 가지를 이 낱말로 채워 쓰고, 공책에 어떤 차례로 늘어놓을지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 낱말 — 여닫다(기본형) / 종류 — 움직임을 나타내는 낱말 / 뜻 — 문을 열었다 닫았다 하다 / 내가 쓴 문장 — 바람이 불어서 창문을 조심히 여닫았다. 공책은 국어사전에 싣는 차례로 늘어놓는다. 그래야 나중에 찾아볼 때 사전처럼 금방 찾을 수 있기 때문이다.","scoring_points":["기본형 ‘여닫다’로 적었는가","종류·뜻·문장을 모두 채웠는가","사전 차례로 늘어놓는 까닭을 썼는가"]},"explanation":["기본형으로 적어요.","종류·뜻·문장도 적어요.","사전 차례로 늘어놓아요."],"asset":{"type":"passage","lines":["낱말 (모양이 바뀌는 낱말은 기본형으로)","낱말의 종류","사전에서 찾은 뜻","그 낱말을 넣어 내가 쓴 문장"],"title":"「내 낱말 공책」 — 낱말 하나에 적을 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_L12_challenge#10','kor',3,2,'u5','L12','g3_2_kor_u5_L12_challenge','lesson_challenge','K3-2-u5-C30',4,'essay','teacher','‘ㄴ’ 소리가 더해지는 두 가지 조건을 쓰고, ‘눈인사’와 ‘나이’를 예로 들어 설명한 뒤, 쓸 때는 어떻게 쓰는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u5-C30","difficulty":4,"kind":"essay","stem":"‘ㄴ’ 소리가 더해지는 두 가지 조건을 쓰고, ‘눈인사’와 ‘나이’를 예로 들어 설명한 뒤, 쓸 때는 어떻게 쓰는지 쓰세요.","answer_guide":{"answer":"예: 앞 글자에 받침이 있고, 뒤 글자가 이·야·여·요·유로 시작해야 한다. ‘눈인사’는 앞 글자 ‘눈’에 받침이 있고 뒤 글자가 ‘인’으로 시작해 [눈닌사]로 소리 난다. ‘나이’는 앞 글자 ‘나’에 받침이 없어 ‘ㄴ’ 소리가 더해지지 않는다. 소리가 달라져도 쓸 때는 ‘눈인사’로 그대로 쓴다.","scoring_points":["두 가지 조건을 썼는가","‘눈인사’와 ‘나이’를 견주어 설명했는가","쓸 때는 그대로 쓴다고 썼는가"]},"explanation":["받침이 있는지 먼저 봐요.","뒤 글자도 봐요.","쓸 때는 그대로예요."],"asset":{"type":"passage","lines":["한여름 → [한녀름]","논일 → [논닐]","눈인사 → [눈닌사]"],"title":"소리가 하나 더해질 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#1','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C2',1,'mc','auto','글을 읽다가 처음 보는 낱말이 나왔을 때 알맞은 방법은 무엇인가요?',ARRAY['K3-2-u5-X01','K3-2-u5-X02','K3-2-u5-X03']::text[],false,'{"seq":1,"concept":"K3-2-u5-C2","difficulty":1,"kind":"mc","stem":"글을 읽다가 처음 보는 낱말이 나왔을 때 알맞은 방법은 무엇인가요?","options":[{"t":"앞뒤를 살펴 짐작하며 읽고, 그 뒤에 국어사전에서 확인한다","correct":true},{"t":"처음 보는 낱말은 빼고 읽는다","mis":"K3-2-u5-X01"},{"t":"그 낱말이 나온 곳에서 읽기를 그만둔다","mis":"K3-2-u5-X02"},{"t":"짐작한 뜻을 그대로 믿는다","mis":"K3-2-u5-X03"}],"explanation":["건너뛰면 뜻을 놓쳐요.","멈추면 흐름을 놓쳐요.","짐작하고 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#2','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C3',1,'mc','auto','「체육 창고 정리」에서 고른 낱말 가운데 이름을 나타내는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X04']::text[],false,'{"seq":2,"concept":"K3-2-u5-C3","difficulty":1,"kind":"mc","stem":"「체육 창고 정리」에서 고른 낱말 가운데 이름을 나타내는 낱말은 무엇인가요?","options":[{"t":"호루라기","correct":true},{"t":"감다","mis":"K3-2-u5-X04"},{"t":"축축하다","mis":"K3-2-u5-X04"},{"t":"쌓다","mis":"K3-2-u5-X04"}],"explanation":["“이것이 ○○이다”에 넣어요.","“이것이 호루라기이다”가 돼요.","이름을 나타내요."],"asset":{"type":"passage","lines":["선반 · 쌓다 · 축축하다 · 호루라기 · 감다","가지런하다 · 수건 · 넣다 · 높다"],"title":"「체육 창고 정리」에서 고른 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#3','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C6',1,'mc','auto','낱말의 종류를 가릴 때 가장 먼저 해 볼 일은 무엇인가요?',ARRAY['K3-2-u5-X06','K3-2-u5-X07']::text[],false,'{"seq":3,"concept":"K3-2-u5-C6","difficulty":1,"kind":"mc","stem":"낱말의 종류를 가릴 때 가장 먼저 해 볼 일은 무엇인가요?","options":[{"t":"세 가지 틀에 넣어 소리 내어 읽어 본다","correct":true},{"t":"낱말의 글자 수를 센다","mis":"K3-2-u5-X06"},{"t":"소리가 닮은 낱말과 같은 종류로 정한다","mis":"K3-2-u5-X06"},{"t":"종류의 이름을 외운다","mis":"K3-2-u5-X07"}],"explanation":["낱말만 보고 정하지 않아요.","틀에 넣어 읽어요.","어울리는 쪽을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#4','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C12',1,'mc','auto','“상자를 차곡차곡 쌓으니”에서 ‘쌓으니’의 기본형은 무엇인가요?',ARRAY['K3-2-u5-X11']::text[],false,'{"seq":4,"concept":"K3-2-u5-C12","difficulty":1,"kind":"mc","stem":"“상자를 차곡차곡 쌓으니”에서 ‘쌓으니’의 기본형은 무엇인가요?","options":[{"t":"쌓다","correct":true},{"t":"쌓으다","mis":"K3-2-u5-X11"},{"t":"쌓으니다","mis":"K3-2-u5-X11"},{"t":"쌓는다","mis":"K3-2-u5-X11"}],"explanation":["바뀌지 않는 부분은 ‘쌓’이에요.","‘-다’를 붙여요.","‘쌓다’예요."],"asset":{"type":"passage","lines":["체육 시간이 끝나고 짝과 체육 창고를 정리했다.","공은 바구니에 넣고, 줄넘기는 둥글게 감아 걸었다.","젖은 수건은 아직 축축해서 따로 널었다.","선반이 높아서 짝이 의자를 붙잡아 주었다.","호루라기는 선생님 책상 위에 두었다.","상자를 차곡차곡 쌓으니 창고 안이 한결 가지런했다."],"title":"글 「체육 창고 정리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#5','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C14',1,'ox','auto','낱말을 나누기 전에는 무엇을 보고 나눌지 기준을 먼저 정해요.',ARRAY['K3-2-u5-X14']::text[],false,'{"seq":5,"concept":"K3-2-u5-C14","difficulty":1,"kind":"ox","stem":"낱말을 나누기 전에는 무엇을 보고 나눌지 기준을 먼저 정해요.","answer":"O","reason_options":[{"t":"기준에 따라 나뉘는 모양이 달라지기 때문에","correct":true},{"t":"낱말마다 들어갈 칸이 정해져 있기 때문에","mis":"K3-2-u5-X14"}],"mis":"K3-2-u5-X14","explanation":["같은 낱말도 여러 기준으로 나뉘어요.","기준부터 정해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#6','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C17',1,'match','auto','‘물’의 짜임을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u5-C17","difficulty":1,"kind":"match","stem":"‘물’의 짜임을 알맞게 이으세요.","pairs":[{"l":"첫 자음자","r":"ㅁ"},{"l":"모음자","r":"ㅜ"},{"l":"받침","r":"ㄹ"}],"mis":"K3-2-u5-X18","explanation":["천천히 소리 내어 읽어요.","셋으로 나뉘어 들려요.","ㅁ · ㅜ · ㄹ이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#7','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C23',1,'mc','auto','국어사전에서 낱말 옆에 함께 적혀 있는 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X24']::text[],false,'{"seq":7,"concept":"K3-2-u5-C23","difficulty":1,"kind":"mc","stem":"국어사전에서 낱말 옆에 함께 적혀 있는 것으로 알맞은 것은 무엇인가요?","options":[{"t":"그 낱말이 쓰인 문장","correct":true},{"t":"그 낱말을 처음 쓴 사람의 이름","mis":"K3-2-u5-X24"},{"t":"그 낱말의 그림 그리는 법","mis":"K3-2-u5-X24"},{"t":"그 낱말을 외우는 노래","mis":"K3-2-u5-X24"}],"explanation":["뜻만 있는 것이 아니에요.","읽는 법도 있어요.","쓰인 문장도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#8','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C30',1,'mc','auto','‘논일’은 어떻게 소리 나나요?',ARRAY['K3-2-u5-X32']::text[],false,'{"seq":8,"concept":"K3-2-u5-C30","difficulty":1,"kind":"mc","stem":"‘논일’은 어떻게 소리 나나요?","options":[{"t":"[논닐]","correct":true},{"t":"[노닐]","mis":"K3-2-u5-X32"},{"t":"[논일]","mis":"K3-2-u5-X32"},{"t":"[놀릴]","mis":"K3-2-u5-X32"}],"explanation":["앞 글자 ‘논’에 받침이 있어요.","뒤 글자가 ‘일’이에요.","‘ㄴ’ 소리가 더해져요."],"asset":{"type":"passage","lines":["한여름 → [한녀름]","논일 → [논닐]","눈인사 → [눈닌사]"],"title":"소리가 하나 더해질 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#9','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C15',2,'mc','auto','「체육 창고 정리」의 아홉 낱말을 ‘문장에 따라 모양이 바뀌는가’로 나누었을 때, 모양이 바뀌지 않는 낱말끼리 모은 것은 무엇인가요?',ARRAY['K3-2-u5-X09','K3-2-u5-X14']::text[],false,'{"seq":9,"concept":"K3-2-u5-C15","difficulty":2,"kind":"mc","stem":"「체육 창고 정리」의 아홉 낱말을 ‘문장에 따라 모양이 바뀌는가’로 나누었을 때, 모양이 바뀌지 않는 낱말끼리 모은 것은 무엇인가요?","options":[{"t":"선반 · 호루라기 · 수건","correct":true},{"t":"쌓다 · 감다 · 넣다","mis":"K3-2-u5-X09"},{"t":"높다 · 축축하다 · 가지런하다","mis":"K3-2-u5-X09"},{"t":"선반 · 쌓다 · 높다","mis":"K3-2-u5-X14"}],"explanation":["‘-고 · -으니’를 붙여 봐요.","이름을 나타내는 셋은 안 붙어요.","선반·호루라기·수건이에요."],"asset":{"type":"passage","lines":["선반 · 쌓다 · 축축하다 · 호루라기 · 감다","가지런하다 · 수건 · 넣다 · 높다"],"title":"「체육 창고 정리」에서 고른 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#10','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C13',2,'mc','auto','“짝이 의자를 붙잡아 주었다.”의 ‘붙잡아’에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u5-X12','K3-2-u5-X13']::text[],false,'{"seq":10,"concept":"K3-2-u5-C13","difficulty":2,"kind":"mc","stem":"“짝이 의자를 붙잡아 주었다.”의 ‘붙잡아’에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"‘붙잡다’가 문장에 맞게 바뀐 모양으로, 바른 말이다","correct":true},{"t":"사전에 없으니 틀린 말이다","mis":"K3-2-u5-X12"},{"t":"사전에 이 모양 그대로 실려 있다","mis":"K3-2-u5-X13"},{"t":"‘붙잡다’로 고쳐야 바른 문장이다","mis":"K3-2-u5-X12"}],"explanation":["사전엔 ‘붙잡다’가 실려요.","‘붙잡아’는 문장에서 바뀐 모양이에요.","바른 말이에요."],"asset":{"type":"passage","lines":["체육 시간이 끝나고 짝과 체육 창고를 정리했다.","공은 바구니에 넣고, 줄넘기는 둥글게 감아 걸었다.","젖은 수건은 아직 축축해서 따로 널었다.","선반이 높아서 짝이 의자를 붙잡아 주었다.","호루라기는 선생님 책상 위에 두었다.","상자를 차곡차곡 쌓으니 창고 안이 한결 가지런했다."],"title":"글 「체육 창고 정리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#11','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C20',2,'mc','auto','‘무’와 ‘물’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X21','K3-2-u5-X22']::text[],false,'{"seq":11,"concept":"K3-2-u5-C20","difficulty":2,"kind":"mc","stem":"‘무’와 ‘물’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?","options":[{"t":"무","correct":true},{"t":"물","mis":"K3-2-u5-X21"},{"t":"둘이 같은 쪽에 함께 실린다","mis":"K3-2-u5-X21"},{"t":"글자 수가 적은 낱말","mis":"K3-2-u5-X22"}],"explanation":["첫 글자 ‘무’와 ‘물’을 견주어요.","‘무’는 받침이 없어요.","받침이 없는 쪽이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#12','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C24',2,'mc','auto','「게시판에 작품 붙이는 법」 3번 줄의 ‘귀퉁이’를 앞뒤로 짐작한 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":12,"concept":"K3-2-u5-C24","difficulty":2,"kind":"mc","stem":"「게시판에 작품 붙이는 법」 3번 줄의 ‘귀퉁이’를 앞뒤로 짐작한 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"물건의 모서리 쪽 끝 부분","correct":true},{"t":"물건의 한가운데","mis":"K3-2-u5-X25"},{"t":"작품을 붙이는 풀","mis":"K3-2-u5-X25"},{"t":"게시판을 거는 못","mis":"K3-2-u5-X25"}],"explanation":["“위쪽 귀퉁이부터 차례로”를 읽어요.","차례가 시작되는 끝자리예요.","모서리 쪽 끝 부분이에요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#13','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C25',2,'mc','auto','‘귀퉁이’를 “구석에 쌓인 먼지”로 짐작했는데 사전의 뜻이 달랐어요. 알맞게 한 것은 무엇인가요?',ARRAY['K3-2-u5-X26','K3-2-u5-X03']::text[],false,'{"seq":13,"concept":"K3-2-u5-C25","difficulty":2,"kind":"mc","stem":"‘귀퉁이’를 “구석에 쌓인 먼지”로 짐작했는데 사전의 뜻이 달랐어요. 알맞게 한 것은 무엇인가요?","options":[{"t":"사전의 뜻으로 고쳐 알고 3번 줄을 다시 읽었다","correct":true},{"t":"짐작이 틀렸으니 이 글은 그만 읽었다","mis":"K3-2-u5-X26"},{"t":"짐작이 맞고 사전이 틀렸다고 여겼다","mis":"K3-2-u5-X26"},{"t":"짐작한 뜻대로 그냥 알고 넘어갔다","mis":"K3-2-u5-X03"}],"explanation":["짐작은 빗나갈 수 있어요.","사전의 뜻으로 고쳐 알아요.","그 줄을 다시 읽어요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#14','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C26',2,'mc','auto','「게시판에 작품 붙이는 법」에서 다 붙인 뒤 한 걸음 물러서는 까닭은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":14,"concept":"K3-2-u5-C26","difficulty":2,"kind":"mc","stem":"「게시판에 작품 붙이는 법」에서 다 붙인 뒤 한 걸음 물러서는 까닭은 무엇인가요?","options":[{"t":"비뚤어진 작품이 없는지 살피려고","correct":true},{"t":"작품을 더 붙이려고","mis":"K3-2-u5-X17"},{"t":"테두리를 떼려고","mis":"K3-2-u5-X17"},{"t":"게시판 크기를 재려고","mis":"K3-2-u5-X17"}],"explanation":["5번 줄을 다시 읽어요.","물러서서 살펴요.","비뚤어진 작품을 찾아요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#15','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C27',2,'sa','auto','‘선반’으로 「단서 세 장」을 만들어요. 첫째 장에 적을 낱말의 종류를 “○○을 나타내는 낱말”의 꼴로 쓸 때, ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"K3-2-u5-C27","difficulty":2,"kind":"sa","stem":"‘선반’으로 「단서 세 장」을 만들어요. 첫째 장에 적을 낱말의 종류를 “○○을 나타내는 낱말”의 꼴로 쓸 때, ○○에 알맞은 말을 쓰세요.","answer":["이름"],"explanation":["“이것이 선반이다”가 돼요.","이름을 나타내요.","‘이름’이에요."],"mis":"K3-2-u5-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#16','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C28',2,'mc','auto','낱말 공책에 ‘귀퉁이 · 테두리 · 비탈’을 사전에 싣는 차례대로 적은 것은 무엇인가요?',ARRAY['K3-2-u5-X30','K3-2-u5-X19']::text[],false,'{"seq":16,"concept":"K3-2-u5-C28","difficulty":2,"kind":"mc","stem":"낱말 공책에 ‘귀퉁이 · 테두리 · 비탈’을 사전에 싣는 차례대로 적은 것은 무엇인가요?","options":[{"t":"귀퉁이 → 비탈 → 테두리","correct":true},{"t":"테두리 → 귀퉁이 → 비탈","mis":"K3-2-u5-X30"},{"t":"비탈 → 귀퉁이 → 테두리","mis":"K3-2-u5-X19"},{"t":"귀퉁이 → 테두리 → 비탈","mis":"K3-2-u5-X19"}],"explanation":["첫 자음자는 ㄱ·ㅌ·ㅂ이에요.","ㄱ → ㅂ → ㅌ 차례예요.","귀퉁이 → 비탈 → 테두리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#17','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C14',3,'mc','auto','단원을 시작할 때와 마칠 때 같은 물음 「낱말을 여럿 놓고 나눌 때 가장 먼저 할 일은?」을 받았어요. 마칠 때 덧붙일 수 있는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X14','K3-2-u5-X15','K3-2-u5-X16']::text[],false,'{"seq":17,"concept":"K3-2-u5-C14","difficulty":3,"kind":"mc","stem":"단원을 시작할 때와 마칠 때 같은 물음 「낱말을 여럿 놓고 나눌 때 가장 먼저 할 일은?」을 받았어요. 마칠 때 덧붙일 수 있는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"같은 낱말도 기준이 바뀌면 나뉘는 결과가 달라지기 때문에","correct":true},{"t":"낱말마다 정해진 칸을 다 외웠기 때문에","mis":"K3-2-u5-X14"},{"t":"아무렇게나 나누어도 결과는 같기 때문에","mis":"K3-2-u5-X15"},{"t":"한 번 나눈 결과는 바뀌지 않기 때문에","mis":"K3-2-u5-X16"}],"explanation":["같은 아홉 낱말을 두 번 나누었어요.","결과가 달랐어요.","그래서 기준이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#18','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C13',3,'mc','auto','「사전에는 ‘접다’만 있으니 ‘접어서’는 바른 말이 아니야.」라는 말이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K3-2-u5-X13','K3-2-u5-X12','K3-2-u5-X10']::text[],false,'{"seq":18,"concept":"K3-2-u5-C13","difficulty":3,"kind":"mc","stem":"「사전에는 ‘접다’만 있으니 ‘접어서’는 바른 말이 아니야.」라는 말이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"사전에는 대표 모양만 실을 뿐, 문장에 맞게 바뀐 모양도 바른 말이기 때문에","correct":true},{"t":"사전에 ‘접어서’도 실려 있기 때문에","mis":"K3-2-u5-X13"},{"t":"‘접다’가 틀린 말이기 때문에","mis":"K3-2-u5-X12"},{"t":"사전을 만든 사람이 빠뜨렸기 때문에","mis":"K3-2-u5-X10"}],"explanation":["사전엔 대표 모양 ‘접다’가 실려요.","‘접어서’는 바뀐 모양이에요.","바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#19','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C23',3,'mc','auto','국어사전에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u5-X24','K3-2-u5-X13','K3-2-u5-X19']::text[],false,'{"seq":19,"concept":"K3-2-u5-C23","difficulty":3,"kind":"mc","stem":"국어사전에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"뜻과 함께 읽는 법과 쓰인 문장도 알 수 있다","correct":true},{"t":"뜻만 적혀 있다","mis":"K3-2-u5-X24"},{"t":"모양이 바뀐 낱말까지 모두 실려 있다","mis":"K3-2-u5-X13"},{"t":"낱말이 아무 차례로나 실려 있다","mis":"K3-2-u5-X19"}],"explanation":["뜻만 있는 것이 아니에요.","바뀐 모양이 다 실린 것도 아니에요.","읽는 법·쓰인 문장이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#20','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C2',3,'error','auto','「게시판에 작품 붙이는 법」을 읽는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X03','K3-2-u5-X02']::text[],false,'{"seq":20,"concept":"K3-2-u5-C2","difficulty":3,"kind":"error","stem":"「게시판에 작품 붙이는 법」을 읽는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「짐작이 그럴듯하면 사전은 안 펴도 돼.」","correct":true,"mis_target":"K3-2-u5-X03"},{"t":"친구 가 — 「‘테두리’에서 멈추지 말고 끝까지 읽자.」","mis":"K3-2-u5-X02"},{"t":"친구 나 — 「다 읽고 나서 ‘귀퉁이’를 사전에서 확인할래.」","mis":"K3-2-u5-X03"}],"explanation":["짐작은 빗나갈 수 있어요.","그래서 확인해요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#21','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C24',3,'mc','auto','‘들쑥날쑥’의 뜻을 짐작할 때 가장 도움이 되는 말은 무엇인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":21,"concept":"K3-2-u5-C24","difficulty":3,"kind":"mc","stem":"‘들쑥날쑥’의 뜻을 짐작할 때 가장 도움이 되는 말은 무엇인가요?","options":[{"t":"앞에 나온 “아무 데나 붙이면”","correct":true},{"t":"낱말 안의 ‘쑥’이라는 소리","mis":"K3-2-u5-X25"},{"t":"1번 줄의 ‘테두리’","mis":"K3-2-u5-X25"},{"t":"5번 줄의 ‘한 걸음’","mis":"K3-2-u5-X25"}],"explanation":["앞뒤 문장이 실마리예요.","아무 데나 붙인 모습이에요.","그 말이 가장 도움이 돼요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#22','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C21',3,'mc','auto','세 낱말을 국어사전에 실리는 차례대로 늘어놓은 것은 무엇인가요?',ARRAY['K3-2-u5-X22','K3-2-u5-X20']::text[],false,'{"seq":22,"concept":"K3-2-u5-C21","difficulty":3,"kind":"mc","stem":"세 낱말을 국어사전에 실리는 차례대로 늘어놓은 것은 무엇인가요?","options":[{"t":"바늘 → 바다 → 바람","correct":true},{"t":"바람 → 바다 → 바늘","mis":"K3-2-u5-X22"},{"t":"바다 → 바람 → 바늘","mis":"K3-2-u5-X22"},{"t":"바늘 → 바람 → 바다","mis":"K3-2-u5-X20"}],"explanation":["첫 글자 ‘바’는 같아요.","두 번째 글자 ‘늘·다·람’을 봐요.","ㄴ → ㄷ → ㄹ 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#23','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C15',4,'mc','auto','「체육 창고 정리」의 아홉 낱말을 나눈 세 결과예요. 각 결과를 만든 기준을 바르게 짝지은 것은 무엇인가요? (㉠ 셋·셋·셋 ㉡ 선반·호루라기·수건 / 나머지 여섯 ㉢ 호루라기·축축하다·가지런하다 / 나머지 여섯)',ARRAY['K3-2-u5-X14','K3-2-u5-X16']::text[],false,'{"seq":23,"concept":"K3-2-u5-C15","difficulty":4,"kind":"mc","stem":"「체육 창고 정리」의 아홉 낱말을 나눈 세 결과예요. 각 결과를 만든 기준을 바르게 짝지은 것은 무엇인가요? (㉠ 셋·셋·셋 ㉡ 선반·호루라기·수건 / 나머지 여섯 ㉢ 호루라기·축축하다·가지런하다 / 나머지 여섯)","options":[{"t":"㉠ 종류 · ㉡ 모양이 바뀌는가 · ㉢ 두 글자인가","correct":true},{"t":"㉠ 종류 · ㉡ 두 글자인가 · ㉢ 모양이 바뀌는가","mis":"K3-2-u5-X14"},{"t":"㉠ 모양이 바뀌는가 · ㉡ 종류 · ㉢ 두 글자인가","mis":"K3-2-u5-X14"},{"t":"셋 다 같은 기준인데 한 번만 바르게 나누었다","mis":"K3-2-u5-X16"}],"explanation":["㉡의 셋은 모두 이름이에요.","㉢의 셋은 두 글자가 넘어요.","결과를 보면 기준이 보여요."],"asset":{"type":"passage","lines":["선반 · 쌓다 · 축축하다 · 호루라기 · 감다","가지런하다 · 수건 · 넣다 · 높다"],"title":"「체육 창고 정리」에서 고른 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#24','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C14',4,'essay','teacher','「낱말을 여럿 놓고 나눌 때 가장 먼저 할 일은?」에 답하고, 「체육 창고 정리」의 아홉 낱말을 두 가지 기준으로 나눈 결과를 예로 들어 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u5-C14","difficulty":4,"kind":"essay","stem":"「낱말을 여럿 놓고 나눌 때 가장 먼저 할 일은?」에 답하고, 「체육 창고 정리」의 아홉 낱말을 두 가지 기준으로 나눈 결과를 예로 들어 까닭을 쓰세요.","answer_guide":{"answer":"예: 무엇을 보고 나눌지 기준을 먼저 정한다. 같은 아홉 낱말을 종류로 나누면 이름(선반·호루라기·수건)·움직임(쌓다·감다·넣다)·성질이나 상태(높다·축축하다·가지런하다)로 셋·셋·셋이 되지만, 모양이 바뀌는가로 나누면 바뀌지 않는 셋(선반·호루라기·수건)과 바뀌는 여섯으로 나뉜다. 기준이 바뀌면 결과도 바뀌기 때문에 기준부터 정해야 한다.","scoring_points":["기준을 먼저 정한다고 썼는가","두 기준으로 나눈 결과를 바르게 썼는가","기준이 바뀌면 결과가 바뀐다는 까닭을 썼는가"]},"explanation":["기준부터 정해요.","두 번 나누어 봐요.","결과가 달라져요."],"asset":{"type":"passage","lines":["선반 · 쌓다 · 축축하다 · 호루라기 · 감다","가지런하다 · 수건 · 넣다 · 높다"],"title":"「체육 창고 정리」에서 고른 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_a#25','kor',3,2,'u5','','g3_2_kor_u5_review_a','unit_review','K3-2-u5-C15',4,'essay','teacher','두 모둠이 같은 낱말을 서로 다르게 나누었을 때 「저 모둠이 틀렸어.」라고 말하기 전에 무엇을 먼저 물어보아야 하는지 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u5-C15","difficulty":4,"kind":"essay","stem":"두 모둠이 같은 낱말을 서로 다르게 나누었을 때 「저 모둠이 틀렸어.」라고 말하기 전에 무엇을 먼저 물어보아야 하는지 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 무엇을 기준으로 나누었는지 먼저 물어보아야 한다. 같은 낱말이라도 종류로 나누는지, 모양이 바뀌는가로 나누는지, 글자 수로 나누는지에 따라 나뉘는 결과가 달라지기 때문이다. 기준이 다르면 두 모둠 다 바르게 나누었을 수 있다.","scoring_points":["기준을 먼저 묻는다고 썼는가","기준에 따라 결과가 달라진다고 썼는가","둘 다 바를 수 있다고 썼는가"]},"explanation":["결과보다 기준이에요.","기준이 다르면 결과도 달라요.","둘 다 바를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#1','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C2',1,'ox','auto','모르는 낱말이 하나라도 나오면 그 글은 끝까지 읽을 수 없어요.',ARRAY['K3-2-u5-X02']::text[],false,'{"seq":1,"concept":"K3-2-u5-C2","difficulty":1,"kind":"ox","stem":"모르는 낱말이 하나라도 나오면 그 글은 끝까지 읽을 수 없어요.","answer":"X","reason_options":[{"t":"앞뒤로 짐작하며 끝까지 읽고 뒤에 확인하면 되기 때문에","correct":true},{"t":"모르는 낱말이 있으면 글의 뜻을 하나도 알 수 없기 때문에","mis":"K3-2-u5-X02"}],"mis":"K3-2-u5-X02","explanation":["어귀를 몰라도 글은 이어져요.","짐작하며 끝까지 읽어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#2','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C4',1,'mc','auto','「체육 창고 정리」에서 고른 낱말 가운데 움직임을 나타내는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X05']::text[],false,'{"seq":2,"concept":"K3-2-u5-C4","difficulty":1,"kind":"mc","stem":"「체육 창고 정리」에서 고른 낱말 가운데 움직임을 나타내는 낱말은 무엇인가요?","options":[{"t":"넣다","correct":true},{"t":"수건","mis":"K3-2-u5-X04"},{"t":"높다","mis":"K3-2-u5-X05"},{"t":"가지런하다","mis":"K3-2-u5-X05"}],"explanation":["“공을 ○○” 하고 읽어요.","“공을 넣는다”가 돼요.","움직임을 나타내요."],"asset":{"type":"passage","lines":["선반 · 쌓다 · 축축하다 · 호루라기 · 감다","가지런하다 · 수건 · 넣다 · 높다"],"title":"「체육 창고 정리」에서 고른 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#3','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C7',1,'ox','auto','‘잠’은 이름을, ‘자다’는 움직임을 나타내요.',ARRAY['K3-2-u5-X06']::text[],false,'{"seq":3,"concept":"K3-2-u5-C7","difficulty":1,"kind":"ox","stem":"‘잠’은 이름을, ‘자다’는 움직임을 나타내요.","answer":"O","reason_options":[{"t":"“잠이 쏟아진다”와 “동생이 잔다”에서 들어가는 쪽이 다르기 때문에","correct":true},{"t":"닮은 짝 가운데 짧은 쪽은 언제나 이름이기 때문에","mis":"K3-2-u5-X06"}],"mis":"K3-2-u5-X06","explanation":["‘잠’은 ‘무엇’ 쪽이에요.","‘자다’는 ‘한다’ 쪽이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#4','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C12',1,'mc','auto','“줄넘기는 둥글게 감아 걸었다”에서 ‘감아’의 기본형은 무엇인가요?',ARRAY['K3-2-u5-X11']::text[],false,'{"seq":4,"concept":"K3-2-u5-C12","difficulty":1,"kind":"mc","stem":"“줄넘기는 둥글게 감아 걸었다”에서 ‘감아’의 기본형은 무엇인가요?","options":[{"t":"감다","correct":true},{"t":"감아다","mis":"K3-2-u5-X11"},{"t":"감으다","mis":"K3-2-u5-X11"},{"t":"감","mis":"K3-2-u5-X11"}],"explanation":["‘감고 · 감으니 · 감아’.","‘감’이 그대로예요.","‘감다’예요."],"asset":{"type":"passage","lines":["체육 시간이 끝나고 짝과 체육 창고를 정리했다.","공은 바구니에 넣고, 줄넘기는 둥글게 감아 걸었다.","젖은 수건은 아직 축축해서 따로 널었다.","선반이 높아서 짝이 의자를 붙잡아 주었다.","호루라기는 선생님 책상 위에 두었다.","상자를 차곡차곡 쌓으니 창고 안이 한결 가지런했다."],"title":"글 「체육 창고 정리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#5','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C14',1,'mc','auto','친구와 함께 낱말 카드를 나누려고 해요. 먼저 정할 것은 무엇인가요?',ARRAY['K3-2-u5-X15','K3-2-u5-X14']::text[],false,'{"seq":5,"concept":"K3-2-u5-C14","difficulty":1,"kind":"mc","stem":"친구와 함께 낱말 카드를 나누려고 해요. 먼저 정할 것은 무엇인가요?","options":[{"t":"무엇을 보고 나눌지","correct":true},{"t":"누가 더 빨리 나누는지","mis":"K3-2-u5-X15"},{"t":"낱말마다 정해진 칸","mis":"K3-2-u5-X14"},{"t":"카드를 몇 장씩 가질지","mis":"K3-2-u5-X15"}],"explanation":["보는 것이 같아야 함께 나눠요.","그것이 기준이에요.","기준을 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#6','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C18',1,'mc','auto','‘들’과 ‘뜰’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X19','K3-2-u5-X22']::text[],false,'{"seq":6,"concept":"K3-2-u5-C18","difficulty":1,"kind":"mc","stem":"‘들’과 ‘뜰’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?","options":[{"t":"들","correct":true},{"t":"뜰","mis":"K3-2-u5-X19"},{"t":"둘이 같은 쪽에 함께 실린다","mis":"K3-2-u5-X19"},{"t":"글자 수가 적은 낱말","mis":"K3-2-u5-X22"}],"explanation":["첫 자음자는 ㄷ과 ㄸ이에요.","ㄷ 바로 다음이 ㄸ이에요.","‘들’이 먼저예요."],"asset":{"type":"passage","lines":["ㄱ ㄲ ㄴ ㄷ ㄸ ㄹ ㅁ ㅂ ㅃ ㅅ ㅆ ㅇ ㅈ ㅉ ㅊ ㅋ ㅌ ㅍ ㅎ"],"title":"첫 자음자의 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#7','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C22',1,'mc','auto','‘넣어서’처럼 모양이 바뀐 낱말을 사전에서 찾기 전에 할 일은 무엇인가요?',ARRAY['K3-2-u5-X23','K3-2-u5-X11','K3-2-u5-X01']::text[],false,'{"seq":7,"concept":"K3-2-u5-C22","difficulty":1,"kind":"mc","stem":"‘넣어서’처럼 모양이 바뀐 낱말을 사전에서 찾기 전에 할 일은 무엇인가요?","options":[{"t":"기본형으로 되돌린다","correct":true},{"t":"바뀐 모양 그대로 찾는다","mis":"K3-2-u5-X23"},{"t":"앞 글자만 떼어 찾는다","mis":"K3-2-u5-X11"},{"t":"찾지 않고 넘어간다","mis":"K3-2-u5-X01"}],"explanation":["사전엔 기본형이 실려요.","사전을 펴기 전에 바꿔요.","‘넣다’로 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#8','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C31',1,'mc','auto','‘기운을 더 나게 해 주다’라는 뜻의 우리말은 무엇인가요?',ARRAY['K3-2-u5-X34']::text[],false,'{"seq":8,"concept":"K3-2-u5-C31","difficulty":1,"kind":"mc","stem":"‘기운을 더 나게 해 주다’라는 뜻의 우리말은 무엇인가요?","options":[{"t":"북돋우다","correct":true},{"t":"여미다","mis":"K3-2-u5-X34"},{"t":"아우르다","mis":"K3-2-u5-X34"},{"t":"찌그러지다","mis":"K3-2-u5-X34"}],"explanation":["기초 다지기의 우리말 셋이에요.","기운을 더 나게 해요.","‘북돋우다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#9','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C15',2,'mc','auto','「체육 창고 정리」의 아홉 낱말을 ‘두 글자인가’로 나누었을 때, 두 글자가 아닌 낱말끼리 모은 것은 무엇인가요?',ARRAY['K3-2-u5-X14']::text[],false,'{"seq":9,"concept":"K3-2-u5-C15","difficulty":2,"kind":"mc","stem":"「체육 창고 정리」의 아홉 낱말을 ‘두 글자인가’로 나누었을 때, 두 글자가 아닌 낱말끼리 모은 것은 무엇인가요?","options":[{"t":"호루라기 · 축축하다 · 가지런하다","correct":true},{"t":"선반 · 호루라기 · 수건","mis":"K3-2-u5-X14"},{"t":"쌓다 · 감다 · 넣다","mis":"K3-2-u5-X14"},{"t":"높다 · 축축하다 · 가지런하다","mis":"K3-2-u5-X14"}],"explanation":["글자 수를 세어 봐요.","호루라기는 네 글자예요.","셋이 두 글자가 넘어요."],"asset":{"type":"passage","lines":["선반 · 쌓다 · 축축하다 · 호루라기 · 감다","가지런하다 · 수건 · 넣다 · 높다"],"title":"「체육 창고 정리」에서 고른 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#10','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C10',2,'mc','auto','「체육 창고 정리」에서 모양이 바뀌지 않는 낱말이 쓰인 곳은 어디인가요?',ARRAY['K3-2-u5-X09']::text[],false,'{"seq":10,"concept":"K3-2-u5-C10","difficulty":2,"kind":"mc","stem":"「체육 창고 정리」에서 모양이 바뀌지 않는 낱말이 쓰인 곳은 어디인가요?","options":[{"t":"“호루라기는 선생님 책상 위에 두었다.”의 ‘호루라기’","correct":true},{"t":"“줄넘기는 둥글게 감아 걸었다.”의 ‘감아’","mis":"K3-2-u5-X09"},{"t":"“선반이 높아서”의 ‘높아서’","mis":"K3-2-u5-X09"},{"t":"“상자를 차곡차곡 쌓으니”의 ‘쌓으니’","mis":"K3-2-u5-X09"}],"explanation":["이름을 나타내는 낱말을 찾아요.","뒤에 ‘는’이 붙어도 낱말은 그대로예요.","‘호루라기’예요."],"asset":{"type":"passage","lines":["체육 시간이 끝나고 짝과 체육 창고를 정리했다.","공은 바구니에 넣고, 줄넘기는 둥글게 감아 걸었다.","젖은 수건은 아직 축축해서 따로 널었다.","선반이 높아서 짝이 의자를 붙잡아 주었다.","호루라기는 선생님 책상 위에 두었다.","상자를 차곡차곡 쌓으니 창고 안이 한결 가지런했다."],"title":"글 「체육 창고 정리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#11','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C21',2,'mc','auto','‘바늘’과 ‘바다’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X22']::text[],false,'{"seq":11,"concept":"K3-2-u5-C21","difficulty":2,"kind":"mc","stem":"‘바늘’과 ‘바다’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?","options":[{"t":"바늘","correct":true},{"t":"바다","mis":"K3-2-u5-X22"},{"t":"둘이 같은 쪽에 함께 실린다","mis":"K3-2-u5-X22"},{"t":"글자 수가 적은 낱말","mis":"K3-2-u5-X22"}],"explanation":["첫 글자 ‘바’가 같아요.","두 번째 글자 ‘늘’과 ‘다’를 봐요.","ㄴ이 ㄷ보다 앞이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#12','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C24',2,'mc','auto','4번 줄의 ‘들쑥날쑥해 보인다’를 앞뒤로 짐작한 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":12,"concept":"K3-2-u5-C24","difficulty":2,"kind":"mc","stem":"4번 줄의 ‘들쑥날쑥해 보인다’를 앞뒤로 짐작한 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"들어가고 나온 것이 고르지 않아 보인다","correct":true},{"t":"모두 가지런해 보인다","mis":"K3-2-u5-X25"},{"t":"색깔이 화려해 보인다","mis":"K3-2-u5-X25"},{"t":"크기가 커 보인다","mis":"K3-2-u5-X25"}],"explanation":["“아무 데나 붙이면”이 앞에 있어요.","차례 없이 붙인 모습이에요.","고르지 않아 보여요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#13','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C25',2,'ox','auto','짐작한 뜻이 사전과 달랐다면 사전을 펴 본 보람이 있는 거예요.',ARRAY['K3-2-u5-X26']::text[],false,'{"seq":13,"concept":"K3-2-u5-C25","difficulty":2,"kind":"ox","stem":"짐작한 뜻이 사전과 달랐다면 사전을 펴 본 보람이 있는 거예요.","answer":"O","reason_options":[{"t":"빗나간 짐작을 바로잡아 글을 더 정확하게 읽을 수 있기 때문에","correct":true},{"t":"짐작이 틀리면 그 글은 다시 읽을 수 없기 때문에","mis":"K3-2-u5-X26"}],"mis":"K3-2-u5-X26","explanation":["확인은 바로잡으려고 해요.","빗나간 것을 찾았어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#14','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C16',2,'mc','auto','「잃어버린 것을 말하는 법」에서 선생님이 물통을 바로 집어 주실 수 있었던 까닭은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":14,"concept":"K3-2-u5-C16","difficulty":2,"kind":"mc","stem":"「잃어버린 것을 말하는 법」에서 선생님이 물통을 바로 집어 주실 수 있었던 까닭은 무엇인가요?","options":[{"t":"손잡이·뚜껑·겉 모양을 낱말로 자세히 말씀드려서","correct":true},{"t":"물통을 새로 사 오셔서","mis":"K3-2-u5-X17"},{"t":"물통이 상자에 하나뿐이어서","mis":"K3-2-u5-X17"},{"t":"짝이 대신 찾아 주어서","mis":"K3-2-u5-X17"}],"explanation":["처음엔 “이렇게 생긴 거”라고만 했어요.","두 번째엔 낱말로 말했어요.","그래서 바로 찾으셨어요."],"asset":{"type":"passage","lines":["교실에서 짝이 물었다. “손잡이는 있어? 뚜껑은 어떻게 여닫아? 겉은 어때?”","하나씩 떠올랐다. 손잡이가 달렸고, 뚜껑을 돌려서 여닫고, 겉이 까슬까슬하고,","바닥이 조금 찌그러졌고, 물을 채우면 꽤 묵직했다.","그대로 말씀드리자 선생님은 상자에서 하나를 바로 집어 주셨다.","물통은 처음부터 거기 있었다. 없던 것은 그것을 말할 낱말이었다."],"title":"이야기 「잃어버린 것을 말하는 법」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#15','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C27',2,'mc','auto','‘선반’의 단서 셋째 장(쓰인 문장)으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X29']::text[],false,'{"seq":15,"concept":"K3-2-u5-C27","difficulty":2,"kind":"mc","stem":"‘선반’의 단서 셋째 장(쓰인 문장)으로 알맞은 것은 무엇인가요?","options":[{"t":"“공을 (　) 위에 올려 두었다.”","correct":true},{"t":"“공을 선반 위에 올려 두었다.”","mis":"K3-2-u5-X29"},{"t":"“선반은 선반이다.”","mis":"K3-2-u5-X29"},{"t":"“(　)를 신고 달렸다.”","mis":"K3-2-u5-X29"}],"explanation":["낱말 자리를 비워요.","선반이 어울리는 문장이어야 해요.","공을 올려 두는 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#16','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C28',2,'mc','auto','낱말 공책을 사전 차례로 적으면 좋은 점은 무엇인가요?',ARRAY['K3-2-u5-X30','K3-2-u5-X07']::text[],false,'{"seq":16,"concept":"K3-2-u5-C28","difficulty":2,"kind":"mc","stem":"낱말 공책을 사전 차례로 적으면 좋은 점은 무엇인가요?","options":[{"t":"나중에 다시 찾아볼 때 쉽게 찾을 수 있다","correct":true},{"t":"공책이 더 예뻐 보인다","mis":"K3-2-u5-X30"},{"t":"글씨를 더 빨리 쓸 수 있다","mis":"K3-2-u5-X07"},{"t":"낱말을 적은 날짜를 알 수 있다","mis":"K3-2-u5-X30"}],"explanation":["공책도 다시 펴 봐요.","사전처럼 차례가 있으면 좋아요.","찾기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#17','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C15',3,'error','auto','「체육 창고 정리」의 아홉 낱말을 두 모둠이 다르게 나누었어요. 잘못 생각한 친구는 누구인가요?',ARRAY['K3-2-u5-X16','K3-2-u5-X14','K3-2-u5-X15']::text[],false,'{"seq":17,"concept":"K3-2-u5-C15","difficulty":3,"kind":"error","stem":"「체육 창고 정리」의 아홉 낱말을 두 모둠이 다르게 나누었어요. 잘못 생각한 친구는 누구인가요?","options":[{"t":"친구 다 — 「우리 모둠과 다르게 나왔으니 저 모둠이 틀렸어.」","correct":true,"mis_target":"K3-2-u5-X16"},{"t":"친구 가 — 「저 모둠은 무엇을 기준으로 나눴는지 물어보자.」","mis":"K3-2-u5-X14"},{"t":"친구 나 — 「우리는 종류로, 저 모둠은 글자 수로 나눴네.」","mis":"K3-2-u5-X15"}],"explanation":["결과보다 기준을 먼저 봐요.","기준이 달랐어요.","친구 다가 잘못 생각했어요."],"asset":{"type":"passage","lines":["선반 · 쌓다 · 축축하다 · 호루라기 · 감다","가지런하다 · 수건 · 넣다 · 높다"],"title":"「체육 창고 정리」에서 고른 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#18','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C13',3,'ox','auto','“짝과 상자를 쌓아서 옮겼다.”는 ‘쌓아서’가 사전에 없으니 틀린 문장이에요.',ARRAY['K3-2-u5-X12']::text[],false,'{"seq":18,"concept":"K3-2-u5-C13","difficulty":3,"kind":"ox","stem":"“짝과 상자를 쌓아서 옮겼다.”는 ‘쌓아서’가 사전에 없으니 틀린 문장이에요.","answer":"X","reason_options":[{"t":"‘쌓아서’는 ‘쌓다’가 문장에 맞게 바뀐 바른 말이기 때문에","correct":true},{"t":"사전에 없는 모양은 모두 틀린 말이기 때문에","mis":"K3-2-u5-X12"}],"mis":"K3-2-u5-X12","explanation":["사전엔 ‘쌓다’가 실려요.","‘쌓아서’는 바뀐 모양이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#19','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C23',3,'error','auto','국어사전에 실린 것을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X24','K3-2-u5-X13']::text[],false,'{"seq":19,"concept":"K3-2-u5-C23","difficulty":3,"kind":"error","stem":"국어사전에 실린 것을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「사전은 뜻만 알려 주니까 쓰인 문장은 따로 찾아야 해.」","correct":true,"mis_target":"K3-2-u5-X24"},{"t":"친구 나 — 「사전에서 읽는 법도 볼 수 있어.」","mis":"K3-2-u5-X24"},{"t":"친구 다 — 「바뀐 모양은 기본형으로 바꾸어 찾아.」","mis":"K3-2-u5-X13"}],"explanation":["사전엔 쓰인 문장도 실려요.","뜻만 있는 것이 아니에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#20','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C2',3,'mc','auto','모르는 낱말을 만났을 때 하는 일을 차례대로 늘어놓은 것은 무엇인가요?',ARRAY['K3-2-u5-X02','K3-2-u5-X03','K3-2-u5-X01']::text[],false,'{"seq":20,"concept":"K3-2-u5-C2","difficulty":3,"kind":"mc","stem":"모르는 낱말을 만났을 때 하는 일을 차례대로 늘어놓은 것은 무엇인가요?","options":[{"t":"공책에 적어 두기 → 짐작하며 끝까지 읽기 → 사전에서 확인하기 → 다시 읽기","correct":true},{"t":"사전에서 확인하기 → 공책에 적어 두기 → 다시 읽기 → 짐작하기","mis":"K3-2-u5-X02"},{"t":"짐작하며 끝까지 읽기 → 다 읽었으니 끝내기","mis":"K3-2-u5-X03"},{"t":"그 낱말을 건너뛰고 끝까지 읽기","mis":"K3-2-u5-X01"}],"explanation":["지금은 멈추지 않아요.","다 읽은 뒤에 확인해요.","고쳐 알고 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#21','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C26',3,'mc','auto','「게시판에 작품 붙이는 법」에서 ‘테두리 · 귀퉁이 · 들쑥날쑥하다’의 뜻을 알고 다시 읽으면 무엇이 달라질까요?',ARRAY['K3-2-u5-X28','K3-2-u5-X17']::text[],false,'{"seq":21,"concept":"K3-2-u5-C26","difficulty":3,"kind":"mc","stem":"「게시판에 작품 붙이는 법」에서 ‘테두리 · 귀퉁이 · 들쑥날쑥하다’의 뜻을 알고 다시 읽으면 무엇이 달라질까요?","options":[{"t":"붙이는 방법이 또렷해져 그대로 따라 할 수 있다","correct":true},{"t":"글을 훨씬 빨리 읽게 된다","mis":"K3-2-u5-X28"},{"t":"작품을 아무 데나 붙여도 된다는 것을 안다","mis":"K3-2-u5-X17"},{"t":"게시판이 필요 없다는 것을 안다","mis":"K3-2-u5-X17"}],"explanation":["낱말을 알면 글이 또렷해져요.","따라 하기 쉬워요.","빠르기가 아니에요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#22','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C20',3,'error','auto','‘무’와 ‘물’의 차례를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X21']::text[],false,'{"seq":22,"concept":"K3-2-u5-C20","difficulty":3,"kind":"error","stem":"‘무’와 ‘물’의 차례를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「받침이 있는 ‘물’이 더 꽉 차 있으니 먼저 실려.」","correct":true,"mis_target":"K3-2-u5-X21"},{"t":"친구 가 — 「첫 자음자 ㅁ과 모음자 ㅜ가 같아.」","mis":"K3-2-u5-X21"},{"t":"친구 나 — 「받침이 없는 ‘무’가 먼저야.」","mis":"K3-2-u5-X21"}],"explanation":["첫 자음자·모음자가 같아요.","받침이 없는 쪽이 먼저예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#23','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C13',4,'mc','auto','동생이 일기에 “선반이 높아서 의자를 놓았다.”라고 쓰고는 「사전에 ‘높아서’가 없으니 고쳐야겠다.」라고 했어요. 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X12','K3-2-u5-X13','K3-2-u5-X10']::text[],false,'{"seq":23,"concept":"K3-2-u5-C13","difficulty":4,"kind":"mc","stem":"동생이 일기에 “선반이 높아서 의자를 놓았다.”라고 쓰고는 「사전에 ‘높아서’가 없으니 고쳐야겠다.」라고 했어요. 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“‘높아서’는 ‘높다’가 문장에 맞게 바뀐 바른 말이니 고치지 않아도 돼. 사전에서 찾을 때만 ‘높다’로 찾아.”","correct":true},{"t":"“맞아. ‘선반이 높다 의자를 놓았다’로 고쳐야 해.”","mis":"K3-2-u5-X12"},{"t":"“더 두꺼운 사전을 보면 ‘높아서’도 있을 거야.”","mis":"K3-2-u5-X13"},{"t":"“사전을 만든 사람이 빠뜨린 거니까 그냥 둬.”","mis":"K3-2-u5-X10"}],"explanation":["‘높아서’는 바른 말이에요.","사전엔 대표 모양만 실려요.","찾을 때만 ‘높다’로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#24','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C13',4,'essay','teacher','기본형이 무엇인지 쓰고, 「사전에 없는 모양은 틀린 말이야.」라는 생각이 왜 알맞지 않은지 「체육 창고 정리」의 낱말 하나를 예로 들어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u5-C13","difficulty":4,"kind":"essay","stem":"기본형이 무엇인지 쓰고, 「사전에 없는 모양은 틀린 말이야.」라는 생각이 왜 알맞지 않은지 「체육 창고 정리」의 낱말 하나를 예로 들어 쓰세요.","answer_guide":{"answer":"예: 기본형은 바뀌지 않는 부분에 ‘-다’를 붙인 대표 모양으로, 사전에 실을 때 고른 것이다. 낱말 하나에 바뀐 모양이 너무 많아 사전에는 기본형만 싣는다. 「체육 창고 정리」의 ‘쌓으니’는 사전에 없지만 ‘쌓다’가 문장에 맞게 바뀐 바른 말이다.","scoring_points":["기본형의 뜻을 썼는가","사전에 기본형만 싣는 까닭을 썼는가","낱말 하나를 예로 들어 바른 말이라고 썼는가"]},"explanation":["기본형은 대표 모양이에요.","모양이 너무 많아 하나만 실어요.","바뀐 모양도 바른 말이에요."],"asset":{"type":"passage","lines":["체육 시간이 끝나고 짝과 체육 창고를 정리했다.","공은 바구니에 넣고, 줄넘기는 둥글게 감아 걸었다.","젖은 수건은 아직 축축해서 따로 널었다.","선반이 높아서 짝이 의자를 붙잡아 주었다.","호루라기는 선생님 책상 위에 두었다.","상자를 차곡차곡 쌓으니 창고 안이 한결 가지런했다."],"title":"글 「체육 창고 정리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_b#25','kor',3,2,'u5','','g3_2_kor_u5_review_b','unit_review','K3-2-u5-C25',4,'essay','teacher','짐작한 뜻이 사전의 뜻과 달랐을 때와 같았을 때 각각 어떻게 할지 쓰고, 두 경우 모두 확인한 보람이 있는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u5-C25","difficulty":4,"kind":"essay","stem":"짐작한 뜻이 사전의 뜻과 달랐을 때와 같았을 때 각각 어떻게 할지 쓰고, 두 경우 모두 확인한 보람이 있는 까닭을 쓰세요.","answer_guide":{"answer":"예: 달랐을 때는 사전의 뜻으로 고쳐 알고 그 줄을 다시 읽는다. 같았을 때는 짐작이 맞았음을 확인하고 그 뜻을 확실히 알게 된다. 다르면 틀린 뜻을 바로잡을 수 있고, 같으면 어림이 아니라 확실한 뜻으로 알게 되니 두 경우 모두 확인한 보람이 있다.","scoring_points":["달랐을 때 할 일을 썼는가","같았을 때 할 일을 썼는가","두 경우 모두 보람이 있는 까닭을 썼는가"]},"explanation":["다르면 고쳐 알아요.","같으면 확실히 알아요.","어느 쪽이든 보람이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#1','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C1',1,'mc','auto','이 단원에서 배운 두 가지는 무엇인가요?',ARRAY['K3-2-u5-X07','K3-2-u5-X01']::text[],false,'{"seq":1,"concept":"K3-2-u5-C1","difficulty":1,"kind":"mc","stem":"이 단원에서 배운 두 가지는 무엇인가요?","options":[{"t":"기준에 따라 낱말 나누기와 국어사전 쓰기","correct":true},{"t":"글씨 쓰기와 줄넘기","mis":"K3-2-u5-X07"},{"t":"낱말 외우기와 빨리 읽기","mis":"K3-2-u5-X07"},{"t":"모르는 말 건너뛰기와 짐작만 하기","mis":"K3-2-u5-X01"}],"explanation":["둘 다 낱말을 다뤄요.","하나는 낱말 나누기예요.","하나는 국어사전 쓰기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#2','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C5',1,'mc','auto','「체육 창고 정리」에서 고른 낱말 가운데 성질이나 상태를 나타내는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X05','K3-2-u5-X04']::text[],false,'{"seq":2,"concept":"K3-2-u5-C5","difficulty":1,"kind":"mc","stem":"「체육 창고 정리」에서 고른 낱말 가운데 성질이나 상태를 나타내는 낱말은 무엇인가요?","options":[{"t":"축축하다","correct":true},{"t":"감다","mis":"K3-2-u5-X05"},{"t":"선반","mis":"K3-2-u5-X04"},{"t":"쌓다","mis":"K3-2-u5-X05"}],"explanation":["“수건이 ○○”에 넣어요.","수건이 어떠한지 말해요.","성질이나 상태예요."],"asset":{"type":"passage","lines":["선반 · 쌓다 · 축축하다 · 호루라기 · 감다","가지런하다 · 수건 · 넣다 · 높다"],"title":"「체육 창고 정리」에서 고른 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#3','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C6',1,'mc','auto','‘높다’를 넣었을 때 어울리는 틀은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X05','K3-2-u5-X06']::text[],false,'{"seq":3,"concept":"K3-2-u5-C6","difficulty":1,"kind":"mc","stem":"‘높다’를 넣었을 때 어울리는 틀은 무엇인가요?","options":[{"t":"“선반이 높다.” — ‘어떠하다’ 쪽","correct":true},{"t":"“이것이 높다이다.” — ‘무엇’ 쪽","mis":"K3-2-u5-X04"},{"t":"“선반을 높다.” — ‘한다’ 쪽","mis":"K3-2-u5-X05"},{"t":"세 틀에 다 어울린다","mis":"K3-2-u5-X06"}],"explanation":["세 틀에 차례로 넣어요.","“선반이 높다”만 자연스러워요.","성질이나 상태예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#4','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C9',1,'mc','auto','‘넣고 · 넣으니 · 넣어서’에서 바뀌지 않는 부분은 무엇인가요?',ARRAY['K3-2-u5-X08']::text[],false,'{"seq":4,"concept":"K3-2-u5-C9","difficulty":1,"kind":"mc","stem":"‘넣고 · 넣으니 · 넣어서’에서 바뀌지 않는 부분은 무엇인가요?","options":[{"t":"넣","correct":true},{"t":"넣으","mis":"K3-2-u5-X08"},{"t":"넣어","mis":"K3-2-u5-X08"},{"t":"고","mis":"K3-2-u5-X08"}],"explanation":["세 모양을 나란히 놓아요.","빠짐없이 든 곳은 ‘넣’이에요.","뒤쪽은 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#5','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C14',1,'mc','auto','기준 없이 생각나는 대로 낱말을 나누면 어떻게 될까요?',ARRAY['K3-2-u5-X15','K3-2-u5-X14']::text[],false,'{"seq":5,"concept":"K3-2-u5-C14","difficulty":1,"kind":"mc","stem":"기준 없이 생각나는 대로 낱말을 나누면 어떻게 될까요?","options":[{"t":"왜 그렇게 나누었는지 다른 사람이 알 수 없다","correct":true},{"t":"언제나 바르게 나뉜다","mis":"K3-2-u5-X15"},{"t":"낱말마다 정해진 칸에 저절로 들어간다","mis":"K3-2-u5-X14"},{"t":"더 많은 칸이 생겨 좋다","mis":"K3-2-u5-X15"}],"explanation":["기준은 나누는 까닭이에요.","기준이 없으면 까닭도 없어요.","다른 사람이 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#6','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C19',1,'mc','auto','‘귤’과 ‘그네’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X20','K3-2-u5-X22']::text[],false,'{"seq":6,"concept":"K3-2-u5-C19","difficulty":1,"kind":"mc","stem":"‘귤’과 ‘그네’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?","options":[{"t":"귤","correct":true},{"t":"그네","mis":"K3-2-u5-X20"},{"t":"둘이 같은 쪽에 함께 실린다","mis":"K3-2-u5-X20"},{"t":"글자 수가 적은 낱말","mis":"K3-2-u5-X22"}],"explanation":["첫 자음자는 ㄱ으로 같아요.","모음자는 ㅠ와 ㅡ예요.","ㅠ가 ㅡ보다 앞이에요."],"asset":{"type":"passage","lines":["ㅏ ㅐ ㅑ ㅒ ㅓ ㅔ ㅕ ㅖ ㅗ ㅘ ㅙ ㅚ ㅛ ㅜ ㅝ ㅞ ㅟ ㅠ ㅡ ㅢ ㅣ"],"title":"모음자의 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#7','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C23',1,'ox','auto','국어사전에서는 낱말을 소리 내어 읽는 법도 알 수 있어요.',ARRAY['K3-2-u5-X24']::text[],false,'{"seq":7,"concept":"K3-2-u5-C23","difficulty":1,"kind":"ox","stem":"국어사전에서는 낱말을 소리 내어 읽는 법도 알 수 있어요.","answer":"O","reason_options":[{"t":"사전에는 뜻과 함께 읽는 법도 실려 있기 때문에","correct":true},{"t":"읽는 법은 사전이 아니라 받아쓰기 공책에만 있기 때문에","mis":"K3-2-u5-X24"}],"mis":"K3-2-u5-X24","explanation":["사전은 뜻풀이표가 아니에요.","읽는 법도 실려요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#8','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C32',1,'mc','auto','‘참외’의 ‘외’에 든 모음자는 무엇인가요?',ARRAY['K3-2-u5-X35']::text[],false,'{"seq":8,"concept":"K3-2-u5-C32","difficulty":1,"kind":"mc","stem":"‘참외’의 ‘외’에 든 모음자는 무엇인가요?","options":[{"t":"ㅚ","correct":true},{"t":"ㅙ","mis":"K3-2-u5-X35"},{"t":"ㅘ","mis":"K3-2-u5-X35"},{"t":"ㅟ","mis":"K3-2-u5-X35"}],"explanation":["ㅗ 옆에 ㅣ가 붙었어요.","그래서 ㅚ예요.","또박또박 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#9','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C15',2,'mc','auto','아홉 낱말을 ‘모양이 바뀌는가’로 나눌 때와 ‘두 글자인가’로 나눌 때, 둘 다 여섯·셋으로 나뉘었어요. 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u5-X14','K3-2-u5-X16']::text[],false,'{"seq":9,"concept":"K3-2-u5-C15","difficulty":2,"kind":"mc","stem":"아홉 낱말을 ‘모양이 바뀌는가’로 나눌 때와 ‘두 글자인가’로 나눌 때, 둘 다 여섯·셋으로 나뉘었어요. 바르게 말한 것은 무엇인가요?","options":[{"t":"칸의 수는 같아도 칸에 든 낱말은 다르다","correct":true},{"t":"칸의 수가 같으니 든 낱말도 똑같다","mis":"K3-2-u5-X14"},{"t":"둘 가운데 하나는 잘못 나눈 것이다","mis":"K3-2-u5-X16"},{"t":"두 기준은 사실 같은 기준이다","mis":"K3-2-u5-X14"}],"explanation":["‘수건’은 안 바뀌지만 두 글자예요.","‘축축하다’는 바뀌지만 네 글자예요.","든 낱말이 달라요."],"asset":{"type":"passage","lines":["선반 · 쌓다 · 축축하다 · 호루라기 · 감다","가지런하다 · 수건 · 넣다 · 높다"],"title":"「체육 창고 정리」에서 고른 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#10','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C11',2,'mc','auto','사전에 ‘쌓다’는 있는데 ‘쌓으니’는 없는 까닭은 무엇인가요?',ARRAY['K3-2-u5-X12','K3-2-u5-X10']::text[],false,'{"seq":10,"concept":"K3-2-u5-C11","difficulty":2,"kind":"mc","stem":"사전에 ‘쌓다’는 있는데 ‘쌓으니’는 없는 까닭은 무엇인가요?","options":[{"t":"바뀐 모양이 너무 많아 대표 모양만 싣기 때문에","correct":true},{"t":"‘쌓으니’는 틀린 말이라서","mis":"K3-2-u5-X12"},{"t":"사전을 만든 사람이 빠뜨려서","mis":"K3-2-u5-X10"},{"t":"‘쌓으니’는 쓰지 않는 말이라서","mis":"K3-2-u5-X12"}],"explanation":["쌓고·쌓으니·쌓아서·쌓았다 ….","모양이 아주 많아요.","대표 모양 하나만 실어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#11','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C21',2,'mc','auto','‘오리’와 ‘오이’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X22']::text[],false,'{"seq":11,"concept":"K3-2-u5-C21","difficulty":2,"kind":"mc","stem":"‘오리’와 ‘오이’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?","options":[{"t":"오리","correct":true},{"t":"오이","mis":"K3-2-u5-X22"},{"t":"둘이 같은 쪽에 함께 실린다","mis":"K3-2-u5-X22"},{"t":"글자 수가 적은 낱말","mis":"K3-2-u5-X22"}],"explanation":["첫 글자 ‘오’가 같아요.","두 번째 글자 ‘리’와 ‘이’를 봐요.","ㄹ이 ㅇ보다 앞이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#12','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C24',2,'mc','auto','1~2번 줄로 보아 ‘테두리’의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":12,"concept":"K3-2-u5-C24","difficulty":2,"kind":"mc","stem":"1~2번 줄로 보아 ‘테두리’의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"둘레를 따라 두른 줄이나 꾸밈","correct":true},{"t":"게시판 한가운데에 붙이는 제목","mis":"K3-2-u5-X25"},{"t":"작품 뒤에 바르는 풀","mis":"K3-2-u5-X25"},{"t":"작품을 붙이는 차례","mis":"K3-2-u5-X25"}],"explanation":["“두른다”라고 했어요.","가장자리가 또렷해진다고 했어요.","둘레에 두른 거예요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#13','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C25',2,'mc','auto','두 사전에서 ‘테두리’를 찾았더니 뜻풀이 말이 조금 달랐어요. 바르게 생각한 것은 무엇인가요?',ARRAY['K3-2-u5-X27','K3-2-u5-X26']::text[],false,'{"seq":13,"concept":"K3-2-u5-C25","difficulty":2,"kind":"mc","stem":"두 사전에서 ‘테두리’를 찾았더니 뜻풀이 말이 조금 달랐어요. 바르게 생각한 것은 무엇인가요?","options":[{"t":"말이 조금 달라도 뜻이 같으면 된다","correct":true},{"t":"글자가 다르니 한 사전은 틀렸다","mis":"K3-2-u5-X27"},{"t":"더 긴 풀이가 맞는 뜻이다","mis":"K3-2-u5-X27"},{"t":"뜻을 알 수 없으니 찾지 않는다","mis":"K3-2-u5-X26"}],"explanation":["사전마다 말이 조금씩 달라요.","뜻이 같은지 봐요.","뜻이 같으면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#14','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C26',2,'mc','auto','「학교 안내도를 만드는 법」에서 걸리는 시간을 “오 분 남짓”처럼 적는 까닭은 무엇인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":14,"concept":"K3-2-u5-C26","difficulty":2,"kind":"mc","stem":"「학교 안내도를 만드는 법」에서 걸리는 시간을 “오 분 남짓”처럼 적는 까닭은 무엇인가요?","options":[{"t":"처음 온 사람이 셈하기 쉽게","correct":true},{"t":"안내도를 예쁘게 꾸미려고","mis":"K3-2-u5-X17"},{"t":"걷는 빠르기를 겨루려고","mis":"K3-2-u5-X17"},{"t":"도서관 문을 여는 시각을 알리려고","mis":"K3-2-u5-X17"}],"explanation":["9번 줄을 다시 읽어요.","셈하기 쉽다고 했어요.","처음 온 사람을 위해서예요."],"asset":{"type":"passage","lines":["6 길도 그린다. 평평한 길과 비탈진 길을 다르게 표시한다.","7 그렇게 해 두면 유모차나 휠체어로 다니는 사람이 길을 고를 수 있다.","8 문도 나누어 적는다. 밀거나 당겨서 여는 여닫이 문인지,","   옆으로 미는 문인지 적어 둔다.","9 걸리는 시간도 적는다. “정문에서 도서관까지 오 분 남짓”처럼 적으면","   처음 온 사람이 셈하기 쉽다.","10 안내도는 그림만으로는 모자라다. 낱말이 있어야 자세해진다."],"title":"설명하는 글 「학교 안내도를 만드는 법」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#15','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C29',2,'mc','auto','짝이 세 장을 다 열고도 못 맞혔어요. 이어서 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X31']::text[],false,'{"seq":15,"concept":"K3-2-u5-C29","difficulty":2,"kind":"mc","stem":"짝이 세 장을 다 열고도 못 맞혔어요. 이어서 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그 낱말을 사전에서 함께 찾아본다","correct":true},{"t":"짝이 졌다고 크게 말한다","mis":"K3-2-u5-X31"},{"t":"다시는 놀이를 하지 않는다","mis":"K3-2-u5-X31"},{"t":"답을 알려 주지 않고 끝낸다","mis":"K3-2-u5-X31"}],"explanation":["못 맞혀도 괜찮아요.","헤아려 본 것이 목표예요.","사전에서 함께 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#16','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C28',2,'mc','auto','낱말 공책에 “짝이 의자를 붙잡아 주었다.”의 ‘붙잡아’를 모았어요. 낱말 칸에 적을 모양은 무엇인가요?',ARRAY['K3-2-u5-X23','K3-2-u5-X11']::text[],false,'{"seq":16,"concept":"K3-2-u5-C28","difficulty":2,"kind":"mc","stem":"낱말 공책에 “짝이 의자를 붙잡아 주었다.”의 ‘붙잡아’를 모았어요. 낱말 칸에 적을 모양은 무엇인가요?","options":[{"t":"붙잡다","correct":true},{"t":"붙잡아","mis":"K3-2-u5-X23"},{"t":"붙잡아서","mis":"K3-2-u5-X23"},{"t":"붙잡","mis":"K3-2-u5-X11"}],"explanation":["낱말 칸엔 기본형을 적어요.","사전에서도 그 모양으로 찾아요.","‘붙잡다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#17','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C15',3,'mc','auto','‘수건’과 ‘높다’가 같은 칸에 들어가는 기준은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X09','K3-2-u5-X14']::text[],false,'{"seq":17,"concept":"K3-2-u5-C15","difficulty":3,"kind":"mc","stem":"‘수건’과 ‘높다’가 같은 칸에 들어가는 기준은 무엇인가요?","options":[{"t":"두 글자인가","correct":true},{"t":"낱말의 종류","mis":"K3-2-u5-X04"},{"t":"문장에 따라 모양이 바뀌는가","mis":"K3-2-u5-X09"},{"t":"어떤 기준으로도 같은 칸에 들어가지 않는다","mis":"K3-2-u5-X14"}],"explanation":["종류로는 이름과 성질·상태예요.","모양으로도 안 바뀜과 바뀜이에요.","둘 다 두 글자예요."],"asset":{"type":"passage","lines":["선반 · 쌓다 · 축축하다 · 호루라기 · 감다","가지런하다 · 수건 · 넣다 · 높다"],"title":"「체육 창고 정리」에서 고른 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#18','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C11',3,'error','auto','기본형과 사전을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X13','K3-2-u5-X10','K3-2-u5-X12']::text[],false,'{"seq":18,"concept":"K3-2-u5-C11","difficulty":3,"kind":"error","stem":"기본형과 사전을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「바뀐 모양이 다 실린 두꺼운 사전을 찾아보면 ‘감아’도 있어.」","correct":true,"mis_target":"K3-2-u5-X13"},{"t":"친구 가 — 「바뀐 모양을 다 실으면 사전이 몇 배로 두꺼워져.」","mis":"K3-2-u5-X10"},{"t":"친구 다 — 「그래서 사전엔 ‘감다’ 하나만 실어.」","mis":"K3-2-u5-X12"}],"explanation":["사전은 대표 모양만 실어요.","‘감아’는 ‘감다’로 찾아요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#19','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C23',3,'mc','auto','‘비탈’을 사전에서 찾았을 때, 쓰인 문장이 함께 있어서 좋은 점은 무엇인가요?',ARRAY['K3-2-u5-X24','K3-2-u5-X13','K3-2-u5-X28']::text[],false,'{"seq":19,"concept":"K3-2-u5-C23","difficulty":3,"kind":"mc","stem":"‘비탈’을 사전에서 찾았을 때, 쓰인 문장이 함께 있어서 좋은 점은 무엇인가요?","options":[{"t":"그 낱말이 실제로 어떻게 쓰이는지 알 수 있다","correct":true},{"t":"뜻을 찾지 않아도 된다","mis":"K3-2-u5-X24"},{"t":"바뀐 모양을 모두 알 수 있다","mis":"K3-2-u5-X13"},{"t":"글을 더 빨리 읽을 수 있다","mis":"K3-2-u5-X28"}],"explanation":["뜻만으로는 쓰임이 잘 안 보여요.","쓰인 문장이 보여 줘요.","어떻게 쓰는지 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#20','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C25',3,'mc','auto','짐작한 뜻과 사전의 뜻이 같았어요. 이때 알맞은 생각은 무엇인가요?',ARRAY['K3-2-u5-X03','K3-2-u5-X26']::text[],false,'{"seq":20,"concept":"K3-2-u5-C25","difficulty":3,"kind":"mc","stem":"짐작한 뜻과 사전의 뜻이 같았어요. 이때 알맞은 생각은 무엇인가요?","options":[{"t":"“짐작이 맞는지 확인해서 이제 뜻을 확실히 알았어.”","correct":true},{"t":"“처음부터 확인할 필요가 없었어.”","mis":"K3-2-u5-X03"},{"t":"“다음부터는 짐작만 해도 되겠어.”","mis":"K3-2-u5-X03"},{"t":"“맞았으니 사전보다 내 짐작이 낫네.”","mis":"K3-2-u5-X26"}],"explanation":["맞았어도 확인한 보람이 있어요.","이제 확실히 알아요.","다음에도 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#21','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C24',3,'mc','auto','‘비뚤어진 작품’을 다른 말로 바꾸어 읽을 때 뜻이 가장 잘 통하는 것은 무엇인가요?',ARRAY['K3-2-u5-X25']::text[],false,'{"seq":21,"concept":"K3-2-u5-C24","difficulty":3,"kind":"mc","stem":"‘비뚤어진 작품’을 다른 말로 바꾸어 읽을 때 뜻이 가장 잘 통하는 것은 무엇인가요?","options":[{"t":"한쪽으로 기울어진 작품","correct":true},{"t":"가장 잘 그린 작품","mis":"K3-2-u5-X25"},{"t":"가장 큰 작품","mis":"K3-2-u5-X25"},{"t":"이름이 적힌 작품","mis":"K3-2-u5-X25"}],"explanation":["물러서서 살피는 까닭을 떠올려요.","바르게 붙지 않은 작품이에요.","한쪽으로 기울어진 거예요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#22','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C19',3,'mc','auto','‘의자’와 ‘이불’ 가운데 국어사전에 먼저 실리는 낱말과 그 까닭을 바르게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u5-X20','K3-2-u5-X21','K3-2-u5-X22']::text[],false,'{"seq":22,"concept":"K3-2-u5-C19","difficulty":3,"kind":"mc","stem":"‘의자’와 ‘이불’ 가운데 국어사전에 먼저 실리는 낱말과 그 까닭을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"의자 — 모음자 ㅢ가 ㅣ보다 앞이라서","correct":true},{"t":"이불 — 모음자 ㅣ가 ㅢ보다 앞이라서","mis":"K3-2-u5-X20"},{"t":"이불 — 받침이 있어서","mis":"K3-2-u5-X21"},{"t":"의자 — 글자 수가 적어서","mis":"K3-2-u5-X22"}],"explanation":["첫 자음자는 ㅇ으로 같아요.","모음자 ㅢ와 ㅣ를 봐요.","ㅢ가 ㅣ보다 앞이에요."],"asset":{"type":"passage","lines":["ㅏ ㅐ ㅑ ㅒ ㅓ ㅔ ㅕ ㅖ ㅗ ㅘ ㅙ ㅚ ㅛ ㅜ ㅝ ㅞ ㅟ ㅠ ㅡ ㅢ ㅣ"],"title":"모음자의 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#23','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C27',4,'mc','auto','‘호루라기’로 「단서 세 장」을 만들었어요. 가장 알맞게 만든 것은 무엇인가요?',ARRAY['K3-2-u5-X04','K3-2-u5-X29']::text[],false,'{"seq":23,"concept":"K3-2-u5-C27","difficulty":4,"kind":"mc","stem":"‘호루라기’로 「단서 세 장」을 만들었어요. 가장 알맞게 만든 것은 무엇인가요?","options":[{"t":"이름을 나타내는 낱말 / 입에 물고 불어서 소리를 내는 물건 / 선생님께서 (　)를 부셨다.","correct":true},{"t":"움직임을 나타내는 낱말 / 입에 물고 불어서 소리를 내는 물건 / 선생님께서 (　)를 부셨다.","mis":"K3-2-u5-X04"},{"t":"이름을 나타내는 낱말 / 호루라기 / 선생님께서 (　)를 부셨다.","mis":"K3-2-u5-X29"},{"t":"이름을 나타내는 낱말 / 입에 물고 불어서 소리를 내는 물건 / 선생님께서 호루라기를 부셨다.","mis":"K3-2-u5-X29"}],"explanation":["종류는 이름이에요.","둘째 장엔 뜻을 적어요.","셋째 장은 낱말 자리를 비워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#24','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C23',4,'essay','teacher','‘비뚤어진’의 뜻을 국어사전에서 찾는 방법을 처음부터 순서대로 쓰고, 찾은 쪽에서 뜻 말고 함께 볼 수 있는 것을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u5-C23","difficulty":4,"kind":"essay","stem":"‘비뚤어진’의 뜻을 국어사전에서 찾는 방법을 처음부터 순서대로 쓰고, 찾은 쪽에서 뜻 말고 함께 볼 수 있는 것을 두 가지 쓰세요.","answer_guide":{"answer":"예: 먼저 ‘비뚤어진’의 바뀌지 않는 부분 ‘비뚤어지’에 ‘-다’를 붙여 기본형 ‘비뚤어지다’로 바꾼다. 첫 자음자 ㅂ 쪽을 펴고, 모음자 ㅣ, 다음 글자 ‘뚤’ 차례로 찾아간다. 찾은 쪽에서는 뜻과 함께 소리 내어 읽는 법과 그 낱말이 쓰인 문장도 볼 수 있다.","scoring_points":["기본형으로 바꾼다고 썼는가","첫 자음자·모음자·다음 글자 차례로 찾는다고 썼는가","뜻 말고 볼 수 있는 것 두 가지를 썼는가"]},"explanation":["기본형으로 바꿔요.","차례대로 찾아가요.","뜻 말고도 있어요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_c#25','kor',3,2,'u5','','g3_2_kor_u5_review_c','unit_review','K3-2-u5-C29',4,'essay','teacher','「단서 세 장」 놀이에서 세 장을 다 열고도 못 맞힌 친구에게 해 줄 말을 쓰고, 이 놀이의 목표가 무엇인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u5-C29","difficulty":4,"kind":"essay","stem":"「단서 세 장」 놀이에서 세 장을 다 열고도 못 맞힌 친구에게 해 줄 말을 쓰고, 이 놀이의 목표가 무엇인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: “못 맞혀도 괜찮아. 우리 같이 사전에서 찾아보자.”라고 말해 주겠다. 이 놀이의 목표는 이기는 것이 아니라 단서를 보며 낱말을 헤아려 보는 것이다. 종류·뜻·쓰인 문장을 살피며 생각하는 동안 낱말을 다루는 힘이 길러지기 때문이다.","scoring_points":["위로하며 함께 찾자고 말했는가","목표가 헤아려 보는 것이라고 썼는가","까닭을 썼는가"]},"explanation":["못 맞혀도 괜찮아요.","헤아려 보는 것이 목표예요.","사전에서 함께 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#1','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C2',1,'mc','auto','모르는 낱말을 확인하는 때로 가장 알맞은 것은 언제인가요?',ARRAY['K3-2-u5-X02','K3-2-u5-X03','K3-2-u5-X01']::text[],false,'{"seq":1,"concept":"K3-2-u5-C2","difficulty":1,"kind":"mc","stem":"모르는 낱말을 확인하는 때로 가장 알맞은 것은 언제인가요?","options":[{"t":"짐작하며 끝까지 읽은 뒤","correct":true},{"t":"낱말이 나오자마자","mis":"K3-2-u5-X02"},{"t":"확인하지 않는다","mis":"K3-2-u5-X03"},{"t":"글을 다 잊어버린 뒤","mis":"K3-2-u5-X01"}],"explanation":["먼저 끝까지 읽어요.","그동안 짐작해 두어요.","그 뒤에 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#2','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C4',1,'ox','auto','‘쌓다’는 움직임을 나타내는 낱말이에요.',ARRAY['K3-2-u5-X05']::text[],false,'{"seq":2,"concept":"K3-2-u5-C4","difficulty":1,"kind":"ox","stem":"‘쌓다’는 움직임을 나타내는 낱말이에요.","answer":"O","reason_options":[{"t":"“상자를 쌓는다”처럼 무엇을 하는지 나타내기 때문에","correct":true},{"t":"‘-다’로 끝나는 낱말은 모두 성질이나 상태를 나타내기 때문에","mis":"K3-2-u5-X05"}],"mis":"K3-2-u5-X05","explanation":["“상자를 ○○”에 넣어요.","무엇을 하는지 말해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#3','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C7',1,'mc','auto','“웃음이 터졌다.”와 “친구가 웃는다.”의 ‘웃음’과 ‘웃는다’에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u5-X06','K3-2-u5-X04']::text[],false,'{"seq":3,"concept":"K3-2-u5-C7","difficulty":1,"kind":"mc","stem":"“웃음이 터졌다.”와 “친구가 웃는다.”의 ‘웃음’과 ‘웃는다’에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"둘 다 바른 말이고 종류가 다르다","correct":true},{"t":"‘웃음’은 틀린 말이다","mis":"K3-2-u5-X06"},{"t":"둘은 같은 종류이다","mis":"K3-2-u5-X06"},{"t":"둘 다 이름을 나타낸다","mis":"K3-2-u5-X04"}],"explanation":["“웃음이 터졌다.”","“친구가 웃는다.”","둘 다 바르고 종류가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#4','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C12',1,'sa','auto','“선반이 높아서”에서 ‘높아서’의 기본형을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u5-C12","difficulty":1,"kind":"sa","stem":"“선반이 높아서”에서 ‘높아서’의 기본형을 쓰세요.","answer":["높다"],"explanation":["바뀌지 않는 부분은 ‘높’이에요.","‘-다’를 붙여요.","‘높다’예요."],"asset":{"type":"passage","lines":["체육 시간이 끝나고 짝과 체육 창고를 정리했다.","공은 바구니에 넣고, 줄넘기는 둥글게 감아 걸었다.","젖은 수건은 아직 축축해서 따로 널었다.","선반이 높아서 짝이 의자를 붙잡아 주었다.","호루라기는 선생님 책상 위에 두었다.","상자를 차곡차곡 쌓으니 창고 안이 한결 가지런했다."],"title":"글 「체육 창고 정리」"},"mis":"K3-2-u5-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#5','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C14',1,'error','auto','낱말을 나누기 전에 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X14']::text[],false,'{"seq":5,"concept":"K3-2-u5-C14","difficulty":1,"kind":"error","stem":"낱말을 나누기 전에 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「낱말마다 칸이 정해져 있으니 그 칸만 찾으면 돼.」","correct":true,"mis_target":"K3-2-u5-X14"},{"t":"친구 가 — 「종류로 나눌지 먼저 정하자.」","mis":"K3-2-u5-X14"},{"t":"친구 다 — 「모양이 바뀌는가로 나눠도 돼.」","mis":"K3-2-u5-X14"}],"explanation":["칸은 기준에 따라 달라져요.","기준을 먼저 정해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#6','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C18',1,'mc','auto','‘거울’과 ‘바늘’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X19','K3-2-u5-X22']::text[],false,'{"seq":6,"concept":"K3-2-u5-C18","difficulty":1,"kind":"mc","stem":"‘거울’과 ‘바늘’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?","options":[{"t":"거울","correct":true},{"t":"바늘","mis":"K3-2-u5-X19"},{"t":"둘이 같은 쪽에 함께 실린다","mis":"K3-2-u5-X19"},{"t":"글자 수가 적은 낱말","mis":"K3-2-u5-X22"}],"explanation":["첫 자음자는 ㄱ과 ㅂ이에요.","ㄱ이 맨 앞이에요.","‘거울’이 먼저예요."],"asset":{"type":"passage","lines":["ㄱ ㄲ ㄴ ㄷ ㄸ ㄹ ㅁ ㅂ ㅃ ㅅ ㅆ ㅇ ㅈ ㅉ ㅊ ㅋ ㅌ ㅍ ㅎ"],"title":"첫 자음자의 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#7','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C22',1,'mc','auto','‘쌓으니’를 사전에서 찾을 때 펼쳐 볼 낱말은 무엇인가요?',ARRAY['K3-2-u5-X23','K3-2-u5-X11']::text[],false,'{"seq":7,"concept":"K3-2-u5-C22","difficulty":1,"kind":"mc","stem":"‘쌓으니’를 사전에서 찾을 때 펼쳐 볼 낱말은 무엇인가요?","options":[{"t":"쌓다","correct":true},{"t":"쌓으니","mis":"K3-2-u5-X23"},{"t":"쌓았다","mis":"K3-2-u5-X23"},{"t":"쌓으","mis":"K3-2-u5-X11"}],"explanation":["바뀐 모양은 실려 있지 않아요.","‘쌓’ + 다예요.","‘쌓다’를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#8','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C30',1,'ox','auto','[한녀름]으로 소리 나도 쓸 때는 ‘한여름’으로 써요.',ARRAY['K3-2-u5-X33']::text[],false,'{"seq":8,"concept":"K3-2-u5-C30","difficulty":1,"kind":"ox","stem":"[한녀름]으로 소리 나도 쓸 때는 ‘한여름’으로 써요.","answer":"O","reason_options":[{"t":"달라지는 것은 소리뿐이기 때문에","correct":true},{"t":"소리 나는 대로 써야 바르기 때문에","mis":"K3-2-u5-X33"}],"mis":"K3-2-u5-X33","explanation":["소리는 [한녀름]이에요.","쓸 때는 그대로예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#9','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C15',2,'ox','auto','「체육 창고 정리」의 아홉 낱말을 종류로 나누어도, 글자 수로 나누어도 결과는 똑같아요.',ARRAY['K3-2-u5-X14']::text[],false,'{"seq":9,"concept":"K3-2-u5-C15","difficulty":2,"kind":"ox","stem":"「체육 창고 정리」의 아홉 낱말을 종류로 나누어도, 글자 수로 나누어도 결과는 똑같아요.","answer":"X","reason_options":[{"t":"기준이 다르면 칸의 수와 든 낱말이 달라지기 때문에","correct":true},{"t":"같은 낱말이면 어떤 기준으로 나누어도 결과가 같기 때문에","mis":"K3-2-u5-X14"}],"mis":"K3-2-u5-X14","explanation":["종류로는 셋·셋·셋이에요.","글자 수로는 여섯·셋이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["선반 · 쌓다 · 축축하다 · 호루라기 · 감다","가지런하다 · 수건 · 넣다 · 높다"],"title":"「체육 창고 정리」에서 고른 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#10','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C13',2,'error','auto','「체육 창고 정리」의 낱말을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X12','K3-2-u5-X13','K3-2-u5-X09']::text[],false,'{"seq":10,"concept":"K3-2-u5-C13","difficulty":2,"kind":"error","stem":"「체육 창고 정리」의 낱말을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「‘높아서’는 사전에 없으니까 ‘높다’로 고쳐 써야 해.」","correct":true,"mis_target":"K3-2-u5-X12"},{"t":"친구 나 — 「‘높아서’를 찾으려면 ‘높다’로 찾아야 해.」","mis":"K3-2-u5-X13"},{"t":"친구 다 — 「‘수건’은 문장이 달라져도 그대로야.」","mis":"K3-2-u5-X09"}],"explanation":["‘높아서’는 바른 말이에요.","찾을 때만 ‘높다’로 바꿔요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["체육 시간이 끝나고 짝과 체육 창고를 정리했다.","공은 바구니에 넣고, 줄넘기는 둥글게 감아 걸었다.","젖은 수건은 아직 축축해서 따로 널었다.","선반이 높아서 짝이 의자를 붙잡아 주었다.","호루라기는 선생님 책상 위에 두었다.","상자를 차곡차곡 쌓으니 창고 안이 한결 가지런했다."],"title":"글 「체육 창고 정리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#11','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C20',2,'mc','auto','‘토끼’와 ‘통’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?',ARRAY['K3-2-u5-X22']::text[],false,'{"seq":11,"concept":"K3-2-u5-C20","difficulty":2,"kind":"mc","stem":"‘토끼’와 ‘통’ 가운데 국어사전에 먼저 실리는 낱말은 무엇인가요?","options":[{"t":"토끼","correct":true},{"t":"통","mis":"K3-2-u5-X22"},{"t":"둘이 같은 쪽에 함께 실린다","mis":"K3-2-u5-X22"},{"t":"글자 수가 적은 낱말","mis":"K3-2-u5-X22"}],"explanation":["첫 글자 ‘토’와 ‘통’을 견주어요.","‘토’는 받침이 없어요.","‘토끼’가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#12','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C22',2,'sa','auto','5번 줄의 ‘비뚤어진’을 사전에서 찾으려면 어떤 모양으로 찾아야 하나요? 기본형으로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"K3-2-u5-C22","difficulty":2,"kind":"sa","stem":"5번 줄의 ‘비뚤어진’을 사전에서 찾으려면 어떤 모양으로 찾아야 하나요? 기본형으로 쓰세요.","answer":["비뚤어지다"],"explanation":["바뀌지 않는 부분은 ‘비뚤어지’예요.","‘-다’를 붙여요.","‘비뚤어지다’예요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"},"mis":"K3-2-u5-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#13','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C25',2,'error','auto','짐작한 뜻과 사전의 뜻이 달랐을 때를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X26']::text[],false,'{"seq":13,"concept":"K3-2-u5-C25","difficulty":2,"kind":"error","stem":"짐작한 뜻과 사전의 뜻이 달랐을 때를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「내 짐작이 더 그럴듯하니까 사전이 잘못 적었어.」","correct":true,"mis_target":"K3-2-u5-X26"},{"t":"친구 가 — 「사전의 뜻으로 고쳐 알면 돼.」","mis":"K3-2-u5-X26"},{"t":"친구 나 — 「그 줄을 다시 읽어 보니 뜻이 통해.」","mis":"K3-2-u5-X26"}],"explanation":["사전의 뜻으로 고쳐 알아요.","다시 읽으면 통해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#14','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C26',2,'ox','auto','「게시판에 작품 붙이는 법」은 작품을 위쪽 귀퉁이부터 차례로 붙이라고 했어요.',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":14,"concept":"K3-2-u5-C26","difficulty":2,"kind":"ox","stem":"「게시판에 작품 붙이는 법」은 작품을 위쪽 귀퉁이부터 차례로 붙이라고 했어요.","answer":"O","reason_options":[{"t":"3번 줄에 위쪽 귀퉁이부터 차례로 붙인다고 적혀 있기 때문에","correct":true},{"t":"작품은 아무 데나 붙여야 보기 좋다고 했기 때문에","mis":"K3-2-u5-X17"}],"mis":"K3-2-u5-X17","explanation":["3번 줄을 봐요.","위쪽 귀퉁이부터예요.","그래서 O예요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#15','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C27',2,'error','auto','「단서 세 장」을 만들며 말했어요. 잘못 만든 친구는 누구인가요?',ARRAY['K3-2-u5-X29']::text[],false,'{"seq":15,"concept":"K3-2-u5-C27","difficulty":2,"kind":"error","stem":"「단서 세 장」을 만들며 말했어요. 잘못 만든 친구는 누구인가요?","options":[{"t":"친구 나 — 「둘째 장에 ‘호루라기’라고 낱말을 써 둘래.」","correct":true,"mis_target":"K3-2-u5-X29"},{"t":"친구 가 — 「첫째 장엔 이름을 나타내는 낱말이라고 쓸래.」","mis":"K3-2-u5-X29"},{"t":"친구 다 — 「셋째 장엔 낱말 자리를 비운 문장을 쓸래.」","mis":"K3-2-u5-X29"}],"explanation":["낱말을 그대로 쓰면 답이에요.","둘째 장엔 뜻을 써요.","친구 나가 잘못 만들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#16','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C28',2,'ox','auto','낱말 공책에는 그 낱말을 넣어 내가 쓴 문장도 적어요.',ARRAY['K3-2-u5-X30']::text[],false,'{"seq":16,"concept":"K3-2-u5-C28","difficulty":2,"kind":"ox","stem":"낱말 공책에는 그 낱말을 넣어 내가 쓴 문장도 적어요.","answer":"O","reason_options":[{"t":"내가 쓴 문장이 있으면 낱말을 어떻게 쓰는지 다시 떠올릴 수 있기 때문에","correct":true},{"t":"공책에는 낱말만 적어야 하기 때문에","mis":"K3-2-u5-X30"}],"mis":"K3-2-u5-X30","explanation":["낱말·종류·뜻·문장 넷이에요.","내가 쓴 문장도 들어가요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#17','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C14',3,'ox','auto','‘축축하다’는 성질이나 상태 칸에만 들어가는 낱말이라, 어떤 기준으로 나누어도 늘 같은 칸에 있어요.',ARRAY['K3-2-u5-X14']::text[],false,'{"seq":17,"concept":"K3-2-u5-C14","difficulty":3,"kind":"ox","stem":"‘축축하다’는 성질이나 상태 칸에만 들어가는 낱말이라, 어떤 기준으로 나누어도 늘 같은 칸에 있어요.","answer":"X","reason_options":[{"t":"기준이 바뀌면 모양이 바뀌는 칸이나 두 글자가 넘는 칸처럼 다른 칸에 들어가기 때문에","correct":true},{"t":"낱말마다 들어갈 칸은 하나로 정해져 있기 때문에","mis":"K3-2-u5-X14"}],"mis":"K3-2-u5-X14","explanation":["종류로는 성질·상태 칸이에요.","모양으로는 바뀌는 칸이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["선반 · 쌓다 · 축축하다 · 호루라기 · 감다","가지런하다 · 수건 · 넣다 · 높다"],"title":"「체육 창고 정리」에서 고른 낱말 아홉 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#18','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C12',3,'mc','auto','‘쌓다’를 기본형이라고 부르는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u5-X12','K3-2-u5-X11']::text[],false,'{"seq":18,"concept":"K3-2-u5-C12","difficulty":3,"kind":"mc","stem":"‘쌓다’를 기본형이라고 부르는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"바뀌지 않는 부분 ‘쌓’에 ‘-다’를 붙인, 사전에 싣는 대표 모양이라서","correct":true},{"t":"가장 바르게 쓴 모양이라서","mis":"K3-2-u5-X12"},{"t":"가장 자주 쓰는 모양이라서","mis":"K3-2-u5-X11"},{"t":"바뀐 모양 가운데 가장 짧아서","mis":"K3-2-u5-X11"}],"explanation":["기본형은 대표 모양이에요.","바른 모양이라는 뜻이 아니에요.","‘쌓’ + 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#19','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C23',3,'ox','auto','국어사전에 ‘찌그러졌고’가 실려 있지 않은 것은 사전이 뜻만 싣는 책이기 때문이에요.',ARRAY['K3-2-u5-X24']::text[],false,'{"seq":19,"concept":"K3-2-u5-C23","difficulty":3,"kind":"ox","stem":"국어사전에 ‘찌그러졌고’가 실려 있지 않은 것은 사전이 뜻만 싣는 책이기 때문이에요.","answer":"X","reason_options":[{"t":"사전은 뜻·읽는 법·쓰인 문장을 싣지만 바뀐 모양은 대표 모양 하나로만 싣기 때문에","correct":true},{"t":"사전에는 뜻 말고는 아무것도 실려 있지 않기 때문에","mis":"K3-2-u5-X24"}],"mis":"K3-2-u5-X24","explanation":["뜻만 싣는 책이 아니에요.","바뀐 모양은 기본형으로 실려요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#20','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C2',3,'ox','auto','모르는 낱말을 확인하는 까닭은 짐작이 맞았는지 틀렸는지 점수를 매기려는 거예요.',ARRAY['K3-2-u5-X26']::text[],false,'{"seq":20,"concept":"K3-2-u5-C2","difficulty":3,"kind":"ox","stem":"모르는 낱말을 확인하는 까닭은 짐작이 맞았는지 틀렸는지 점수를 매기려는 거예요.","answer":"X","reason_options":[{"t":"짐작한 뜻을 바로잡거나 확실히 알아 글을 정확하게 읽으려는 것이기 때문에","correct":true},{"t":"짐작이 틀리면 글을 다시 읽을 수 없기 때문에","mis":"K3-2-u5-X26"}],"mis":"K3-2-u5-X26","explanation":["점수를 매기는 일이 아니에요.","바로잡고 확실히 알려는 거예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#21','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C26',3,'error','auto','「게시판에 작품 붙이는 법」을 읽고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u5-X17']::text[],false,'{"seq":21,"concept":"K3-2-u5-C26","difficulty":3,"kind":"error","stem":"「게시판에 작품 붙이는 법」을 읽고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「테두리는 작품을 다 붙인 다음에 두르는 거야.」","correct":true,"mis_target":"K3-2-u5-X17"},{"t":"친구 가 — 「테두리를 먼저 두르면 가장자리가 또렷해.」","mis":"K3-2-u5-X17"},{"t":"친구 다 — 「위쪽 귀퉁이부터 차례로 붙여야 해.」","mis":"K3-2-u5-X17"}],"explanation":["1번 줄을 다시 읽어요.","붙이기 전에 먼저 둘러요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#22','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C18',3,'mc','auto','‘꿀벌 · 들 · 뜰 · 수건’을 국어사전에 실리는 차례대로 늘어놓은 것은 무엇인가요?',ARRAY['K3-2-u5-X19','K3-2-u5-X22']::text[],false,'{"seq":22,"concept":"K3-2-u5-C18","difficulty":3,"kind":"mc","stem":"‘꿀벌 · 들 · 뜰 · 수건’을 국어사전에 실리는 차례대로 늘어놓은 것은 무엇인가요?","options":[{"t":"꿀벌 → 들 → 뜰 → 수건","correct":true},{"t":"들 → 뜰 → 수건 → 꿀벌","mis":"K3-2-u5-X19"},{"t":"꿀벌 → 뜰 → 들 → 수건","mis":"K3-2-u5-X19"},{"t":"들 → 꿀벌 → 뜰 → 수건","mis":"K3-2-u5-X22"}],"explanation":["첫 자음자는 ㄲ·ㄷ·ㄸ·ㅅ이에요.","쌍자음자는 홑자음자 바로 뒤예요.","꿀벌 → 들 → 뜰 → 수건이에요."],"asset":{"type":"passage","lines":["ㄱ ㄲ ㄴ ㄷ ㄸ ㄹ ㅁ ㅂ ㅃ ㅅ ㅆ ㅇ ㅈ ㅉ ㅊ ㅋ ㅌ ㅍ ㅎ"],"title":"첫 자음자의 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#23','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C21',4,'mc','auto','낱말 공책에 모은 ‘눈썰매 · 눈사람 · 누리 · 눈’을 사전에 싣는 차례대로 적은 것은 무엇인가요?',ARRAY['K3-2-u5-X21','K3-2-u5-X19','K3-2-u5-X22']::text[],false,'{"seq":23,"concept":"K3-2-u5-C21","difficulty":4,"kind":"mc","stem":"낱말 공책에 모은 ‘눈썰매 · 눈사람 · 누리 · 눈’을 사전에 싣는 차례대로 적은 것은 무엇인가요?","options":[{"t":"누리 → 눈 → 눈사람 → 눈썰매","correct":true},{"t":"눈 → 누리 → 눈사람 → 눈썰매","mis":"K3-2-u5-X21"},{"t":"누리 → 눈 → 눈썰매 → 눈사람","mis":"K3-2-u5-X19"},{"t":"눈 → 눈사람 → 눈썰매 → 누리","mis":"K3-2-u5-X22"}],"explanation":["‘누’는 받침이 없어 먼저예요.","‘눈’ 뒤에 글자가 없는 ‘눈’이 그다음이에요.","눈사람(ㅅ) → 눈썰매(ㅆ)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#24','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C2',4,'essay','teacher','「게시판에 작품 붙이는 법」을 처음 읽는다고 생각하고, ‘귀퉁이’를 만났을 때 어떻게 읽을지 짐작·확인·다시 읽기의 순서로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u5-C2","difficulty":4,"kind":"essay","stem":"「게시판에 작품 붙이는 법」을 처음 읽는다고 생각하고, ‘귀퉁이’를 만났을 때 어떻게 읽을지 짐작·확인·다시 읽기의 순서로 쓰세요.","answer_guide":{"answer":"예: 먼저 멈추지 않고 “위쪽 귀퉁이부터 차례로 붙인다”의 앞뒤를 보며 ‘차례가 시작되는 끝자리’쯤으로 짐작하고 끝까지 읽는다. 다 읽은 뒤 국어사전에서 ‘귀퉁이’를 찾아 짐작이 맞는지 확인한다. 짐작이 빗나갔으면 사전의 뜻으로 고쳐 알고, 3번 줄을 다시 읽는다.","scoring_points":["앞뒤로 짐작하며 끝까지 읽는다고 썼는가","다 읽은 뒤 사전에서 확인한다고 썼는가","고쳐 알고 다시 읽는다고 썼는가"]},"explanation":["짐작하며 끝까지 읽어요.","그 뒤에 확인해요.","고쳐 알고 다시 읽어요."],"asset":{"type":"passage","lines":["1 게시판에 작품을 붙이기 전에 먼저 테두리를 두른다.","2 테두리가 있으면 게시판의 가장자리가 또렷해 보인다.","3 작품은 위쪽 귀퉁이부터 차례로 붙인다.","4 아무 데나 붙이면 작품들이 들쑥날쑥해 보인다.","5 다 붙인 뒤에는 한 걸음 물러서서 비뚤어진 작품이 없는지 살핀다."],"title":"설명하는 글 「게시판에 작품 붙이는 법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u5_review_d#25','kor',3,2,'u5','','g3_2_kor_u5_review_d','unit_review','K3-2-u5-C1',4,'essay','teacher','이 단원에서 배운 것 가운데 앞으로 책을 읽을 때 쓸 것 두 가지를 쓰고, 각각 어떻게 쓸지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u5-C1","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 것 가운데 앞으로 책을 읽을 때 쓸 것 두 가지를 쓰고, 각각 어떻게 쓸지 쓰세요.","answer_guide":{"answer":"예: 첫째, 모르는 낱말을 만나면 앞뒤로 짐작하며 끝까지 읽고 다 읽은 뒤에 사전에서 확인하겠다. 둘째, 모양이 바뀐 낱말은 바뀌지 않는 부분에 ‘-다’를 붙여 기본형으로 바꾸어 사전에서 찾겠다. 찾은 낱말은 낱말 공책에 사전 차례로 모아 두겠다.","scoring_points":["배운 것 두 가지를 썼는가","각각 어떻게 쓸지 구체적으로 썼는가","낱말을 다루는 일과 이어 썼는가"]},"explanation":["짐작하고 확인하기예요.","기본형으로 찾기예요.","책을 읽다 막히면 사전을 펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
